/** Real (unboosted) levels, plus what {@link Boosts} may assume on top of them. */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class CombatStats
{
	private int attack;
	private int strength;
	private int defence;
	private int ranged;
	private int magic;
	private int hitpoints;
	private int prayer;
	private int slayer;
	/** Assume the best offensive prayer and the standard potion for the style; off for plain level maths. */
	private boolean assumeBoosts;
	/** Knight Waves training ground done: unlocks Chivalry and Piety. */
	private boolean pietyUnlocked;
	private boolean rigourUnlocked;
	private boolean auguryUnlocked;
	private boolean deadeyeUnlocked;
	private boolean mysticVigourUnlocked;

	/** Levels only: no assumed boosts, no prayer unlocks. */
	public CombatStats(int attack, int strength, int defence, int ranged, int magic, int hitpoints, int prayer, int slayer)
	{
		this(attack, strength, defence, ranged, magic, hitpoints, prayer, slayer, false, false, false, false, false, false);
	}
}

package com.slayercompanion.gear;

import com.slayercompanion.data.Equipment;
import com.slayercompanion.data.Monster;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;

/**
 * DPS maths following the OSRS Wiki DPS calculator, integer rounding in its order. Assumed prayer and potion come from
 * {@link Boosts}, armour sets from {@link SetBonuses}, monster-specific weapon rules (immunities, dragon hunter,
 * demonbane, ...) from {@link WeaponEffects}.
 */
public final class DpsCalculator
{
	private static final Map<String, Integer> SPELL_MAX = new HashMap<>();
	private static final String[] ELEMENTS = {"wind", "water", "earth", "fire"};
	private static final String[] TIERS = {"strike", "bolt", "blast", "wave", "surge"};
	private static final int[] TIER_BASE = {2, 9, 13, 17, 21};

	static
	{
		for (int t = 0; t < TIERS.length; t++)
		{
			for (int e = 0; e < ELEMENTS.length; e++)
			{
				int max = t == 0 ? 2 + 2 * e : TIER_BASE[t] + e;
				SPELL_MAX.put(ELEMENTS[e] + " " + TIERS[t], max);
			}
		}
	}

	private DpsCalculator()
	{
	}

	/** Top hit as shown in game, after per-hit effects such as the berserker necklace. */
	public static int maxHit(CombatStats s, Loadout l, Monster m, boolean onTask)
	{
		return SetBonuses.shownMax(l, rawMax(s, l, m, onTask));
	}

	/** Max hit before per-hit set effects (the top of the uniform roll). */
	private static int rawMax(CombatStats s, Loadout l, Monster m, boolean onTask)
	{
		if (WeaponEffects.isImmune(l, m))
		{
			return 0;
		}
		switch (l.getStyle())
		{
			case RANGED:
				return rangedMax(s, l, onTask, m);
			case MAGIC:
				return magicMax(s, l, m, onTask);
			default:
				return meleeMax(s, l, m, onTask);
		}
	}

	public static double hitChance(CombatStats s, Loadout l, Monster m, boolean onTask)
	{
		return hitChance(attackRoll(s, l, m, onTask), defenceRoll(l, m));
	}

	public static double dps(CombatStats s, Loadout l, Monster m, boolean onTask)
	{
		if (WeaponEffects.isImmune(l, m))
		{
			return 0;
		}
		double hit = SetBonuses.expectedHit(l, hitChance(s, l, m, onTask), rawMax(s, l, m, onTask));
		return hit / (speedTicks(l) * 0.6);
	}

	/** Wiki hit chance from an attack roll and a defence roll. */
	public static double hitChance(long attackRoll, long defenceRoll)
	{
		if (attackRoll > defenceRoll)
		{
			return 1.0 - (defenceRoll + 2.0) / (2.0 * (attackRoll + 1.0));
		}
		return attackRoll / (2.0 * (defenceRoll + 1.0));
	}

	public static int speedTicks(Loadout l)
	{
		Equipment w = l.getBySlot().get("weapon");
		if (l.getStyle() == Style.MAGIC)
		{
			if (l.getSpell() != null)
			{
				return 5;
			}
			return w != null && w.getSpeedTicks() > 0 ? w.getSpeedTicks() : 4;
		}
		return w != null && w.getSpeedTicks() > 0 ? w.getSpeedTicks() : 4;
	}

	// ---- rolls ----

	static long attackRoll(CombatStats s, Loadout l, Monster m, boolean onTask)
	{
		switch (l.getStyle())
		{
			case RANGED:
			{
				// Accurate style: +3.
				long eff = Boosts.prayAccuracy(Boosts.ranged(s, Style.RANGED), Boosts.prayer(s, Style.RANGED)) + 3 + 8;
				if (SetBonuses.rangedVoid(l))
				{
					eff = eff * 11 / 10;
				}
				long roll = eff * (sum(l, "ranged") + 64);
				roll = roll * (20 + SetBonuses.crystalPieces(l)) / 20;
				return WeaponEffects.applyAccuracy(scale(roll, accuracyMult(l, m, onTask)), l, m);
			}
			case MAGIC:
			{
				long eff = Boosts.prayAccuracy(Boosts.magic(s, Style.MAGIC), Boosts.prayer(s, Style.MAGIC)) + 9;
				if (SetBonuses.magicVoid(l))
				{
					eff = eff * 29 / 20;
				}
				long roll = eff * (sum(l, "magic") + 64);
				long attack = WeaponEffects.applyAccuracy(scale(roll, accuracyMult(l, m, onTask)), l, m);
				if (weaknessApplies(l, m))
				{
					// Wiki: bonus is a percentage of the unmodified base roll, added last.
					attack += roll * m.getElementalWeaknessPercent() / 100;
				}
				return attack;
			}
			default:
			{
				// Aggressive style: +0 attack, +3 strength.
				long eff = Boosts.prayAccuracy(Boosts.attack(s, Style.MELEE), Boosts.prayer(s, Style.MELEE)) + 8;
				if (SetBonuses.meleeVoid(l))
				{
					eff = eff * 11 / 10;
				}
				long base = eff * (sum(l, meleeType(l)) + 64);
				long roll = scale(base, accuracyMult(l, m, onTask));
				if (SetBonuses.obsidian(l))
				{
					roll += base / 10;
				}
				roll = WeaponEffects.applyAccuracy(roll, l, m);
				return roll * (200 + SetBonuses.inquisitorBonus(l)) / 200;
			}
		}
	}

	static long defenceRoll(Loadout l, Monster m)
	{
		Map<String, Integer> d = m.getDefensiveBonuses();
		switch (l.getStyle())
		{
			case RANGED:
			{
				Equipment w = l.getBySlot().get("weapon");
				String key = w != null && "Thrown".equals(w.getCategory()) ? "light" : "standard";
				return (long) (m.getDefenceLevel() + 9) * (d.getOrDefault(key, 0) + 64);
			}
			case MAGIC:
				return (long) (m.getMagicLevel() + 9) * (d.getOrDefault("magic", 0) + 64);
			default:
				return (long) (m.getDefenceLevel() + 9) * (d.getOrDefault(meleeType(l), 0) + 64);
		}
	}

	// ---- max hits ----

	private static int meleeMax(CombatStats s, Loadout l, Monster m, boolean onTask)
	{
		long eff = Boosts.prayStrength(Boosts.strength(s, Style.MELEE), Boosts.prayer(s, Style.MELEE)) + 3 + 8;
		if (SetBonuses.meleeVoid(l))
		{
			eff = eff * 11 / 10;
		}
		int base = (int) ((eff * (sum(l, "str") + 64) + 320) / 640);
		int max = (int) scale(base, damageMult(l, m, onTask));
		if (SetBonuses.obsidian(l))
		{
			max += base / 10;
		}
		max = WeaponEffects.applyMaxHit(max, l, m, false);
		return max * (200 + SetBonuses.inquisitorBonus(l)) / 200;
	}

	private static int rangedMax(CombatStats s, Loadout l, boolean onTask, Monster m)
	{
		long eff = Boosts.prayStrength(Boosts.ranged(s, Style.RANGED), Boosts.prayer(s, Style.RANGED)) + 3 + 8;
		if (SetBonuses.eliteRangedVoid(l))
		{
			eff = eff * 9 / 8;
		}
		else if (SetBonuses.rangedVoid(l))
		{
			eff = eff * 11 / 10;
		}
		int base = (int) ((eff * (sum(l, "ranged_str") + 64) + 320) / 640);
		// Calculator (tested in game): the crystal armour bonus comes before the slayer helm.
		base = base * (40 + SetBonuses.crystalPieces(l)) / 40;
		// Wiki: with an imbued slayer helm, dragon hunter crossbow / scorching bow add to its 23/20 factor.
		int addend = WeaponEffects.rangedHelmAddend(l, m);
		boolean inHelm = addend > 0 && salveMult(l, m) == 1.0 && slayerHelmMult(l, onTask) > 1.0;
		int max = inHelm ? base * (23 + addend) / 20 : (int) scale(base, damageMult(l, m, onTask));
		return WeaponEffects.applyMaxHit(max, l, m, inHelm);
	}

	private static int magicMax(CombatStats s, Loadout l, Monster m, boolean onTask)
	{
		int base;
		if (WeaponEffects.MAGIC_DART.equalsIgnoreCase(l.getSpell()))
		{
			base = magicDartBase(Boosts.magic(s, Style.MAGIC), l, onTask);
		}
		else if (l.getSpell() != null)
		{
			Integer b = SPELL_MAX.get(l.getSpell().toLowerCase(Locale.ROOT));
			base = b == null ? 0 : b;
		}
		else
		{
			int magic = Boosts.magic(s, Style.MAGIC);
			Equipment w = l.getBySlot().get("weapon");
			String n = w == null || w.getName() == null ? "" : w.getName().toLowerCase(Locale.ROOT);
			if (n.startsWith("trident of the seas"))
			{
				base = magic / 3 - 5;
			}
			else if (n.startsWith("trident of the swamp"))
			{
				base = magic / 3 - 2;
			}
			else
			{
				return 0;
			}
		}
		if (base <= 0)
		{
			return 0;
		}
		// Gear, prayer and elite void magic damage add together, in tenths of a percent.
		int damage = sum(l, "magic_str") + Boosts.prayer(s, Style.MAGIC).getMagicDamage() + SetBonuses.magicDamageBonus(l);
		int boosted = WeaponEffects.applyMagicBase(base, l, m);
		int withBonus = boosted + boosted * damage / 1000;
		int max = WeaponEffects.applyMaxHit((int) scale(withBonus, damageMult(l, m, onTask)), l, m, false);
		if (weaknessApplies(l, m))
		{
			// Wiki: weakness is added last, as a percentage of the pre-bonus base max.
			max += base * m.getElementalWeaknessPercent() / 100;
		}
		return max;
	}

	/** Wiki: floor(magic / 10) + 10, or floor(magic / 6) + 13 with a Slayer's staff (e) on task; 0 without a valid staff. */
	private static int magicDartBase(int magic, Loadout l, boolean onTask)
	{
		Equipment w = l.getBySlot().get("weapon");
		if (w == null || !WeaponEffects.canCastMagicDart(w))
		{
			return 0;
		}
		boolean enchanted = w.getName().toLowerCase(Locale.ROOT).startsWith("slayer's staff (e)");
		return enchanted && onTask ? 13 + magic / 6 : 10 + magic / 10;
	}

	private static boolean weaknessApplies(Loadout l, Monster m)
	{
		if (l.getSpell() == null || m.getElementalWeakness() == null)
		{
			return false;
		}
		String first = l.getSpell().toLowerCase(Locale.ROOT).split(" ")[0];
		String element = "wind".equals(first) ? "air" : first;
		return element.equals(m.getElementalWeakness());
	}

	// ---- multipliers ----

	private static double accuracyMult(Loadout l, Monster m, boolean onTask)
	{
		return damageMult(l, m, onTask);
	}

	/** Salve beats the slayer helm (they do not stack); same value for accuracy and damage. */
	private static double damageMult(Loadout l, Monster m, boolean onTask)
	{
		double salve = salveMult(l, m);
		return salve > 1.0 ? salve : slayerHelmMult(l, onTask);
	}

	/** Slayer helmet / black mask on task: 7/6 melee; imbued 1.15 ranged and magic. */
	private static double slayerHelmMult(Loadout l, boolean onTask)
	{
		Equipment head = l.getBySlot().get("head");
		if (!onTask || head == null || head.getName() == null)
		{
			return 1.0;
		}
		String n = head.getName().toLowerCase(Locale.ROOT);
		if (!n.contains("slayer helmet") && !n.contains("black mask"))
		{
			return 1.0;
		}
		if (l.getStyle() == Style.MELEE)
		{
			return 7.0 / 6.0;
		}
		return n.contains("(i)") ? 1.15 : 1.0;
	}

	/** Salve amulet vs undead: 7/6 (1.2 enhanced) melee; imbued versions also for ranged and magic. */
	private static double salveMult(Loadout l, Monster m)
	{
		Equipment neck = l.getBySlot().get("neck");
		if (!m.isUndead() || neck == null || neck.getName() == null)
		{
			return 1.0;
		}
		String n = neck.getName().toLowerCase(Locale.ROOT).replace(" ", "");
		if (!n.startsWith("salveamulet"))
		{
			return 1.0;
		}
		boolean imbued = n.contains("(i)") || n.contains("(ei)");
		boolean enhanced = n.contains("(e)") || n.contains("(ei)");
		if (l.getStyle() == Style.MELEE)
		{
			return enhanced ? 1.2 : 7.0 / 6.0;
		}
		if (imbued)
		{
			return enhanced ? 1.2 : 1.15;
		}
		return 1.0;
	}

	// ---- helpers ----

	/**
	 * floor(v * mult) for the calculator's integer fractions (7/6, 23/20, 6/5): the nudge stops 26400 * 1.15 landing on
	 * 30359.999...; a real fraction of these is at least 1/20 off a whole number, so it is never rounded up.
	 */
	private static long scale(long v, double mult)
	{
		return mult == 1.0 ? v : (long) Math.floor(v * mult + 1e-6);
	}

	private static String meleeType(Loadout l)
	{
		return l.getMeleeType() == null ? "slash" : l.getMeleeType();
	}

	private static int sum(Loadout l, String key)
	{
		int total = 0;
		for (Equipment e : l.getBySlot().values())
		{
			if (e != null && e.getBonuses() != null)
			{
				total += e.getBonuses().getOrDefault(key, 0);
			}
		}
		return total;
	}
}

package com.slayercompanion.gear;

import com.slayercompanion.data.Equipment;
import com.slayercompanion.data.Monster;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;
import java.util.Collections;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import lombok.AllArgsConstructor;
import lombok.Value;

/**
 * Greedy per-slot best-in-slot search over owned items, plus a "biggest upgrade" suggestion. Set bonuses need several
 * pieces at once, so the search also starts from each complete owned set ({@link SetBonuses#ownedKits}), and an
 * upgrade that completes an owned set is valued with the rest of it.
 */
public class GearOptimizer
{
	private static final String[] SLOTS = {"head", "cape", "neck", "ammo", "body", "shield", "legs", "hands", "feet", "ring"};
	private static final String[] MELEE_TYPES = {"stab", "slash", "crush"};
	private static final String[][] SPELLS = {
		{"Wind Strike", "1"}, {"Water Strike", "5"}, {"Earth Strike", "9"}, {"Fire Strike", "13"},
		{"Wind Bolt", "17"}, {"Water Bolt", "23"}, {"Earth Bolt", "29"}, {"Fire Bolt", "35"},
		{"Wind Blast", "41"}, {"Water Blast", "47"}, {"Earth Blast", "53"}, {"Fire Blast", "59"},
		{"Wind Wave", "62"}, {"Water Wave", "65"}, {"Earth Wave", "70"}, {"Fire Wave", "75"},
		{"Wind Surge", "81"}, {"Water Surge", "90"}, {"Earth Surge", "95"}, {"Fire Surge", "99"}};
	/** Wiki: Magic Dart needs 50 Magic and 55 Slayer, and a staff from {@link WeaponEffects#canCastMagicDart}. */
	private static final int MAGIC_DART_MAGIC = 50;
	private static final int MAGIC_DART_SLAYER = 55;

	@Value
	@AllArgsConstructor
	public static class Upgrade
	{
		Equipment item;
		double dpsGainPercent;
	}

	private final Collection<Equipment> catalogue;

	public GearOptimizer(Collection<Equipment> catalogue)
	{
		this.catalogue = catalogue;
	}

	public Optional<Loadout> best(CombatStats stats, Style style, Monster m, boolean onTask, OwnedItems owned)
	{
		if (!owned.bankSeen())
		{
			return Optional.empty();
		}
		List<Equipment> pool = new ArrayList<>();
		for (Equipment e : catalogue)
		{
			if (e.getSlot() != null && owned.count(e.getItemId()) > 0 && meetsSkills(stats, e))
			{
				pool.add(e);
			}
		}
		List<Map<String, Equipment>> seeds = new ArrayList<>();
		seeds.add(Collections.emptyMap());
		seeds.addAll(SetBonuses.ownedKits(style, pool));
		// Shield vs two-hander interact, so search each family separately; keep the best over every start.
		Loadout best = null;
		double bestDps = -1;
		for (Map<String, Equipment> seed : seeds)
		{
			for (boolean twoHanded : new boolean[]{false, true})
			{
				Loadout l = search(stats, style, m, onTask, pool, twoHanded, seed);
				if (l == null)
				{
					continue;
				}
				double d = tune(stats, l, m, onTask);
				if (best == null || d > bestDps + 1e-9)
				{
					best = l;
					bestDps = d;
				}
			}
		}
		return Optional.of(best);
	}

	/** Greedy swaps from {@code seed} (a set to start in); null if the seed's weapon is the wrong hand count. */
	private Loadout search(CombatStats stats, Style style, Monster m, boolean onTask, List<Equipment> pool, boolean twoHanded,
		Map<String, Equipment> seed)
	{
		Loadout cur = new Loadout();
		cur.setStyle(style);
		for (Equipment e : seed.values())
		{
			if ("weapon".equals(e.getSlot()) && (e.isTwoHanded() != twoHanded || classify(e) != style))
			{
				return null;
			}
			cur = with(cur, e, pool, m);
		}
		double curDps = tune(stats, cur, m, onTask);
		for (int pass = 0; pass < 3; pass++)
		{
			boolean changed = false;
			// weapon first
			for (Equipment w : pool)
			{
				if (!"weapon".equals(w.getSlot()) || classify(w) != style || w.isTwoHanded() != twoHanded
					|| !ammoOk(cur, w, pool, m))
				{
					continue;
				}
				Loadout t = with(cur, w, pool, m);
				double d = tune(stats, t, m, onTask);
				if (d > curDps + 1e-9)
				{
					curDps = d;
					cur = t;
					changed = true;
				}
			}
			for (String slot : SLOTS)
			{
				if (cur.getBySlot().get("weapon") != null && cur.getBySlot().get("weapon").isTwoHanded() && "shield".equals(slot))
				{
					continue;
				}
				for (Equipment e : pool)
				{
					if (!slot.equals(e.getSlot()) || ("ammo".equals(slot) && !ammoCompatible(cur.getBySlot().get("weapon"), e)))
					{
						continue;
					}
					Loadout t = with(cur, e, pool, m);
					double d = tune(stats, t, m, onTask);
					if (d > curDps + 1e-9)
					{
						curDps = d;
						cur = t;
						changed = true;
					}
				}
			}
			if (!changed)
			{
				break;
			}
		}
		return cur;
	}

	public Optional<Upgrade> biggestUpgrade(CombatStats stats, Set<String> questsDone, Loadout current, Monster m,
		boolean onTask, OwnedItems owned)
	{
		Loadout base = copy(current);
		double baseDps = tune(stats, copy(base), m, onTask);
		List<Equipment> ownedPool = ownedPool(owned);
		Equipment bestItem = null;
		double bestDps = baseDps;
		for (Equipment e : catalogue)
		{
			if (e.getSlot() == null || owned.count(e.getItemId()) > 0 || !meetsSkills(stats, e) || !meetsQuests(questsDone, e))
			{
				continue;
			}
			Equipment curW = base.getBySlot().get("weapon");
			if ("shield".equals(e.getSlot()) && curW != null && curW.isTwoHanded())
			{
				continue;
			}
			if ("weapon".equals(e.getSlot()))
			{
				if (classify(e) != base.getStyle() || !ammoOk(base, e, ownedPool, m))
				{
					continue;
				}
			}
			if ("ammo".equals(e.getSlot()) && !ammoCompatible(curW, e))
			{
				continue;
			}
			double d = tune(stats, with(base, e, ownedPool, m), m, onTask);
			// Also with the owned rest of any set it completes (e.g. the void helm a player is missing).
			for (Map<String, Equipment> kit : SetBonuses.kitsCompletedBy(e, base.getStyle(), ownedPool))
			{
				Loadout t = base;
				for (Equipment piece : kit.values())
				{
					t = with(t, piece, ownedPool, m);
				}
				d = Math.max(d, tune(stats, t, m, onTask));
			}
			if (d > bestDps + 1e-9)
			{
				bestDps = d;
				bestItem = e;
			}
		}
		if (bestItem == null)
		{
			return Optional.empty();
		}
		// Both sides use the same assumed prayer and potion, so this is the gain the item gives a boosted player.
		double gain = baseDps <= 0 ? 100.0 : (bestDps - baseDps) / baseDps * 100.0;
		return Optional.of(new Upgrade(bestItem, gain));
	}

	// ---- helpers ----

	/** Picks the best melee type / spell for the loadout in place and returns its dps. */
	private static double tune(CombatStats s, Loadout l, Monster m, boolean onTask)
	{
		switch (l.getStyle())
		{
			case MELEE:
			{
				double best = -1;
				String bestType = "slash";
				for (String t : MELEE_TYPES)
				{
					l.setMeleeType(t);
					double d = DpsCalculator.dps(s, l, m, onTask);
					if (d > best + 1e-9)
					{
						best = d;
						bestType = t;
					}
				}
				l.setMeleeType(bestType);
				return best;
			}
			case MAGIC:
			{
				Equipment w = l.getBySlot().get("weapon");
				if (w != null && w.getName() != null && w.getName().toLowerCase(Locale.ROOT).startsWith("trident"))
				{
					l.setSpell(null);
					return DpsCalculator.dps(s, l, m, onTask);
				}
				double best = -1;
				String bestSpell = null;
				for (String[] sp : SPELLS)
				{
					if (s.getMagic() < Integer.parseInt(sp[1]))
					{
						continue;
					}
					l.setSpell(sp[0]);
					double d = DpsCalculator.dps(s, l, m, onTask);
					if (d > best + 1e-9)
					{
						best = d;
						bestSpell = sp[0];
					}
				}
				if (w != null && WeaponEffects.canCastMagicDart(w) && s.getMagic() >= MAGIC_DART_MAGIC
					&& s.getSlayer() >= MAGIC_DART_SLAYER)
				{
					l.setSpell(WeaponEffects.MAGIC_DART);
					double d = DpsCalculator.dps(s, l, m, onTask);
					if (d > best + 1e-9)
					{
						best = d;
						bestSpell = WeaponEffects.MAGIC_DART;
					}
				}
				l.setSpell(bestSpell);
				return Math.max(best, 0);
			}
			default:
				return DpsCalculator.dps(s, l, m, onTask);
		}
	}

	/** Copy of l with e in its slot; two-handers drop the shield; ammo weapons get the best ammo from pool. */
	private static Loadout with(Loadout l, Equipment e, List<Equipment> pool, Monster m)
	{
		Loadout t = copy(l);
		t.getBySlot().put(e.getSlot(), e);
		if ("weapon".equals(e.getSlot()))
		{
			if (e.isTwoHanded())
			{
				t.getBySlot().remove("shield");
			}
			String need = ammoNeeded(e);
			if (need == null)
			{
				t.getBySlot().remove("ammo");
			}
			else if (!ammoCompatible(e, t.getBySlot().get("ammo"))
				|| !WeaponEffects.ammoCanHurt(m, t.getBySlot().get("ammo")))
			{
				t.getBySlot().remove("ammo");
				Equipment a = bestAmmo(pool, e, m);
				if (a != null)
				{
					t.getBySlot().put("ammo", a);
				}
			}
		}
		return t;
	}

	private List<Equipment> ownedPool(OwnedItems owned)
	{
		List<Equipment> pool = new ArrayList<>();
		for (Equipment e : catalogue)
		{
			if (owned.count(e.getItemId()) > 0)
			{
				pool.add(e);
			}
		}
		return pool;
	}

	/** Strongest compatible ammo, preferring ammo that can hurt the monster at all (e.g. broad bolts vs Kurask). */
	private static Equipment bestAmmo(List<Equipment> pool, Equipment weapon, Monster m)
	{
		Equipment best = null;
		for (Equipment a : pool)
		{
			if ("ammo".equals(a.getSlot()) && ammoCompatible(weapon, a) && (best == null || betterAmmo(a, best, m)))
			{
				best = a;
			}
		}
		return best;
	}

	private static boolean betterAmmo(Equipment a, Equipment best, Monster m)
	{
		boolean hurts = WeaponEffects.ammoCanHurt(m, a);
		if (hurts != WeaponEffects.ammoCanHurt(m, best))
		{
			return hurts;
		}
		return a.getBonuses().getOrDefault("ranged_str", 0) > best.getBonuses().getOrDefault("ranged_str", 0);
	}

	/** True if the weapon can be used with the current ammo, or has/needs a compatible ammo in the pool. */
	private static boolean ammoOk(Loadout cur, Equipment w, List<Equipment> pool, Monster m)
	{
		if (ammoNeeded(w) == null)
		{
			return true;
		}
		return ammoCompatible(w, cur.getBySlot().get("ammo")) || bestAmmo(pool, w, m) != null;
	}

	/** Ammo family a weapon fires: arrow, bolt, javelin, ogre; null if it takes no (identifiable) ammo. */
	static String ammoNeeded(Equipment w)
	{
		if (w == null || classify(w) != Style.RANGED)
		{
			return null;
		}
		String c = w.getCategory() == null ? "" : w.getCategory().toLowerCase(Locale.ROOT);
		String n = w.getName() == null ? "" : w.getName().toLowerCase(Locale.ROOT);
		if (n.contains("ballista"))
		{
			return "javelin";
		}
		if (n.contains("ogre bow"))
		{
			return "ogre";
		}
		if (n.contains("crystal bow") || n.contains("faerdhinen") || n.contains("craw's bow") || n.contains("webweaver")
			|| n.contains("venator") || n.contains("atlatl") || n.contains("blowpipe"))
		{
			return null;
		}
		if (c.equals("crossbow"))
		{
			return "bolt";
		}
		if (c.equals("bow"))
		{
			return "arrow";
		}
		return null;
	}

	static String ammoType(Equipment a)
	{
		String n = a.getName() == null ? "" : a.getName().toLowerCase(Locale.ROOT);
		if (n.contains("javelin"))
		{
			return "javelin";
		}
		if (n.contains("brutal") || n.contains("ogre arrow"))
		{
			return "ogre";
		}
		if (n.contains("bolt"))
		{
			return "bolt";
		}
		if (n.contains("arrow"))
		{
			return "arrow";
		}
		return null;
	}

	/** Ammo is only compatible when both families are identified and equal. */
	private static boolean ammoCompatible(Equipment weapon, Equipment ammo)
	{
		String need = ammoNeeded(weapon);
		return need != null && ammo != null && need.equals(ammoType(ammo));
	}

	/** Combat style a weapon is used for; null if unsupported in v1 (e.g. non-trident powered staves). */
	static Style classify(Equipment w)
	{
		String c = w.getCategory() == null ? "" : w.getCategory().toLowerCase(Locale.ROOT);
		String n = w.getName() == null ? "" : w.getName().toLowerCase(Locale.ROOT);
		if (WeaponEffects.isMeleeStaff(w))
		{
			return Style.MELEE;
		}
		if (c.equals("powered staff"))
		{
			return n.startsWith("trident of the seas") || n.startsWith("trident of the swamp") ? Style.MAGIC : null;
		}
		if (c.equals("staff") || c.equals("bladed staff"))
		{
			return Style.MAGIC;
		}
		if (c.equals("bow") || c.equals("crossbow") || c.equals("thrown") || c.equals("chinchompas"))
		{
			return Style.RANGED;
		}
		if (c.isEmpty() || c.equals("unarmed") || c.equals("salamander") || c.equals("blaster") || c.equals("gun"))
		{
			return null;
		}
		return Style.MELEE;
	}

	private static Loadout copy(Loadout l)
	{
		return new Loadout(new java.util.HashMap<>(l.getBySlot()), l.getStyle(), l.getMeleeType(), l.getSpell());
	}

	private static boolean meetsSkills(CombatStats s, Equipment e)
	{
		for (java.util.Map.Entry<String, Integer> r : e.getSkillReqs().entrySet())
		{
			int have;
			switch (r.getKey().toLowerCase(Locale.ROOT))
			{
				case "attack": have = s.getAttack(); break;
				case "strength": have = s.getStrength(); break;
				case "defence": have = s.getDefence(); break;
				case "ranged": have = s.getRanged(); break;
				case "magic": have = s.getMagic(); break;
				case "hitpoints": have = s.getHitpoints(); break;
				case "prayer": have = s.getPrayer(); break;
				case "slayer": have = s.getSlayer(); break;
				default: have = Integer.MAX_VALUE; // non-combat skills are not tracked; assume met
			}
			if (have < r.getValue())
			{
				return false;
			}
		}
		return true;
	}

	private static boolean meetsQuests(Set<String> done, Equipment e)
	{
		return done.containsAll(e.getQuestReqs());
	}
}

package com.slayercompanion.gear;

import com.slayercompanion.data.Equipment;
import java.util.HashMap;
import java.util.Map;
import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@NoArgsConstructor
@AllArgsConstructor
public class Loadout
{
	private Map<String, Equipment> bySlot = new HashMap<>();
	private Style style = Style.MELEE;
	/** stab, slash or crush. */
	private String meleeType = "slash";
	/** e.g. "Water Wave"; null for powered staves or non-magic. */
	private String spell;
}

package com.slayercompanion.gear;

import com.slayercompanion.data.Monster;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

/**
 * Combat attributes the bundled monster data does not carry yet (draconic, demon and undead are on {@link Monster}).
 * Ids are the NPCs with the matching attribute in the OSRS Wiki DPS calculator's monster data.
 */
public final class MonsterTraits
{
	/** "leafy": Kurask and Turoth, only hurt by leaf-bladed weapons, broad ammo and Magic Dart. */
	private static final Set<Integer> LEAFY = ids(
		410, 411, 7405, // Kurask (normal, big), King kurask
		427, 428, 429, 430, 10397); // Turoth (dad, mum, child, baby), Spiked Turoth

	private static final Set<Integer> KALPHITE = ids(
		955, 957, 958, 959, 960, 962, 963, 965, // Kalphite worker, soldiers, guardians, queen
		7032, // Reanimated kalphite
		729, 794, 797, 799, 1127, 1782, 4192, 6343, 11508, 14126, // scarabs
		795, 796, 800, 801); // locust riders

	/** Vampyre tier: 1 any weapon, 2 silver weapons only, 3 Ivandis flail / blisterwood only. */
	private static final Map<Integer, Integer> VAMPYRE_TIER = new HashMap<>();

	static
	{
		tier(1,
			3137, 3234, 3237, 3707, 5640, 5641, 5642, // Feral vampyres
			3692, 4436, 9731, // Vampyre juveniles
			1128, 3459, 6344, 3481, 6332, 6393, 9560); // Dessous, Count Draynor, Kroy
		tier(2,
			3694, 4427, 4442, 4443, 5634, 5635, 5636, 9614, 9727); // Vampyre juvinates
		tier(3,
			3709, 3710, 3711, 3712, 8252, // Vyrewatch
			9756, 9757, 9758, 9759, 9760, 9761, 9762, 9763, // Vyrewatch sentinels
			8242, 8248, 9561, 9567, // Ranis Drakan, Damien Leucurte, Vanstrom Klause
			15765, 15766, 15767, 15768, 15769, 15770); // Venators

	}

	private MonsterTraits()
	{
	}

	public static boolean isLeafy(Monster m)
	{
		return LEAFY.contains(m.getId());
	}

	public static boolean isKalphite(Monster m)
	{
		return KALPHITE.contains(m.getId());
	}

	/** 1-3, or 0 when the monster is not a vampyre. */
	public static int vampyreTier(Monster m)
	{
		return VAMPYRE_TIER.getOrDefault(m.getId(), 0);
	}

	private static Set<Integer> ids(Integer... ids)
	{
		return new HashSet<>(Arrays.asList(ids));
	}

	private static void tier(int tier, int... ids)
	{
		for (int id : ids)
		{
			VAMPYRE_TIER.put(id, tier);
		}
	}
}

package com.slayercompanion.gear;

import com.google.gson.Gson;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;
import java.util.function.IntUnaryOperator;

/** Items the player has: bank + inventory + worn. Plain Java so it is unit-testable. */
public class OwnedItems
{

	private transient IntUnaryOperator canonical;
	private Map<Integer, Integer> bank = new HashMap<>();
	private Map<Integer, Integer> inventory = new HashMap<>();
	private Map<Integer, Integer> worn = new HashMap<>();
	private Long bankSeenEpochMillis;

	public OwnedItems()
	{
		this(IntUnaryOperator.identity());
	}

	/** @param canonical maps noted/placeholder ids to the base item id (ItemManager.canonicalize). */
	public OwnedItems(IntUnaryOperator canonical)
	{
		this.canonical = canonical;
	}

	public void updateBank(Map<Integer, Integer> items, Instant seen)
	{
		bank = canon(items);
		bankSeenEpochMillis = seen.toEpochMilli();
	}

	public void updateInventory(Map<Integer, Integer> items)
	{
		inventory = canon(items);
	}

	public void updateWorn(Map<Integer, Integer> items)
	{
		worn = canon(items);
	}

	public int count(int itemId)
	{
		int id = canonical.applyAsInt(itemId);
		return bank.getOrDefault(id, 0) + inventory.getOrDefault(id, 0) + worn.getOrDefault(id, 0);
	}

	/** Whether the item (or a variant of it) is equipped right now. */
	public boolean isWorn(int itemId)
	{
		return worn.getOrDefault(canonical.applyAsInt(itemId), 0) > 0;
	}

	public boolean bankSeen()
	{
		return bankSeenEpochMillis != null;
	}

	public Optional<Instant> bankSeenAt()
	{
		return bankSeenEpochMillis == null ? Optional.empty() : Optional.of(Instant.ofEpochMilli(bankSeenEpochMillis));
	}

	public String toJson(Gson gson)
	{
		return gson.toJson(this);
	}

	public static OwnedItems fromJson(Gson gson, String json)
	{
		return fromJson(gson, json, IntUnaryOperator.identity());
	}

	public static OwnedItems fromJson(Gson gson, String json, IntUnaryOperator canonical)
	{
		OwnedItems o = json == null || json.isEmpty() ? null : gson.fromJson(json, OwnedItems.class);
		if (o == null)
		{
			o = new OwnedItems();
		}
		o.canonical = canonical;
		if (o.bank == null)
		{
			o.bank = new HashMap<>();
		}
		if (o.inventory == null)
		{
			o.inventory = new HashMap<>();
		}
		if (o.worn == null)
		{
			o.worn = new HashMap<>();
		}
		return o;
	}

	private Map<Integer, Integer> canon(Map<Integer, Integer> in)
	{
		Map<Integer, Integer> out = new HashMap<>();
		in.forEach((id, qty) -> out.merge(canonical.applyAsInt(id), qty, Integer::sum));
		return out;
	}
}

package com.slayercompanion.gear;

import com.slayercompanion.data.Equipment;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Armour set bonuses as the OSRS Wiki DPS calculator models them: Void / Elite void, obsidian with Tzhaar weapons,
 * berserker necklace, Inquisitor's (crush), crystal armour with a crystal bow or Bow of Faerdhinen, and the Verac's,
 * Karil's and Ahrim's set effects. Dharok's assumes full Hitpoints (no bonus); Torag's and Guthan's do not change dps.
 * Names match by prefix, so "(or)", "(Normal)" and charge suffixes count; broken pieces never do.
 */
public final class SetBonuses
{
	private static final String[] VOID_TOP = {"void knight top", "elite void top"};
	private static final String[] VOID_ROBE = {"void knight robe", "elite void robe"};
	private static final String[] ELITE_TOP = {"elite void top"};
	private static final String[] ELITE_ROBE = {"elite void robe"};
	private static final String[] VOID_GLOVES = {"void knight gloves"};
	private static final String[] TZHAAR_WEAPONS = {"tzhaar-ket-em", "tzhaar-ket-om", "toktz-xil-ak", "toktz-xil-ek",
		"toktz-mej-tal"};
	private static final String DAMNED = "amulet of the damned";

	/** A set the optimizer can start from: slot -> name prefixes, best variant first. */
	static final class Kit
	{
		final Style style;
		final Map<String, String[]> pieces = new HashMap<>();

		Kit(Style style, Object... slotPrefixes)
		{
			this.style = style;
			for (int i = 0; i < slotPrefixes.length; i += 2)
			{
				pieces.put((String) slotPrefixes[i], (String[]) slotPrefixes[i + 1]);
			}
		}
	}

	private static final String[] ELITE_FIRST_TOP = {"elite void top", "void knight top"};
	private static final String[] ELITE_FIRST_ROBE = {"elite void robe", "void knight robe"};

	/** Sets whose bonus needs several pieces at once, which one-slot-at-a-time swaps cannot find. */
	static final List<Kit> KITS = Collections.unmodifiableList(Arrays.asList(
		voidKit(Style.MELEE, "void melee helm"),
		voidKit(Style.RANGED, "void ranger helm"),
		voidKit(Style.MAGIC, "void mage helm"),
		new Kit(Style.MELEE, "head", new String[]{"obsidian helmet"}, "body", new String[]{"obsidian platebody"},
			"legs", new String[]{"obsidian platelegs"}),
		new Kit(Style.MELEE, "head", new String[]{"inquisitor's great helm"}, "body", new String[]{"inquisitor's hauberk"},
			"legs", new String[]{"inquisitor's plateskirt"}),
		new Kit(Style.RANGED, "head", new String[]{"crystal helm"}, "body", new String[]{"crystal body"},
			"legs", new String[]{"crystal legs"}),
		new Kit(Style.MELEE, "weapon", new String[]{"verac's flail"}, "head", new String[]{"verac's helm"},
			"body", new String[]{"verac's brassard"}, "legs", new String[]{"verac's plateskirt"}),
		new Kit(Style.RANGED, "weapon", new String[]{"karil's crossbow"}, "head", new String[]{"karil's coif"},
			"body", new String[]{"karil's leathertop"}, "legs", new String[]{"karil's leatherskirt"},
			"neck", new String[]{DAMNED}),
		new Kit(Style.MAGIC, "weapon", new String[]{"ahrim's staff"}, "head", new String[]{"ahrim's hood"},
			"body", new String[]{"ahrim's robetop"}, "legs", new String[]{"ahrim's robeskirt"},
			"neck", new String[]{DAMNED})));

	private SetBonuses()
	{
	}

	private static Kit voidKit(Style style, String helm)
	{
		return new Kit(style, "head", new String[]{helm}, "body", ELITE_FIRST_TOP, "legs", ELITE_FIRST_ROBE,
			"hands", VOID_GLOVES);
	}

	// ---- void ----

	static boolean meleeVoid(Loadout l)
	{
		return voidRobes(l) && wears(l, "head", "void melee helm");
	}

	static boolean rangedVoid(Loadout l)
	{
		return voidRobes(l) && wears(l, "head", "void ranger helm");
	}

	static boolean eliteRangedVoid(Loadout l)
	{
		return rangedVoid(l) && eliteRobes(l);
	}

	static boolean magicVoid(Loadout l)
	{
		return voidRobes(l) && wears(l, "head", "void mage helm");
	}

	/** Elite magic void: +5% magic damage, in tenths of a percent like the gear bonus. */
	static int magicDamageBonus(Loadout l)
	{
		return magicVoid(l) && eliteRobes(l) ? 50 : 0;
	}

	private static boolean voidRobes(Loadout l)
	{
		return wears(l, "body", VOID_TOP) && wears(l, "legs", VOID_ROBE) && wears(l, "hands", VOID_GLOVES);
	}

	private static boolean eliteRobes(Loadout l)
	{
		return wears(l, "body", ELITE_TOP) && wears(l, "legs", ELITE_ROBE);
	}

	// ---- obsidian / berserker ----

	/** Full obsidian armour with a Tzhaar weapon: + floor(base / 10) to the base roll and base max hit. */
	static boolean obsidian(Loadout l)
	{
		return tzhaarWeapon(l) && wears(l, "head", "obsidian helmet") && wears(l, "body", "obsidian platebody")
			&& wears(l, "legs", "obsidian platelegs");
	}

	/** Berserker necklace with a Tzhaar weapon: every melee hit x 6/5. */
	static boolean berserker(Loadout l)
	{
		return l.getStyle() == Style.MELEE && tzhaarWeapon(l) && wears(l, "neck", "berserker necklace");
	}

	private static boolean tzhaarWeapon(Loadout l)
	{
		return wears(l, "weapon", TZHAAR_WEAPONS);
	}

	// ---- inquisitor / crystal ----

	/** Inquisitor's on crush: helm 1, hauberk 2, plateskirt 2, over 200; 0 otherwise. */
	static int inquisitorBonus(Loadout l)
	{
		if (l.getStyle() != Style.MELEE || !"crush".equals(l.getMeleeType()))
		{
			return 0;
		}
		return (wears(l, "head", "inquisitor's great helm") ? 1 : 0) + (wears(l, "body", "inquisitor's hauberk") ? 2 : 0)
			+ (wears(l, "legs", "inquisitor's plateskirt") ? 2 : 0);
	}

	/** Crystal helm 1, legs 2, body 3 with a crystal bow or Bow of Faerdhinen; 0 otherwise. */
	static int crystalPieces(Loadout l)
	{
		if (l.getStyle() != Style.RANGED || !wears(l, "weapon", "crystal bow", "bow of faerdhinen"))
		{
			return 0;
		}
		return (wears(l, "head", "crystal helm") ? 1 : 0) + (wears(l, "legs", "crystal legs") ? 2 : 0)
			+ (wears(l, "body", "crystal body") ? 3 : 0);
	}

	// ---- barrows ----

	private static boolean veracs(Loadout l)
	{
		return l.getStyle() == Style.MELEE && wears(l, "weapon", "verac's flail") && wears(l, "head", "verac's helm")
			&& wears(l, "body", "verac's brassard") && wears(l, "legs", "verac's plateskirt");
	}

	private static boolean karils(Loadout l)
	{
		return l.getStyle() == Style.RANGED && wears(l, "weapon", "karil's crossbow") && wears(l, "head", "karil's coif")
			&& wears(l, "body", "karil's leathertop") && wears(l, "legs", "karil's leatherskirt") && wears(l, "neck", DAMNED);
	}

	private static boolean ahrims(Loadout l)
	{
		return l.getStyle() == Style.MAGIC && l.getSpell() != null && wears(l, "weapon", "ahrim's staff")
			&& wears(l, "head", "ahrim's hood") && wears(l, "body", "ahrim's robetop") && wears(l, "legs", "ahrim's robeskirt")
			&& wears(l, "neck", DAMNED);
	}

	// ---- per-hit effects ----

	/** Max hit as shown: the berserker necklace scales every hit, so its top hit too. */
	static int shownMax(Loadout l, int max)
	{
		return berserker(l) ? max * 6 / 5 : max;
	}

	/**
	 * Average damage per attack from the hit chance and the max hit before per-hit effects, following the
	 * calculator's hit distributions (uniform 0..max on an accurate hit, then set effects).
	 */
	static double expectedHit(Loadout l, double hitChance, int max)
	{
		if (berserker(l))
		{
			return hitChance * mean(max, 6, 5, 0);
		}
		if (veracs(l))
		{
			// 25% of attacks ignore accuracy and hit 1..max+1.
			return 0.75 * hitChance * max / 2.0 + 0.25 * (max + 2) / 2.0;
		}
		if (karils(l))
		{
			// 25% of accurate hits add a second hitsplat of half the first.
			return hitChance * (max / 2.0 + 0.25 * mean(max, 1, 2, 0));
		}
		if (ahrims(l))
		{
			// 25% of hits deal 30% more.
			return hitChance * (0.75 * max / 2.0 + 0.25 * mean(max, 13, 10, 0));
		}
		return hitChance * max / 2.0;
	}

	/** Mean of floor(d * num / den) + add over d = 0..max. */
	private static double mean(int max, int num, int den, int add)
	{
		long total = 0;
		for (int d = 0; d <= max; d++)
		{
			total += d * num / den + add;
		}
		return (double) total / (max + 1);
	}

	// ---- optimizer seeds ----

	/** Owned, wearable kits for the style as slot -> item, best variant per slot; empty when none is complete. */
	static List<Map<String, Equipment>> ownedKits(Style style, List<Equipment> pool)
	{
		List<Map<String, Equipment>> out = new ArrayList<>();
		for (Kit k : KITS)
		{
			if (k.style != style)
			{
				continue;
			}
			Map<String, Equipment> found = complete(k, pool, null);
			if (found != null)
			{
				out.add(found);
			}
		}
		return out;
	}

	/**
	 * The other owned pieces of each kit that {@code item} belongs to, so an upgrade that completes a set is valued
	 * with the rest of it; one map per completable kit.
	 */
	static List<Map<String, Equipment>> kitsCompletedBy(Equipment item, Style style, List<Equipment> pool)
	{
		List<Map<String, Equipment>> out = new ArrayList<>();
		for (Kit k : KITS)
		{
			String[] prefixes = k.pieces.get(item.getSlot());
			if (k.style != style || prefixes == null || !matches(item, prefixes))
			{
				continue;
			}
			Map<String, Equipment> found = complete(k, pool, item);
			if (found != null)
			{
				out.add(found);
			}
		}
		return out;
	}

	/** Slot -> the best-variant pool item for every piece of the kit ({@code fixed} fills its own slot); else null. */
	private static Map<String, Equipment> complete(Kit k, List<Equipment> pool, Equipment fixed)
	{
		Map<String, Equipment> found = new HashMap<>();
		for (Map.Entry<String, String[]> piece : k.pieces.entrySet())
		{
			String slot = piece.getKey();
			Equipment e = fixed != null && slot.equals(fixed.getSlot()) ? fixed : bestVariant(pool, slot, piece.getValue());
			if (e == null)
			{
				return null;
			}
			found.put(slot, e);
		}
		return found;
	}

	/** First prefix with an owned wearable match wins (elite void before plain void). */
	private static Equipment bestVariant(List<Equipment> pool, String slot, String[] prefixes)
	{
		for (String p : prefixes)
		{
			for (Equipment e : pool)
			{
				if (slot.equals(e.getSlot()) && matches(e, p))
				{
					return e;
				}
			}
		}
		return null;
	}

	// ---- name matching ----

	private static boolean wears(Loadout l, String slot, String... prefixes)
	{
		return matches(l.getBySlot().get(slot), prefixes);
	}

	private static boolean matches(Equipment e, String... prefixes)
	{
		if (e == null || e.getName() == null)
		{
			return false;
		}
		String n = e.getName().toLowerCase(Locale.ROOT);
		// Broken void and fully degraded barrows pieces cannot be worn.
		if (n.contains("(broken)") || n.endsWith(" (0)"))
		{
			return false;
		}
		for (String p : prefixes)
		{
			if (n.startsWith(p))
			{
				return true;
			}
		}
		return false;
	}
}

package com.slayercompanion.gear;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * Bank tab layout for the recommended setup, in the style of Inventory Setups: the equipment paper-doll in
 * columns 0-2, then a blank row, then the items to bring. Positions index an 8-wide bank grid (row * 8 + col);
 * -1 marks an empty position.
 */
public final class SetupLayout
{
	public static final int COLUMNS = 8;
	public static final int EMPTY = -1;
	/** Rows used by the paper-doll (head row through gloves/boots/ring row). */
	static final int DOLL_ROWS = 5;

	private static final Map<String, Integer> SLOT_POS = new HashMap<>();

	static
	{
		SLOT_POS.put("head", pos(0, 1));
		SLOT_POS.put("cape", pos(1, 0));
		SLOT_POS.put("neck", pos(1, 1));
		SLOT_POS.put("ammo", pos(1, 2));
		SLOT_POS.put("weapon", pos(2, 0));
		SLOT_POS.put("body", pos(2, 1));
		SLOT_POS.put("shield", pos(2, 2));
		SLOT_POS.put("legs", pos(3, 1));
		SLOT_POS.put("hands", pos(4, 0));
		SLOT_POS.put("feet", pos(4, 1));
		SLOT_POS.put("ring", pos(4, 2));
	}

	private SetupLayout()
	{
	}

	static int pos(int row, int col)
	{
		return row * COLUMNS + col;
	}

	/** Bank position of an equipment slot ("head", "weapon", ...), or -1 for an unknown slot. */
	public static int slotPosition(String slot)
	{
		return SLOT_POS.getOrDefault(slot, EMPTY);
	}

	/**
	 * @param slotItems item id per equipment slot name (as in {@link Loadout#getBySlot()})
	 * @param bring     items to bring, in display order; duplicates and items already in the doll are skipped
	 * @return item id per bank position; empty when there is nothing to show
	 */
	public static int[] build(Map<String, Integer> slotItems, List<Integer> bring)
	{
		List<Integer> out = new ArrayList<>();
		Set<Integer> placed = new HashSet<>();
		for (Map.Entry<String, Integer> e : slotItems.entrySet())
		{
			int p = slotPosition(e.getKey());
			Integer id = e.getValue();
			if (p < 0 || id == null || id < 0)
			{
				continue;
			}
			set(out, p, id);
			placed.add(id);
		}

		// Bring items start on a fresh row, one blank row below the doll (or at the top when there is no gear).
		int next = placed.isEmpty() ? 0 : pos(DOLL_ROWS + 1, 0);
		for (Integer id : bring == null ? Collections.<Integer>emptyList() : bring)
		{
			if (id == null || id < 0 || !placed.add(id))
			{
				continue;
			}
			set(out, next++, id);
		}

		int[] layout = new int[out.size()];
		for (int i = 0; i < layout.length; i++)
		{
			layout[i] = out.get(i);
		}
		return layout;
	}

	private static void set(List<Integer> out, int pos, int id)
	{
		while (out.size() <= pos)
		{
			out.add(EMPTY);
		}
		out.set(pos, id);
	}
}

package com.slayercompanion.gear;

public enum Style
{
	MELEE, RANGED, MAGIC
}

package com.slayercompanion.gear;

import com.slayercompanion.data.Equipment;
import com.slayercompanion.data.Monster;
import java.util.Locale;

/**
 * Weapon effects that depend on the monster: which setups can hurt it at all (Kurask/Turoth, vampyres), and
 * the wiki DPS calculator's weapon-vs-attribute bonuses (dragon hunter, demonbane, keris, vampyrebane, leafy).
 * Factors are applied in the calculator's order, each one rounded down.
 */
public final class WeaponEffects
{
	public static final String MAGIC_DART = "Magic Dart";

	private static final String[] LEAF_BLADED = {"leaf-bladed battleaxe", "leaf-bladed spear", "leaf-bladed sword"};
	private static final String[] BROAD_AMMO = {"broad arrows", "broad bolts", "amethyst broad bolts", "seeking broad arrows"};
	private static final String[] MAGIC_DART_STAVES = {"slayer's staff", "staff of the dead", "toxic staff of the dead",
		"staff of light", "staff of balance"};
	/** Melee weapons that hurt tier 3 vampyres (and tier 2 at full damage). */
	private static final String[] VAMPYREBANE = {"ivandis flail", "blisterwood flail", "blisterwood sickle",
		"hallowed flail", "sunspear"};
	private static final String[] SILVER_MELEE = {"blessed axe", "ivandis flail", "blisterwood flail", "hallowed flail",
		"silver sickle", "emerald sickle", "ruby sickle", "enchanted emerald sickle", "enchanted ruby sickle",
		"blisterwood sickle", "silverlight", "darklight", "arclight", "rod of ivandis", "wolfbane"};
	/** Tier 2 vampyres take at most this per hit from silver weapons that are not Ivandis/Blisterwood. */
	private static final int SILVER_TIER_TWO_CAP = 10;

	private WeaponEffects()
	{
	}

	// ---- immunity ----

	/** True when nothing in this setup can damage the monster, so it must score 0 dps. */
	public static boolean isImmune(Loadout l, Monster m)
	{
		if (MonsterTraits.isLeafy(m) && !hurtsLeafy(l))
		{
			return true;
		}
		int tier = MonsterTraits.vampyreTier(m);
		if (tier == 3)
		{
			return !vampyrebane(l, false);
		}
		return tier == 2 && !vampyrebane(l, true) && !silver(l);
	}

	/** What the player must bring when a monster ignores ordinary weapons; null for ordinary monsters. */
	public static String immunityHint(Monster m)
	{
		if (MonsterTraits.isLeafy(m))
		{
			return "Needs a leaf-bladed weapon, broad ammo or Magic Dart";
		}
		switch (MonsterTraits.vampyreTier(m))
		{
			case 2:
				return "Needs a silver weapon, ideally an Ivandis flail or Blisterwood weapon";
			case 3:
				return "Needs an Ivandis flail or Blisterwood weapon";
			default:
				return null;
		}
	}

	/** Whether this ammo can hurt the monster at all, so the optimizer loads it instead of stronger useless ammo. */
	public static boolean ammoCanHurt(Monster m, Equipment ammo)
	{
		if (MonsterTraits.isLeafy(m))
		{
			return isAny(ammo, BROAD_AMMO);
		}
		int tier = MonsterTraits.vampyreTier(m);
		if (tier == 3)
		{
			return false;
		}
		return tier != 2 || isSilverBolts(ammo);
	}

	/** Magic Dart needs one of these staves wielded (plus 50 Magic and 55 Slayer, checked by the optimizer). */
	public static boolean canCastMagicDart(Equipment weapon)
	{
		return isAny(weapon, MAGIC_DART_STAVES);
	}

	/** Ivandis/Blisterwood flails and the Rod of Ivandis sit in the "Staff" category but are melee weapons. */
	static boolean isMeleeStaff(Equipment weapon)
	{
		return isAny(weapon, "ivandis flail", "blisterwood flail", "rod of ivandis");
	}

	private static boolean hurtsLeafy(Loadout l)
	{
		switch (l.getStyle())
		{
			case MELEE:
				return isAny(weapon(l), LEAF_BLADED);
			case RANGED:
				return isAny(l.getBySlot().get("ammo"), BROAD_AMMO);
			default:
				return MAGIC_DART.equalsIgnoreCase(l.getSpell());
		}
	}

	/** Weapons that deal full damage to vampyres; the Rod of Ivandis only counts for tier 2. */
	private static boolean vampyrebane(Loadout l, boolean tierTwo)
	{
		Equipment w = weapon(l);
		if (l.getStyle() == Style.RANGED)
		{
			return is(w, "blisterwood stake");
		}
		return l.getStyle() == Style.MELEE && (isAny(w, VAMPYREBANE) || tierTwo && is(w, "rod of ivandis"));
	}

	private static boolean silver(Loadout l)
	{
		if (l.getStyle() == Style.RANGED)
		{
			return is(weapon(l), "blisterwood stake") || isSilverBolts(l.getBySlot().get("ammo"));
		}
		return l.getStyle() == Style.MELEE && isAny(weapon(l), SILVER_MELEE);
	}

	private static boolean isSilverBolts(Equipment ammo)
	{
		return is(ammo, "silver bolts");
	}

	// ---- accuracy ----

	/** Applies weapon-vs-monster accuracy factors to an attack roll that already includes slayer helm / salve. */
	static long applyAccuracy(long roll, Loadout l, Monster m)
	{
		Equipment w = weapon(l);
		switch (l.getStyle())
		{
			case MELEE:
				if (m.isDemon())
				{
					roll = demonbane(roll, w);
				}
				if (m.isDragon() && is(w, "dragon hunter lance"))
				{
					roll = roll * 6 / 5;
				}
				if (MonsterTraits.isKalphite(m) && is(w, "keris partisan of breaching"))
				{
					roll = roll * 133 / 100;
				}
				if (MonsterTraits.vampyreTier(m) > 0)
				{
					if (isAny(w, "blisterwood flail", "blisterwood sickle"))
					{
						roll = roll * 105 / 100;
					}
					else if (isAny(w, "hallowed flail", "sunspear"))
					{
						roll = roll * 125 / 100;
					}
				}
				return roll;
			case RANGED:
				if (m.isDragon() && is(w, "dragon hunter crossbow"))
				{
					roll = roll * 13 / 10;
				}
				if (m.isDemon() && is(w, "scorching bow"))
				{
					roll = addPercent(roll, 30);
				}
				return roll;
			default:
				if (m.isDragon() && is(w, "dragon hunter wand"))
				{
					roll = roll * 7 / 4;
				}
				return roll;
		}
	}

	// ---- max hit ----

	/** Dragon hunter wand: +40% to the spell's base max hit vs draconic, before magic damage bonuses. */
	static int applyMagicBase(int base, Loadout l, Monster m)
	{
		return m.isDragon() && is(weapon(l), "dragon hunter wand") ? base * 7 / 5 : base;
	}

	/**
	 * Extra twentieths the ranged weapon adds to an imbued slayer helm's 23/20 instead of multiplying after it
	 * (dragon hunter crossbow +5, scorching bow +6); 0 when none applies.
	 */
	static int rangedHelmAddend(Loadout l, Monster m)
	{
		Equipment w = weapon(l);
		if (m.isDragon() && is(w, "dragon hunter crossbow"))
		{
			return 5;
		}
		return m.isDemon() && is(w, "scorching bow") ? 6 : 0;
	}

	/**
	 * Applies weapon-vs-monster damage factors to a max hit that already includes slayer helm / salve.
	 *
	 * @param rangedBonusInHelm the ranged weapon's bonus was already added into the imbued slayer helm factor
	 */
	static int applyMaxHit(int max, Loadout l, Monster m, boolean rangedBonusInHelm)
	{
		Equipment w = weapon(l);
		switch (l.getStyle())
		{
			case MELEE:
				if (m.isDemon() && !isAny(w, "silverlight", "darklight"))
				{
					max = (int) demonbane(max, w);
				}
				if (m.isDragon() && is(w, "dragon hunter lance"))
				{
					max = max * 6 / 5;
				}
				if (MonsterTraits.isKalphite(m) && is(w, "keris"))
				{
					max = is(w, "keris partisan of amascut") ? max * 115 / 100 : max * 133 / 100;
				}
				if (m.isDemon() && isAny(w, "silverlight", "darklight"))
				{
					max = (int) addPercent(max, 60);
				}
				if (MonsterTraits.isLeafy(m) && is(w, "leaf-bladed battleaxe"))
				{
					max = max * 47 / 40;
				}
				break;
			case RANGED:
				if (!rangedBonusInHelm && m.isDragon() && is(w, "dragon hunter crossbow"))
				{
					max = max * 5 / 4;
				}
				if (!rangedBonusInHelm && m.isDemon() && is(w, "scorching bow"))
				{
					max = (int) addPercent(max, 30);
				}
				break;
			default:
				break;
		}
		return vampyreDamage(max, l, MonsterTraits.vampyreTier(m));
	}

	/** Vampyrebane / silver damage bonuses, then the tier 2 cap for other silver weapons. */
	private static int vampyreDamage(int max, Loadout l, int tier)
	{
		if (tier == 0)
		{
			return max;
		}
		Equipment w = weapon(l);
		if (isAny(w, "blisterwood flail", "hallowed flail", "blisterwood stake"))
		{
			max = max * 125 / 100;
		}
		else if (is(w, "sunspear"))
		{
			max = max * 150 / 100;
		}
		else if (is(w, "blisterwood sickle"))
		{
			max = max * 23 / 20;
		}
		else if (is(w, "ivandis flail"))
		{
			max = max * 6 / 5;
		}
		else if (is(w, "rod of ivandis") && tier != 3)
		{
			max = max * 11 / 10;
		}
		else if (tier == 1 && silver(l))
		{
			max = max * 11 / 10;
		}
		if (tier == 2 && !vampyrebane(l, true) && silver(l))
		{
			max = Math.min(max, SILVER_TIER_TWO_CAP);
		}
		return max;
	}

	/** Melee demonbane: Arclight/Emberlight +70%, Silverlight/Darklight +60%, bone/burning claws +5%. */
	private static long demonbane(long value, Equipment w)
	{
		if (isAny(w, "arclight", "emberlight") && !is(w, "arclight (inactive)"))
		{
			return addPercent(value, 70);
		}
		if (isAny(w, "silverlight", "darklight"))
		{
			return addPercent(value, 60);
		}
		if (isAny(w, "bone claws", "burning claws"))
		{
			return addPercent(value, 5);
		}
		return value;
	}

	/** Wiki "add factor": value + floor(value * percent / 100). */
	private static long addPercent(long value, int percent)
	{
		return value + value * percent / 100;
	}

	// ---- name matching ----

	private static Equipment weapon(Loadout l)
	{
		return l.getBySlot().get("weapon");
	}

	/** Case-insensitive prefix match, so "Arclight (Charged)" and "Rod of Ivandis (5)" match their base names. */
	private static boolean is(Equipment e, String prefix)
	{
		return e != null && e.getName() != null && e.getName().toLowerCase(Locale.ROOT).startsWith(prefix);
	}

	private static boolean isAny(Equipment e, String... prefixes)
	{
		for (String p : prefixes)
		{
			if (is(e, p))
			{
				return true;
			}
		}
		return false;
	}
}

package com.slayercompanion.integration;

import java.util.Map;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.PluginManager;

/** Asks the Shortest Path plugin (if installed and enabled) to draw or time a route, via PluginMessage. */
public class ShortestPath
{
	private static final String PLUGIN_NAME = "Shortest Path";
	public static final String NAMESPACE = "shortestpath";
	/** Shortest Path's answer to a {@link #query}; carries the query's "id" and the route "cost" in ticks. */
	public static final String RESULT = "result";

	private final EventBus eventBus;
	private final PluginManager pluginManager;

	public ShortestPath(EventBus eventBus, PluginManager pluginManager)
	{
		this.eventBus = eventBus;
		this.pluginManager = pluginManager;
	}

	/** True when a plugin named "Shortest Path" is loaded and enabled. */
	public boolean available()
	{
		return pluginManager.getPlugins().stream()
			.anyMatch(p -> PLUGIN_NAME.equals(p.getName()) && pluginManager.isPluginEnabled(p));
	}

	/** Requests a path from the player's location to target; false (nothing posted) if unavailable. */
	public boolean pathTo(WorldPoint target)
	{
		if (target == null || !available())
		{
			return false;
		}
		eventBus.post(new PluginMessage(NAMESPACE, "path", Map.of("target", target)));
		return true;
	}

	/**
	 * Finds a route from the player's location to target without drawing it; Shortest Path answers with a
	 * {@link #RESULT} message carrying this id. False (nothing posted) if unavailable.
	 */
	public boolean query(String id, WorldPoint target)
	{
		if (target == null || !available())
		{
			return false;
		}
		eventBus.post(new PluginMessage(NAMESPACE, "query", Map.of("id", id, "target", target)));
		return true;
	}
}

package com.slayercompanion.integration;

import com.slayercompanion.data.Location;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.OptionalDouble;
import java.util.Set;
import net.runelite.api.coords.WorldPoint;

/**
 * Route times to each location from Shortest Path's "query" API, so travel accounts for the player's
 * teleports, fairy rings and transport. Until an answer arrives (or without Shortest Path) callers fall
 * back to a straight-line estimate. Client thread only.
 */
public class TravelTimes
{
	static final double SECONDS_PER_TICK = 0.6;
	/** Ask again once the player is this many tiles from where the last routes started. */
	static final int REQUERY_TILES = 30;
	private static final String ID_PREFIX = "slayercompanion:";

	private final Map<String, Double> seconds = new HashMap<>();
	private Set<String> askedFor = Collections.emptySet();
	private WorldPoint askedFrom;
	private int generation;

	/**
	 * Queries routes when the locations changed or the player moved far (or teleported) since the last ask.
	 * Earlier answers stay in use until the new ones arrive.
	 */
	public void refresh(List<Location> locations, WorldPoint player, ShortestPath shortestPath)
	{
		Set<String> ids = new HashSet<>();
		locations.forEach(l -> ids.add(l.getId()));
		if (player == null || ids.isEmpty() || (ids.equals(askedFor) && !movedFar(player)))
		{
			return;
		}
		if (!shortestPath.available())
		{
			seconds.clear();
			askedFor = Collections.emptySet();
			return;
		}
		askedFor = ids;
		askedFrom = player;
		generation++;
		for (Location l : locations)
		{
			if (l.routeTarget() != null)
			{
				shortestPath.query(ID_PREFIX + generation + ":" + l.getId(), l.routeTarget().toWorldPoint());
			}
		}
	}

	/**
	 * Stores the route time from a Shortest Path "result" message if it answers this class's latest queries.
	 * @return true when a time was stored, so the ranking should be rebuilt
	 */
	public boolean onResult(Map<String, Object> data)
	{
		Object id = data == null ? null : data.get("id");
		String prefix = ID_PREFIX + generation + ":";
		if (!(id instanceof String) || !((String) id).startsWith(prefix))
		{
			return false;
		}
		Object cost = data.get("cost");
		if (!Boolean.TRUE.equals(data.get("reached")) || !(cost instanceof Number) || ((Number) cost).intValue() < 0)
		{
			return false;
		}
		seconds.put(((String) id).substring(prefix.length()), ((Number) cost).intValue() * SECONDS_PER_TICK);
		return true;
	}

	/** The routed travel time to this location, if Shortest Path has answered. */
	public OptionalDouble seconds(String locationId)
	{
		Double s = seconds.get(locationId);
		return s == null ? OptionalDouble.empty() : OptionalDouble.of(s);
	}

	/** The player has moved far (or teleported) since routes were last asked for, so they should be asked again. */
	public boolean isStale(WorldPoint player)
	{
		return askedFrom != null && player != null && movedFar(player);
	}

	private boolean movedFar(WorldPoint player)
	{
		return askedFrom == null || player.getPlane() != askedFrom.getPlane()
			|| Math.max(Math.abs(player.getX() - askedFrom.getX()), Math.abs(player.getY() - askedFrom.getY())) > REQUERY_TILES;
	}
}

package com.slayercompanion.locations;

import com.slayercompanion.data.Drop;
import com.slayercompanion.data.Location;
import com.slayercompanion.data.Monster;
import java.util.function.IntToLongFunction;

public final class Estimates
{
	private Estimates()
	{
	}

	public static double killsPerHour(double dps, Monster monster, Location location)
	{
		if (dps <= 0)
		{
			return 0;
		}
		double secondsPerKill = monster.getHitpoints() / dps + location.getOverheadSeconds();
		return 3600 / secondsPerKill * location.getKillSpeedFactor();
	}

	public static double xpPerHour(double killsPerHour, Monster monster)
	{
		return killsPerHour * monster.getSlayerXp();
	}

	public static double gpPerKill(Monster monster, IntToLongFunction price)
	{
		double total = 0;
		for (Drop d : monster.getDrops())
		{
			total += d.getRate() * (d.getQtyMin() + d.getQtyMax()) / 2.0 * price.applyAsLong(d.getItemId());
		}
		return total;
	}

	public static double gpPerHour(double killsPerHour, double gpPerKill, Location location)
	{
		return killsPerHour * (gpPerKill + location.getBonusGpPerKill());
	}
}

package com.slayercompanion.locations;

import com.slayercompanion.data.Location;
import com.slayercompanion.data.WorldPointDto;
import com.slayercompanion.gear.Style;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.OptionalDouble;
import java.util.function.Function;
import java.util.function.ToDoubleFunction;
import net.runelite.api.coords.WorldPoint;

public final class LocationRanker
{
	static final double SECONDS_PER_TILE = 0.3;
	static final double FAR_TRAVEL_SECONDS = 120;
	static final double PLANE_CHANGE_SECONDS = 30;
	/** Underground areas mostly sit 6400 tiles north of the overworld spot they lie under. */
	static final int UNDERGROUND_Y_OFFSET = 6400;
	static final String KONAR_REASON = "Not your Konar location";

	private LocationRanker()
	{
	}

	/**
	 * @param lockReason empty when the location is usable, otherwise the first unmet requirement
	 *                   (e.g. "Needs boots of stone").
	 */
	public static List<RankedLocation> rank(List<Location> locations, Style style, WorldPoint player,
		Function<Location, Optional<String>> lockReason, Optional<String> konarLocation,
		Function<Location, Boolean> hasSafespot, ToDoubleFunction<Location> xpHr, ToDoubleFunction<Location> gpHr)
	{
		return rank(locations, style, player, lockReason, konarLocation, hasSafespot, xpHr, gpHr,
			l -> OptionalDouble.empty());
	}

	/** @param routedSeconds Shortest Path's route time per location; the straight-line estimate is used where empty */
	public static List<RankedLocation> rank(List<Location> locations, Style style, WorldPoint player,
		Function<Location, Optional<String>> lockReason, Optional<String> konarLocation,
		Function<Location, Boolean> hasSafespot, ToDoubleFunction<Location> xpHr, ToDoubleFunction<Location> gpHr,
		Function<Location, OptionalDouble> routedSeconds)
	{
		boolean konarActive = konarLocation.isPresent() && locations.stream().anyMatch(l -> matchesKonar(l, konarLocation.get()));
		boolean safespotMatters = style != Style.MELEE;

		List<RankedLocation> out = new ArrayList<>();
		for (Location l : locations)
		{
			RankedLocation r = new RankedLocation();
			r.setLocation(l);
			Optional<String> reason = konarActive && !matchesKonar(l, konarLocation.get())
				? Optional.of(KONAR_REASON)
				: lockReason.apply(l);
			r.setUsable(!reason.isPresent());
			r.setLockedReason(reason.orElse(null));
			r.setHasSafespot(Boolean.TRUE.equals(hasSafespot.apply(l)));
			OptionalDouble routed = routedSeconds.apply(l);
			r.setTravelRouted(routed.isPresent());
			r.setTravelSeconds(routed.isPresent() ? routed.getAsDouble() : travelSeconds(player, l.getEntrance()));
			r.setXpPerHour(xpHr.applyAsDouble(l));
			r.setGpPerHour(gpHr.applyAsDouble(l));
			out.add(r);
		}

		Comparator<RankedLocation> order = Comparator.comparing((RankedLocation r) -> !r.isUsable());
		if (safespotMatters)
		{
			order = order.thenComparing(r -> !r.isHasSafespot());
		}
		order = order.thenComparingDouble(RankedLocation::getTravelSeconds);
		out.sort(order);

		if (!out.isEmpty() && out.get(0).isUsable())
		{
			RankedLocation top = out.get(0);
			top.setRecommended(true);
			boolean strictlyClosest = out.stream().skip(1).filter(RankedLocation::isUsable)
				.allMatch(r -> top.getTravelSeconds() < r.getTravelSeconds());
			List<String> reasons = new ArrayList<>();
			if (safespotMatters && top.isHasSafespot())
			{
				reasons.add("Safespot");
			}
			if (strictlyClosest)
			{
				reasons.add("Closest");
			}
			top.setWhy(reasons.isEmpty() ? "Best available" : String.join(" · ", reasons));
		}
		return out;
	}

	/**
	 * Coarse estimate: Chebyshev distance between overworld-equivalent points x 0.3 s, plus a fixed
	 * penalty when the level differs (another plane, or going above/below ground). The player point
	 * is expected in template space already (WorldPoint.fromLocalInstance), so instances are handled.
	 */
	static double travelSeconds(WorldPoint player, WorldPointDto entrance)
	{
		if (entrance == null)
		{
			return FAR_TRAVEL_SECONDS;
		}
		boolean playerUnder = isUnderground(player.getY());
		boolean entranceUnder = isUnderground(entrance.getY());
		int dx = Math.abs(player.getX() - entrance.getX());
		int dy = Math.abs(overworldY(player.getY()) - overworldY(entrance.getY()));
		double seconds = Math.max(dx, dy) * SECONDS_PER_TILE;
		if (player.getPlane() != entrance.getPlane() || playerUnder != entranceUnder)
		{
			seconds += PLANE_CHANGE_SECONDS;
		}
		return seconds;
	}

	private static boolean isUnderground(int y)
	{
		return y >= UNDERGROUND_Y_OFFSET;
	}

	private static int overworldY(int y)
	{
		return isUnderground(y) ? y - UNDERGROUND_Y_OFFSET : y;
	}

	private static boolean matchesKonar(Location l, String konar)
	{
		if (l.getName() == null)
		{
			return false;
		}
		String a = l.getName().toLowerCase(Locale.ROOT);
		String b = konar.toLowerCase(Locale.ROOT);
		return a.contains(b) || b.contains(a);
	}
}

