package com.slayercompanion.safespot;

import com.slayercompanion.data.Location;
import com.slayercompanion.data.Safespot;
import com.slayercompanion.data.WorldPointDto;
import java.util.Collections;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.MenuAction;
import net.runelite.api.Player;
import net.runelite.api.Tile;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.chatbox.ChatboxPanelManager;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.util.ColorUtil;

/**
 * Adds safespot options on the "Walk here" entry, modelled on RuneLite's Ground Markers plugin:
 * shift + right-click offers "Mark safespot"; a tile with a shown spot offers "Safespot looks right" (unverified
 * builtin only) and "Wrong safespot", each targeting "Slayer Companion". Existing menu entries are never changed or removed.
 */
public class SafespotMenu
{
	private static final String WALK_HERE = "Walk here";
	private static final String MARK = "Mark safespot";
	private static final String LOOKS_RIGHT = "Safespot looks right";
	private static final String WRONG_SPOT = "Wrong safespot";
	private static final String TARGET = ColorUtil.wrapWithColorTag("Slayer Companion", JagexColors.MENU_TARGET);
	/** A mark goes to the task location whose entrance is within this many tiles of the player. */
	static final int NEAR_ENTRANCE_TILES = 150;

	private final Client client;
	private final SafespotStore store;
	private final ChatboxPanelManager chatboxPanelManager;

	private volatile String locationId;
	private volatile int monsterId;
	private volatile Location selected;
	private volatile List<Location> taskLocations = Collections.emptyList();
	private Runnable onChange = () -> { };

	@Inject
	public SafespotMenu(Client client, SafespotStore store, ChatboxPanelManager chatboxPanelManager)
	{
		this.client = client;
		this.store = store;
		this.chatboxPanelManager = chatboxPanelManager;
	}

	/**
	 * Sets the selected location and monster plus every location of the current task;
	 * a null selected location disables the menu.
	 */
	public void setContext(Location selected, int monsterId, List<Location> taskLocations)
	{
		this.selected = selected;
		this.locationId = selected == null ? null : selected.getId();
		this.monsterId = monsterId;
		this.taskLocations = taskLocations == null ? Collections.emptyList() : taskLocations;
	}

	/**
	 * The task location whose entrance is nearest the player (Chebyshev, same plane, within
	 * {@link #NEAR_ENTRANCE_TILES}); the selected location when none is that close.
	 */
	static Location locationForMark(List<Location> taskLocations, Location selected, WorldPoint player)
	{
		if (player == null)
		{
			return selected;
		}
		Location best = null;
		int bestDist = Integer.MAX_VALUE;
		for (Location l : taskLocations)
		{
			WorldPointDto e = l.getEntrance();
			if (e == null || e.getPlane() != player.getPlane())
			{
				continue;
			}
			int dist = Math.max(Math.abs(e.getX() - player.getX()), Math.abs(e.getY() - player.getY()));
			if (dist <= NEAR_ENTRANCE_TILES && dist < bestDist)
			{
				best = l;
				bestDist = dist;
			}
		}
		return best != null ? best : selected;
	}

	/** Called after any store change so the owner can persist {@link SafespotStore#toJson()}. */
	public void setOnChange(Runnable onChange)
	{
		this.onChange = onChange == null ? () -> { } : onChange;
	}

	@Subscribe
	public void onMenuEntryAdded(MenuEntryAdded event)
	{
		String loc = locationId;
		if (loc == null || event.getType() != MenuAction.WALK.getId() || !WALK_HERE.equals(event.getOption()))
		{
			return;
		}
		Tile tile = client.getSelectedSceneTile();
		if (tile == null)
		{
			return;
		}
		WorldPoint wp = WorldPoint.fromLocalInstance(client, tile.getLocalLocation());

		// wp is in template space, the same space spots are stored in.
		Safespot shown = store.spotAt(loc, wp);

		if (shown != null)
		{
			if (!shown.isVerified() && "builtin".equals(shown.getSource()))
			{
				addEntry(LOOKS_RIGHT, () ->
				{
					store.confirm(wp);
					onChange.run();
				});
			}
			addEntry(WRONG_SPOT, () ->
			{
				store.reject(wp);
				onChange.run();
			});
		}
		else if (client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			Location target = locationForMark(taskLocations, selected, playerPoint());
			if (target == null)
			{
				return;
			}
			int monster = target == selected ? monsterId : target.getMonsterId();
			addEntry(MARK, () -> promptNote(target, monster, wp));
		}
	}

	private void addEntry(String option, Runnable action)
	{
		client.getMenu().createMenuEntry(-1)
			.setOption(option)
			.setTarget(TARGET)
			.setType(MenuAction.RUNELITE)
			.onClick(e -> action.run());
	}

	private WorldPoint playerPoint()
	{
		Player p = client.getLocalPlayer();
		return p == null ? null : WorldPoint.fromLocalInstance(client, p.getLocalLocation());
	}

	private void promptNote(Location loc, int monster, WorldPoint wp)
	{
		chatboxPanelManager.openTextInput("Safespot note for " + loc.getName() + " (optional)")
			.onDone(note ->
			{
				store.mark(loc.getId(), monster, wp, note);
				onChange.run();
			})
			.build();
	}
}

package com.slayercompanion.safespot;

import com.slayercompanion.data.Safespot;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.OverlayUtil;

/** Outlines the current location's safespot tiles: solid when verified, dashed when not. */
public class SafespotOverlay extends Overlay
{
	private static final Color VERIFIED = new Color(0, 200, 0);
	private static final Color UNVERIFIED = new Color(255, 200, 0);
	private static final Stroke SOLID = new BasicStroke(2f);
	private static final Stroke DASHED = new BasicStroke(2f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER,
		10f, new float[]{6f, 4f}, 0f);
	private static final int MAX_DRAW_DISTANCE = 32;

	private final Client client;
	private final SafespotStore store;
	private volatile String locationId;

	@Inject
	public SafespotOverlay(Client client, SafespotStore store)
	{
		this.client = client;
		this.store = store;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
		setPriority(OverlayPriority.LOW);
	}

	public void setLocationId(String locationId)
	{
		this.locationId = locationId;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		String loc = locationId;
		if (loc == null || client.getLocalPlayer() == null
			|| !client.getLocalPlayer().getWorldView().isTopLevel())
		{
			return null;
		}
		WorldPoint playerPos = client.getLocalPlayer().getWorldLocation();
		for (Safespot spot : store.forLocation(loc))
		{
			// Spots are stored in template (non-instance) coordinates; map to the real scene like Ground Markers.
			for (WorldPoint wp : WorldPoint.toLocalInstance(client.getTopLevelWorldView(), spot.getTile().toWorldPoint()))
			{
				if (wp.getPlane() != client.getTopLevelWorldView().getPlane() || wp.distanceTo(playerPos) >= MAX_DRAW_DISTANCE)
				{
					continue;
				}
				LocalPoint lp = LocalPoint.fromWorld(client.getTopLevelWorldView(), wp);
				if (lp == null)
				{
					continue;
				}
				Polygon poly = canvasPoly(lp);
				if (poly != null)
				{
					Color c = spot.isVerified() ? VERIFIED : UNVERIFIED;
					OverlayUtil.renderPolygon(graphics, poly, c, new Color(c.getRed(), c.getGreen(), c.getBlue(), 40),
						spot.isVerified() ? SOLID : DASHED);
				}
			}
		}
		return null;
	}

	private Polygon canvasPoly(LocalPoint lp)
	{
		return Perspective.getCanvasTilePoly(client, lp);
	}
}

package com.slayercompanion.safespot;

import com.google.gson.Gson;
import com.google.gson.JsonParseException;
import com.slayercompanion.data.Safespot;
import com.slayercompanion.data.WorldPointDto;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;
import java.util.stream.Collectors;
import net.runelite.api.coords.WorldPoint;

/** Builtin safespots plus the player's own marks and verify/reject decisions. */
public class SafespotStore
{
	/** Persisted form: only what the player changed. */
	private static class Saved
	{
		List<Safespot> player = new ArrayList<>();
		List<WorldPointDto> confirmed = new ArrayList<>();
		List<WorldPointDto> rejected = new ArrayList<>();
	}

	private final Gson gson;
	private final List<Safespot> builtin;
	private final List<Safespot> player = new ArrayList<>();
	private final Set<WorldPoint> confirmed = new LinkedHashSet<>();
	private final Set<WorldPoint> rejected = new LinkedHashSet<>();

	public SafespotStore(Gson gson, List<Safespot> builtin, String savedJson)
	{
		this.gson = gson;
		this.builtin = new ArrayList<>(builtin);
		load(savedJson);
	}

	/** Replaces the player's marks and decisions with saved JSON (e.g. after switching account). */
	public void load(String savedJson)
	{
		player.clear();
		confirmed.clear();
		rejected.clear();
		if (savedJson == null || savedJson.trim().isEmpty())
		{
			return;
		}
		try
		{
			Saved saved = gson.fromJson(savedJson, Saved.class);
			if (saved == null)
			{
				return;
			}
			if (saved.player != null)
			{
				saved.player.stream().filter(s -> s != null && s.getTile() != null).forEach(player::add);
			}
			if (saved.confirmed != null)
			{
				saved.confirmed.stream().filter(Objects::nonNull).map(WorldPointDto::toWorldPoint).forEach(confirmed::add);
			}
			if (saved.rejected != null)
			{
				saved.rejected.stream().filter(Objects::nonNull).map(WorldPointDto::toWorldPoint).forEach(rejected::add);
			}
		}
		catch (JsonParseException e)
		{
			// corrupt saved data: fall back to builtin only
			player.clear();
			confirmed.clear();
			rejected.clear();
		}
	}

	private static WorldPoint point(Safespot s)
	{
		return s.getTile().toWorldPoint();
	}

	private static WorldPointDto dto(WorldPoint p)
	{
		WorldPointDto d = new WorldPointDto();
		d.setX(p.getX());
		d.setY(p.getY());
		d.setPlane(p.getPlane());
		return d;
	}

	private Safespot effective(Safespot b)
	{
		if (!confirmed.contains(point(b)))
		{
			return b;
		}
		Safespot copy = new Safespot();
		copy.setLocationId(b.getLocationId());
		copy.setMonsterId(b.getMonsterId());
		copy.setTile(b.getTile());
		copy.setNote(b.getNote());
		copy.setSource(b.getSource());
		copy.setVerified(true);
		return copy;
	}

	/** Visible (non-rejected) spots for a location, builtin first. */
	public List<Safespot> forLocation(String locationId)
	{
		List<Safespot> out = new ArrayList<>();
		for (Safespot b : builtin)
		{
			if (Objects.equals(b.getLocationId(), locationId) && !rejected.contains(point(b)))
			{
				out.add(effective(b));
			}
		}
		player.stream().filter(s -> Objects.equals(s.getLocationId(), locationId)).forEach(out::add);
		return out;
	}

	/** The shown spot at a template-space tile (as from WorldPoint.fromLocalInstance), or null. */
	public Safespot spotAt(String locationId, WorldPoint tile)
	{
		return forLocation(locationId).stream().filter(s -> point(s).equals(tile)).findFirst().orElse(null);
	}

	public boolean hasAny(String locationId)
	{
		return !forLocation(locationId).isEmpty();
	}

	public void mark(String locationId, int monsterId, WorldPoint tile, String note)
	{
		rejected.remove(tile);
		player.removeIf(s -> point(s).equals(tile) && Objects.equals(s.getLocationId(), locationId));
		Safespot s = new Safespot();
		s.setLocationId(locationId);
		s.setMonsterId(monsterId);
		s.setTile(dto(tile));
		s.setNote(note == null ? "" : note.trim());
		s.setVerified(true);
		s.setSource("player");
		player.add(s);
	}

	/** Marks a builtin spot at this tile as verified. */
	public void confirm(WorldPoint tile)
	{
		rejected.remove(tile);
		if (builtin.stream().anyMatch(b -> point(b).equals(tile)))
		{
			confirmed.add(tile);
		}
	}

	/** Hides the spot at this tile (removes a player mark, hides a builtin). */
	public void reject(WorldPoint tile)
	{
		player.removeIf(s -> point(s).equals(tile));
		confirmed.remove(tile);
		if (builtin.stream().anyMatch(b -> point(b).equals(tile)))
		{
			rejected.add(tile);
		}
	}

	/** Player marks plus builtin spots the player confirmed, as they should appear in safespots.json. */
	List<Safespot> exportable()
	{
		List<Safespot> out = builtin.stream()
			.filter(b -> confirmed.contains(point(b)) && !rejected.contains(point(b)))
			.map(this::effective)
			.collect(Collectors.toList());
		out.addAll(player);
		return out;
	}

	/** How many spots {@link SafespotExport#export} would include. */
	public int exportableCount()
	{
		return exportable().size();
	}

	public String toJson()
	{
		Saved saved = new Saved();
		saved.player = new ArrayList<>(player);
		confirmed.forEach(p -> saved.confirmed.add(dto(p)));
		rejected.forEach(p -> saved.rejected.add(dto(p)));
		return gson.toJson(saved);
	}
}

package com.slayercompanion.session;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Reads the game messages for items an open herb sack, gem bag or seed box takes straight off the floor.
 * None of these bags is a readable item container, so the message is the only sign. The herb sack and seed
 * box messages name the item; the gem bag's doesn't, so it is the ground item the player last chose to take.
 */
public class BagPickups
{
	/** One pickup: a name (herb sack, seed box) or an item id (gem bag). */
	public static final class Bagged
	{
		final String name;
		final int itemId;
		final int qty;

		Bagged(String name, int itemId, int qty)
		{
			this.name = name;
			this.itemId = itemId;
			this.qty = qty;
		}
	}

	private static final Pattern HERB = Pattern.compile("You put the (.+?)(?: herb)? into your (?:open )?herb sack\\.");
	private static final Pattern SEED = Pattern.compile("You put (\\d+) x (.+?) straight into your open seed box\\.");
	private static final Pattern GEM = Pattern.compile("You put it straight into your open gem \\w+\\.");

	private int lastTaken = -1;

	/** The player chose "Take" on a ground item. */
	public void onTake(int itemId)
	{
		lastTaken = itemId;
	}

	/** @return what a bag took, or null if the message isn't a bag pickup */
	public Bagged parse(String message)
	{
		Matcher m = HERB.matcher(message);
		if (m.matches())
		{
			return new Bagged(m.group(1), -1, 1);
		}
		m = SEED.matcher(message);
		if (m.matches())
		{
			return new Bagged(m.group(2), -1, Integer.parseInt(m.group(1)));
		}
		if (GEM.matcher(message).matches() && lastTaken != -1)
		{
			Bagged b = new Bagged(null, lastTaken, 1);
			lastTaken = -1;
			return b;
		}
		return null;
	}
}

package com.slayercompanion.session;

import java.util.Collections;
import java.util.Map;
import java.util.Optional;
import java.util.OptionalDouble;
import java.util.OptionalInt;
import java.util.Set;
import net.runelite.api.ItemID;
import net.runelite.api.gameval.VarPlayerID;

/**
 * How many kills the dwarf multicannon's cannonballs last, from balls in the cannon plus balls carried.
 * <p>
 * Feed it once per game tick with {@link #update}, so the cannon varp and the inventory are read together:
 * loading moves balls from the inventory into the cannon and leaves the total unchanged. Rule: a decrease
 * of the total (in cannon + carried) while the cannon stays placed, no bank is open, and after the task's
 * first kill, was fired. Placing or picking up the cannon resets the baseline, so balls returned on pickup
 * are not counted either way.
 * <p>
 * Supply cost: cannonballs leave the inventory when loaded, not when fired. Call
 * {@link SupplyTracker#ignore} with {@link #BALL_IDS} so loading is not costed, and pass the balls
 * {@link #update} reports as fired to {@link SupplyTracker#addUsed}; each ball is then costed once, when fired.
 */
public class CannonRunway
{
	/** Cannonballs in the cannon. RuneLite {@code VarPlayerID.ROCKTHROWER} (3), read by RuneLite's CannonPlugin. */
	public static final int AMMO_VARP = VarPlayerID.ROCKTHROWER;
	/** Cannon state. RuneLite {@code VarPlayerID.DROPCANNON} (2); CannonPlugin treats {@link #STATE_PLACED} as placed. */
	public static final int STATE_VARP = VarPlayerID.DROPCANNON;
	public static final int STATE_PLACED = 4;
	/** Ammo the dwarf multicannon fires: steel and granite cannonballs. */
	public static final Set<Integer> BALL_IDS = Set.of(ItemID.STEEL_CANNONBALL, ItemID.GRANITE_CANNONBALL);

	private boolean placed;
	private boolean bankOpen;
	private boolean started;
	private int kills;
	private long used;
	private int ammo;
	private int steel;
	private int granite;
	/** The ball type last seen going into the cannon; fired balls are costed as this type. */
	private int loadedId = ItemID.STEEL_CANNONBALL;

	/** Whether a cannon state varp value means the cannon is set up. */
	public static boolean isPlaced(int stateVarp)
	{
		return stateVarp == STATE_PLACED;
	}

	/** Clears usage and kills for a new task. The cannon and ball counts are kept. */
	public void reset()
	{
		started = false;
		kills = 0;
		used = 0;
	}

	/** Records {@code n} task kills; the first one starts counting. */
	public void onKill(int n)
	{
		if (n > 0)
		{
			started = true;
			kills += n;
		}
	}

	/** While a bank or deposit box is open, carried balls going down were banked, not fired. */
	public void setBankOpen(boolean open)
	{
		bankOpen = open;
	}

	/**
	 * Takes this tick's cannon and carried-ball readings.
	 *
	 * @param placed  cannon set up ({@link #isPlaced} of the {@link #STATE_VARP} value)
	 * @param ammo    {@link #AMMO_VARP} value
	 * @param steel   steel cannonballs carried
	 * @param granite granite cannonballs carried
	 * @return balls fired since the last update, item id to quantity; empty when none
	 */
	public Map<Integer, Integer> update(boolean placed, int ammo, int steel, int granite)
	{
		ammo = Math.max(0, ammo);
		Map<Integer, Integer> fired = Collections.emptyMap();
		if (placed && this.placed)
		{
			if (ammo > this.ammo)
			{
				if (granite < this.granite)
				{
					loadedId = ItemID.GRANITE_CANNONBALL;
				}
				else if (steel < this.steel)
				{
					loadedId = ItemID.STEEL_CANNONBALL;
				}
			}
			int diff = (this.ammo + this.steel + this.granite) - (ammo + steel + granite);
			if (diff > 0 && started && !bankOpen)
			{
				used += diff;
				fired = Collections.singletonMap(loadedId, diff);
			}
		}
		this.placed = placed;
		this.ammo = placed ? ammo : 0;
		this.steel = steel;
		this.granite = granite;
		return fired;
	}

	public boolean placed()
	{
		return placed;
	}

	public int kills()
	{
		return kills;
	}

	/** Balls fired this task. */
	public long ballsUsed()
	{
		return used;
	}

	/** Balls in the cannon plus carried. */
	public int ballsLeft()
	{
		return ammo + steel + granite;
	}

	/** Balls fired per kill; empty before the first kill. */
	public OptionalDouble ballsPerKill()
	{
		return kills > 0 ? OptionalDouble.of(used / (double) kills) : OptionalDouble.empty();
	}

	/** Kills until the balls run out; empty with no cannon placed or no balls fired yet. */
	public OptionalInt killsLeft()
	{
		if (!placed || kills <= 0 || used <= 0)
		{
			return OptionalInt.empty();
		}
		return OptionalInt.of((int) Math.floor(ballsLeft() / (used / (double) kills)));
	}

	/** Panel line, e.g. "~30 kills · 412 balls"; empty with no cannon placed. */
	public Optional<String> summary()
	{
		return placed ? Optional.of(line(killsLeft(), ballsLeft())) : Optional.empty();
	}

	/** Shortfall warning against the kills left on task; empty with no cannon placed or no shortfall. */
	public Optional<String> warning(int taskRemaining)
	{
		return placed ? warning(killsLeft(), taskRemaining) : Optional.empty();
	}

	/** "~30 kills · 412 balls", or just "412 balls" before a rate is known. */
	public static String line(OptionalInt killsLeft, int balls)
	{
		String b = balls + (balls == 1 ? " ball" : " balls");
		if (!killsLeft.isPresent())
		{
			return b;
		}
		int k = killsLeft.getAsInt();
		return "~" + k + (k == 1 ? " kill · " : " kills · ") + b;
	}

	/** "Cannonballs run out ~12 kills before task end" when {@code killsLeft} falls short of the task. */
	public static Optional<String> warning(OptionalInt killsLeft, int taskRemaining)
	{
		if (!killsLeft.isPresent() || killsLeft.getAsInt() >= taskRemaining)
		{
			return Optional.empty();
		}
		int shortBy = taskRemaining - killsLeft.getAsInt();
		return Optional.of("Cannonballs run out ~" + shortBy + (shortBy == 1 ? " kill" : " kills") + " before task end");
	}
}

package com.slayercompanion.session;

import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.function.IntUnaryOperator;
import net.runelite.api.ItemID;

/**
 * Consumable items that each kill needs to finish the monster off, and how many kills the carried ones cover.
 * <ul>
 * <li>Lizards (desert, small, large): one Ice cooler per kill.</li>
 * <li>Rockslugs (and giant rockslugs): one Bag of salt per kill.</li>
 * <li>Mutated and ancient zygomites: one Fungicide spray charge per kill. A spray (n) holds n charges;
 * each Fungicide refill tops a spray up by 10, so refills only count while a spray is carried.</li>
 * </ul>
 * Tools that are not used up (rock hammer / granite hammer for gargoyles) are skipped.
 * <p>
 * Slayer unlocks "Reptile freezer", "Slug salter" and "Shroom sprayer" apply the item automatically, but it is
 * still consumed, so the counts here hold with or without them. "Gargoyle smasher" covers the hammer tool.
 */
public final class FinishingItems
{
	private static final int[] SPRAYS = {
		ItemID.FUNGICIDE_SPRAY_0, ItemID.FUNGICIDE_SPRAY_1, ItemID.FUNGICIDE_SPRAY_2, ItemID.FUNGICIDE_SPRAY_3,
		ItemID.FUNGICIDE_SPRAY_4, ItemID.FUNGICIDE_SPRAY_5, ItemID.FUNGICIDE_SPRAY_6, ItemID.FUNGICIDE_SPRAY_7,
		ItemID.FUNGICIDE_SPRAY_8, ItemID.FUNGICIDE_SPRAY_9, ItemID.FUNGICIDE_SPRAY_10,
	};
	/** Charges one Fungicide refill adds to a spray. */
	static final int REFILL_CHARGES = 10;

	public static final Need ICE_COOLER = new Need("Ice coolers", "Ice cooler",
		Map.of(ItemID.ICE_COOLER, 1), Set.of());
	public static final Need BAG_OF_SALT = new Need("Bags of salt", "Bag of salt",
		Map.of(ItemID.BAG_OF_SALT, 1), Set.of());
	public static final Need FUNGICIDE = new Need("Fungicide charges", "Fungicide charge",
		fungicideUses(), Set.of(ItemID.FUNGICIDE));

	private static final Map<String, Need> BY_NAME = new HashMap<>();

	static
	{
		for (String n : new String[]{"lizards", "lizard", "desert lizards", "desert lizard", "small lizards",
			"small lizard", "large lizards", "large lizard"})
		{
			BY_NAME.put(n, ICE_COOLER);
		}
		for (String n : new String[]{"rockslugs", "rockslug", "giant rockslugs", "giant rockslug"})
		{
			BY_NAME.put(n, BAG_OF_SALT);
		}
		for (String n : new String[]{"mutated zygomites", "mutated zygomite", "zygomites", "zygomite",
			"ancient zygomites", "ancient zygomite"})
		{
			BY_NAME.put(n, FUNGICIDE);
		}
	}

	private FinishingItems()
	{
	}

	private static Map<Integer, Integer> fungicideUses()
	{
		Map<Integer, Integer> m = new LinkedHashMap<>();
		for (int charges = 0; charges < SPRAYS.length; charges++)
		{
			m.put(SPRAYS[charges], charges);
		}
		m.put(ItemID.FUNGICIDE, REFILL_CHARGES);
		return m;
	}

	/** The finishing item a task needs, by task name (e.g. "Mutated Zygomites"); empty if none. */
	public static Optional<Need> forTask(String taskName)
	{
		if (taskName == null)
		{
			return Optional.empty();
		}
		return Optional.ofNullable(BY_NAME.get(taskName.trim().toLowerCase(Locale.ROOT)));
	}

	/** The finishing item a monster needs, by NPC name (e.g. "Desert Lizard"); empty if none. */
	public static Optional<Need> forMonster(String npcName)
	{
		return forTask(npcName);
	}

	/** A consumable finishing item, possibly spread over several item ids (spray charges, refills). */
	public static final class Need
	{
		private final String label;
		private final String singular;
		private final Map<Integer, Integer> usesPerItem;
		/** Items that only count while some other item of this need is carried (refills need a spray). */
		private final Set<Integer> needsHolder;

		Need(String label, String singular, Map<Integer, Integer> usesPerItem, Set<Integer> needsHolder)
		{
			this.label = label;
			this.singular = singular;
			this.usesPerItem = Collections.unmodifiableMap(usesPerItem);
			this.needsHolder = needsHolder;
		}

		/** Plural label, e.g. "Ice coolers". */
		public String getLabel()
		{
			return label;
		}

		/** Item id to kills one of that item covers. */
		public Map<Integer, Integer> getUsesPerItem()
		{
			return usesPerItem;
		}

		/** Kills the carried items cover. */
		public int usesCarried(SupplyTracker t)
		{
			return usesCarried(t::count);
		}

		/** Kills covered by carried counts (item id to quantity). */
		public int usesCarried(Map<Integer, Integer> counts)
		{
			return usesCarried(id -> counts.getOrDefault(id, 0));
		}

		private int usesCarried(IntUnaryOperator count)
		{
			boolean holder = false;
			for (int id : usesPerItem.keySet())
			{
				if (!needsHolder.contains(id) && count.applyAsInt(id) > 0)
				{
					holder = true;
					break;
				}
			}
			int uses = 0;
			for (Map.Entry<Integer, Integer> e : usesPerItem.entrySet())
			{
				if (needsHolder.contains(e.getKey()) && !holder)
				{
					continue;
				}
				uses += Math.max(0, count.applyAsInt(e.getKey())) * e.getValue();
			}
			return uses;
		}

		/** Status line, e.g. "23 ice coolers · 40 left"; empty once no kills are left. */
		public Optional<String> line(int usesCarried, int killsLeft)
		{
			if (killsLeft <= 0)
			{
				return Optional.empty();
			}
			String what = (usesCarried == 1 ? singular : label).toLowerCase(Locale.ROOT);
			String have = usesCarried <= 0 ? "No " + what + " carried" : usesCarried + " " + what;
			return Optional.of(have + " · " + killsLeft + " left");
		}

		/** Warning when the carried items cover fewer kills than are left, e.g.
		 * "Ice coolers run out ~17 kills before task end"; empty otherwise. */
		public Optional<String> warning(int usesCarried, int killsLeft)
		{
			int shortBy = killsLeft - Math.max(0, usesCarried);
			if (shortBy <= 0)
			{
				return Optional.empty();
			}
			if (usesCarried <= 0)
			{
				return Optional.of("No " + label.toLowerCase(Locale.ROOT) + " carried · needed to finish kills");
			}
			return Optional.of(label + " run out ~" + shortBy + (shortBy == 1 ? " kill" : " kills")
				+ " before task end");
		}

		@Override
		public String toString()
		{
			return label;
		}
	}
}

