package com.slayercompanion.session;

import java.time.Duration;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.function.Predicate;

/**
 * Value of task loot the player actually picks up. Coins a ring of wealth (i) collects straight into the
 * inventory never touch the ground, so unmatched coins gained within {@link #AUTO_COLLECT} of a task kill count too.
 * Each task kill's drop waits here for {@link #GROUND_TIME};
 * an item of the same id arriving in the player's carried items (inventory, worn, looting bag) within that
 * time counts as picked up, up to the dropped quantity. Open herb sacks, gem bags and seed boxes take items
 * straight off the floor; those arrive via {@link #onBagged} instead. Times are offsets from any fixed start.
 */
public class PickedUpLoot
{
	/** How long a drop stays on the ground (one minute private, two public). */
	static final Duration GROUND_TIME = Duration.ofMinutes(3);

	private static final class OnGround
	{
		final int itemId;
		final String name;
		int qty;
		final long gpEach;
		final Duration expires;

		OnGround(int itemId, String name, int qty, long gpEach, Duration expires)
		{
			this.itemId = itemId;
			this.name = name;
			this.qty = qty;
			this.gpEach = gpEach;
			this.expires = expires;
		}
	}

	/** How close to a kill auto-collected coins arrive, either side (the kill count can update first or last). */
	static final Duration AUTO_COLLECT = Duration.ofSeconds(3);
	private static final int COINS = 995;

	private final List<OnGround> ground = new ArrayList<>();
	private Duration lastKill;
	/** Unmatched coins gained recently, waiting for a kill; and when. */
	private int looseCoins;
	private Duration looseCoinsAt;
	private Map<Integer, Integer> last;
	private boolean bankOpen;
	private long total;

	public void reset()
	{
		ground.clear();
		total = 0;
		lastKill = null;
		looseCoins = 0;
	}

	public void onDrop(int itemId, int qty, long gpEach, Duration now)
	{
		onDrop(itemId, null, qty, gpEach, now);
	}

	/** @param name the game's name for the item, so bag pickups that only name it can match (may be null) */
	public void onDrop(int itemId, String name, int qty, long gpEach, Duration now)
	{
		ground.add(new OnGround(itemId, name, qty, gpEach, now.plus(GROUND_TIME)));
	}

	/** Items an open bag took straight off the floor, named by the game's message. */
	public void onBagged(String name, int qty, Duration now)
	{
		expire(now);
		pickUp(g -> g.name != null && g.name.equalsIgnoreCase(name), qty);
	}

	/** Items an open bag took straight off the floor, known by id. */
	public void onBagged(int itemId, int qty, Duration now)
	{
		expire(now);
		pickUp(g -> g.itemId == itemId, qty);
	}

	private void expire(Duration now)
	{
		ground.removeIf(g -> g.qty <= 0 || now.compareTo(g.expires) > 0);
	}

	/** A task kill: claims coins that arrived just before it and opens a window for ones just after. */
	public void onKill(Duration now)
	{
		lastKill = now;
		if (looseCoins > 0 && within(looseCoinsAt, now))
		{
			total += looseCoins;
		}
		looseCoins = 0;
	}

	private static boolean within(Duration a, Duration b)
	{
		return a != null && a.minus(b).abs().compareTo(AUTO_COLLECT) <= 0;
	}

	/** While a bank or deposit box is open, gains were withdrawn, not picked up. */
	public void setBankOpen(boolean open)
	{
		bankOpen = open;
	}

	/** @param counts item id to quantity across everything the player carries */
	public void onCarried(Map<Integer, Integer> counts, Duration now)
	{
		expire(now);
		if (last != null && !bankOpen)
		{
			for (Map.Entry<Integer, Integer> e : counts.entrySet())
			{
				int gained = e.getValue() - last.getOrDefault(e.getKey(), 0);
				if (gained > 0)
				{
					int itemId = e.getKey();
					int left = pickUp(g -> g.itemId == itemId, gained);
					if (e.getKey() == COINS && left > 0)
					{
						autoCollected(left, now);
					}
				}
			}
		}
		last = new HashMap<>(counts);
	}

	private void autoCollected(int coins, Duration now)
	{
		if (within(lastKill, now))
		{
			total += coins;
		}
		else
		{
			looseCoins = coins;
			looseCoinsAt = now;
		}
	}

	/** @return how much of the gain matched no drop on the ground */
	private int pickUp(Predicate<OnGround> matches, int gained)
	{
		for (Iterator<OnGround> it = ground.iterator(); it.hasNext() && gained > 0; )
		{
			OnGround g = it.next();
			if (!matches.test(g))
			{
				continue;
			}
			int n = Math.min(g.qty, gained);
			total += n * g.gpEach;
			g.qty -= n;
			gained -= n;
			if (g.qty == 0)
			{
				it.remove();
			}
		}
		return gained;
	}

	/** GP value picked up this task. */
	public long total()
	{
		return total;
	}
}

package com.slayercompanion.session;

import java.util.Optional;
import java.util.OptionalDouble;
import java.util.OptionalInt;
import java.util.Set;

/**
 * Estimates how many more kills the player's prayer lasts.
 * <p>
 * Drain is the sum of every drop in prayer points seen after the task's first kill. Drinking a potion
 * raises points, so increases are ignored and potions need no special handling. Drain per kill only counts
 * kills after the first update, since the drain before it was not watched.
 * <p>
 * Restore per dose (OSRS Wiki): Prayer potion 7 + floor(level / 4); Super restore, Sanfew serum and
 * Blighted super restore 8 + floor(level / 4). Holy wrench and prayer cape bonuses are ignored, as is
 * restoring past the base level, so the estimate errs low for those players.
 */
public class PrayerRunway
{
	private int last = -1;
	private boolean started;
	private int kills;
	private int killsAtStart;
	private long drained;

	/** Clears drain and kills for a new task. The last point reading is kept as the baseline. */
	public void reset()
	{
		started = false;
		kills = 0;
		killsAtStart = 0;
		drained = 0;
	}

	/** Records {@code n} task kills; the first update starts drain counting. */
	public void onKill(int n)
	{
		if (n <= 0)
		{
			return;
		}
		if (!started)
		{
			started = true;
			killsAtStart = n;
		}
		kills += n;
	}

	/** @param current prayer points now (boosted level), from StatChanged */
	public void onPrayerPoints(int current)
	{
		if (last >= 0 && started && current < last)
		{
			drained += last - current;
		}
		last = current;
	}

	/** Prayer points drained since the first kill. */
	public long drained()
	{
		return drained;
	}

	/** Points drained per kill; empty before any measured kill or when no drain was seen (not praying). */
	public OptionalDouble drainPerKill()
	{
		int counted = kills - killsAtStart;
		if (counted <= 0 || drained <= 0)
		{
			return OptionalDouble.empty();
		}
		return OptionalDouble.of(drained / (double) counted);
	}

	/** Points one dose of the family restores at the given base prayer level; 0 for other families. */
	public static int restorePerDose(String family, int prayerLevel)
	{
		int bonus = Math.max(0, prayerLevel) / 4;
		if ("Prayer potion".equals(family))
		{
			return 7 + bonus;
		}
		if ("Super restore".equals(family) || "Sanfew serum".equals(family)
			|| "Blighted super restore".equals(family))
		{
			return 8 + bonus;
		}
		return 0;
	}

	/**
	 * Kills left before prayer runs out, counting carried doses at the Prayer potion rate (the lower one).
	 * Empty when no drain was seen; show plain points then.
	 */
	public OptionalInt killsLeft(int currentPoints, int dosesCarried, int prayerLevel)
	{
		long points = currentPoints + (long) dosesCarried * restorePerDose("Prayer potion", prayerLevel);
		return killsLeftFor(points);
	}

	/** Kills left, counting each carried dose family from the tracker at its own restore rate. */
	public OptionalInt killsLeft(int currentPoints, SupplyTracker supplies, int prayerLevel)
	{
		long points = currentPoints;
		for (String family : SupplyTracker.PRAYER_FAMILIES)
		{
			points += (long) supplies.doses(Set.of(family)) * restorePerDose(family, prayerLevel);
		}
		return killsLeftFor(points);
	}

	private OptionalInt killsLeftFor(long points)
	{
		OptionalDouble perKill = drainPerKill();
		if (!perKill.isPresent())
		{
			return OptionalInt.empty();
		}
		return OptionalInt.of((int) Math.floor(Math.max(0, points) / perKill.getAsDouble()));
	}

	/** "Lasts ~25 kills", or plain points ("43 prayer points") when there is no estimate. */
	public static String line(OptionalInt killsLeft, int currentPoints)
	{
		if (!killsLeft.isPresent())
		{
			return currentPoints + " prayer points";
		}
		int k = killsLeft.getAsInt();
		return "Lasts ~" + k + (k == 1 ? " kill" : " kills");
	}

	/** "Prayer runs out ~15 kills before task end" when prayer will not last the task; empty otherwise. */
	public static Optional<String> warning(OptionalInt killsLeft, int killsRemaining)
	{
		if (!killsLeft.isPresent() || killsLeft.getAsInt() >= killsRemaining)
		{
			return Optional.empty();
		}
		int gap = killsRemaining - killsLeft.getAsInt();
		return Optional.of("Prayer runs out ~" + gap + (gap == 1 ? " kill" : " kills") + " before task end");
	}
}

package com.slayercompanion.session;

import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import net.runelite.api.gameval.VarbitID;

/**
 * Slayer reward points per completed task, from the OSRS Wiki "Slayer reward point" table
 * (checked 2026-10-21). A task pays the master's base points, times 5 on every 10th task in the streak,
 * 15 on every 50th, 25 on every 100th, 35 on every 250th and 50 on every 1000th (the largest applies).
 * <p>
 * The first four tasks of a streak pay nothing. The wiki ties this to the streak, not the account: after
 * Turael resets the streak to zero, four more tasks are needed before points resume. So the streak varbit
 * alone is enough and no lifetime task count is needed. (One line on the wiki page says "first 5"; the
 * rule text and the Turael note both say four.)
 * <p>
 * Krystilia keeps a separate wilderness streak ({@link #WILDERNESS_STREAK_VARBIT}); pass that streak for her.
 */
public final class SlayerPoints
{
	/** Current slayer reward points (varbit 4068). */
	public static final int POINTS_VARBIT = VarbitID.SLAYER_POINTS;
	/** Current task streak for standard masters (varbit 4069). */
	public static final int STREAK_VARBIT = VarbitID.SLAYER_TASKS_COMPLETED;
	/** Current task streak for Krystilia (varbit 5617). */
	public static final int WILDERNESS_STREAK_VARBIT = VarbitID.SLAYER_WILDERNESS_TASKS_COMPLETED;

	/** Tasks at the start of a streak that pay no points. */
	public static final int UNPAID_TASKS = 4;

	/** Base points: { normal, with the relevant elite diary }. */
	private static final Map<String, int[]> BASE = new HashMap<>();

	static
	{
		base(0, 0, "Turael", "Spria", "Aya");
		base(6, 6, "Mazchna", "Achtryn");
		base(8, 8, "Vannaka");
		base(10, 10, "Chaeldar");
		base(12, 15, "Nieve", "Steve");
		base(15, 15, "Duradel", "Kuradal");
		base(18, 20, "Konar", "Konar quo Maten");
		base(25, 25, "Krystilia");
	}

	private SlayerPoints()
	{
	}

	private static void base(int normal, int diary, String... masters)
	{
		for (String m : masters)
		{
			BASE.put(key(m), new int[]{normal, diary});
		}
	}

	private static String key(String master)
	{
		return master == null ? "" : master.trim().toLowerCase(Locale.ROOT);
	}

	/** Whether the master is in the points table. */
	public static boolean isKnown(String master)
	{
		return BASE.containsKey(key(master));
	}

	/**
	 * Base points per task. Elite diary raises Nieve/Steve (Western Provinces) and Konar (Kourend &amp; Kebos).
	 * Unknown masters (including Mortimer) give 0.
	 */
	public static int basePoints(String master, boolean eliteDiary)
	{
		int[] b = BASE.get(key(master));
		return b == null ? 0 : b[eliteDiary ? 1 : 0];
	}

	/** Milestone multiplier for the n-th task of a streak (1 for ordinary tasks). */
	public static int multiplier(int taskNumber)
	{
		if (taskNumber <= 0)
		{
			return 1;
		}
		if (taskNumber % 1000 == 0)
		{
			return 50;
		}
		if (taskNumber % 250 == 0)
		{
			return 35;
		}
		if (taskNumber % 100 == 0)
		{
			return 25;
		}
		if (taskNumber % 50 == 0)
		{
			return 15;
		}
		if (taskNumber % 10 == 0)
		{
			return 5;
		}
		return 1;
	}

	/** Points for finishing the next task, given the streak before it (the streak varbit's current value). */
	public static int pointsForTask(String master, int completedStreak)
	{
		return pointsForTask(master, completedStreak, false);
	}

	/** Points for finishing the next task, given the streak before it and the master's elite diary. */
	public static int pointsForTask(String master, int completedStreak, boolean eliteDiary)
	{
		int next = Math.max(0, completedStreak) + 1;
		if (next <= UNPAID_TASKS)
		{
			return 0;
		}
		return basePoints(master, eliteDiary) * multiplier(next);
	}

	/** "412 → 422": current points and the total after the award. */
	public static String summary(int current, int awarded)
	{
		return current + " → " + (current + awarded);
	}
}

package com.slayercompanion.session;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Optional;
import java.util.OptionalDouble;
import java.util.OptionalInt;
import java.util.Set;
import java.util.function.IntFunction;
import java.util.function.IntToLongFunction;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;
import net.runelite.api.ItemID;

/**
 * Tracks what the player uses up during a task from snapshots of everything they carry (inventory + worn
 * equipment + rune pouch, summed per item id), so moving gear between worn and inventory nets out.
 * <p>
 * Rule: an item whose count goes down while no bank is open, after the task's first kill, was used.
 * Increases (loot, withdrawals) are ignored. Items named "Something(n)" form a dose family; usage there is
 * counted in doses, so Prayer potion(4) becoming (3) is one dose. Empty vials cost nothing.
 * <p>
 * Weapon charges (trident runes, blowpipe scales and darts, revenant ether, ...) are not items; they are
 * counted per attack by {@link WeaponCharges} and costed here through {@link #addChargeUsed}.
 * <p>
 * Known limits: items dropped on purpose count as used; a pizza or cake eaten in halves is costed per piece
 * eaten; runes or coins put into a weapon after the first kill are costed twice, once as they leave the
 * inventory and again as the charges are spent (scales, ether, vials of blood and blowpipe darts are not);
 * charges spent by attacks the tracker does not recognise (see {@link WeaponCharges}) are not seen.
 */
public class SupplyTracker
{
	/** Dose families that restore prayer, for the prayer runway. */
	public static final Set<String> PRAYER_FAMILIES = Set.of(
		"Prayer potion", "Super restore", "Sanfew serum", "Blighted super restore");

	private static final Pattern DOSE = Pattern.compile("^(.*?)\\s*\\((\\d{1,2})\\)$");

	/** An item that is one member of a dose family, e.g. Prayer potion with 3 doses. */
	@Value
	public static class Dose
	{
		String family;
		int doses;
	}

	private final IntToLongFunction price;
	private final IntFunction<String> names;

	private Map<Integer, Integer> last;
	private boolean bankOpen;
	private boolean started;
	private int kills;
	private final Map<Integer, Long> used = new HashMap<>();
	private final Map<String, Long> dosesUsed = new HashMap<>();
	private long foodUsed;
	private final Set<Integer> ignored = new HashSet<>();
	/** Items ignored while any of their carriers is carried, e.g. darts while a blowpipe is. */
	private final Map<Integer, Set<Integer>> ignoredWhile = new HashMap<>();
	/** Charge materials spent, in fractions of an item. */
	private final Map<Integer, Double> chargeUsed = new HashMap<>();

	private final Map<Integer, Optional<Dose>> doseCache = new HashMap<>();
	private final Map<Integer, Long> priceCache = new HashMap<>();
	/** Best known per-dose price for each family: the price of its highest-dose member divided by its doses. */
	private final Map<String, Dose> dosePriceFrom = new HashMap<>();
	private final Map<String, Double> dosePrice = new HashMap<>();

	/**
	 * @param price GP each for an item id; looked up when the item is first used
	 * @param names the game's name for an item id (may return null); used to find dose families
	 */
	public SupplyTracker(IntToLongFunction price, IntFunction<String> names)
	{
		this.price = price;
		this.names = names;
	}

	/** Clears usage and kills for a new task. The last snapshot is kept as the baseline. */
	public void reset()
	{
		started = false;
		kills = 0;
		used.clear();
		chargeUsed.clear();
		dosesUsed.clear();
		foodUsed = 0;
	}

	/** Records {@code n} task kills; the first one starts usage counting. */
	public void onKill(int n)
	{
		if (n > 0)
		{
			started = true;
			kills += n;
		}
	}

	/**
	 * Items whose carried count going down is not usage, because another tracker reports their use through
	 * {@link #addUsed} (cannonballs: loading them is not firing them, see {@link CannonRunway}). Kept across resets.
	 */
	public void ignore(Set<Integer> itemIds)
	{
		ignored.addAll(itemIds);
	}

	/**
	 * Like {@link #ignore}, but only while one of {@code carriers} is carried before or after the change:
	 * darts leaving the inventory with a blowpipe carried were loaded into it. Kept across resets.
	 */
	public void ignoreWhileCarried(Set<Integer> carriers, Set<Integer> itemIds)
	{
		for (int id : itemIds)
		{
			ignoredWhile.computeIfAbsent(id, k -> new HashSet<>()).addAll(carriers);
		}
	}

	/**
	 * Records a weapon charge's materials spent, in fractions of an item (2/3 of a scale per blowpipe shot);
	 * costed at the item's price. Kept apart from {@link #usedTotal}, which counts whole items carried.
	 */
	public void addChargeUsed(int itemId, double qty)
	{
		if (qty > 0)
		{
			chargeUsed.merge(itemId, qty, Double::sum);
			priceCache.computeIfAbsent(itemId, price::applyAsLong);
		}
	}

	/** Records usage seen elsewhere, e.g. cannonballs fired; costed like any other used item. */
	public void addUsed(int itemId, long qty)
	{
		if (qty > 0)
		{
			used.merge(itemId, qty, Long::sum);
			priceCache.computeIfAbsent(itemId, price::applyAsLong);
		}
	}

	/** While a bank or deposit box is open, decreases were banked, not used. */
	public void setBankOpen(boolean open)
	{
		bankOpen = open;
	}

	/** @param counts item id to quantity across inventory, worn equipment and rune pouch */
	public void onSnapshot(Map<Integer, Integer> counts)
	{
		Map<Integer, Integer> now = new HashMap<>();
		for (Map.Entry<Integer, Integer> e : counts.entrySet())
		{
			if (e.getValue() != null && e.getValue() > 0)
			{
				now.merge(e.getKey(), e.getValue(), Integer::sum);
			}
		}
		if (last != null && started && !bankOpen)
		{
			countUsage(last, now);
		}
		last = now;
	}

	private void countUsage(Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		Set<Integer> ids = new HashSet<>(before.keySet());
		ids.addAll(after.keySet());
		Map<String, Integer> familyBefore = new HashMap<>();
		Map<String, Integer> familyAfter = new HashMap<>();
		for (int id : ids)
		{
			int b = before.getOrDefault(id, 0);
			int a = after.getOrDefault(id, 0);
			Optional<Dose> dose = doseOf(id);
			if (dose.isPresent())
			{
				Dose d = dose.get();
				familyBefore.merge(d.getFamily(), b * d.getDoses(), Integer::sum);
				familyAfter.merge(d.getFamily(), a * d.getDoses(), Integer::sum);
				notePrice(id, d);
			}
			else if (b > a && id != ItemID.VIAL && !ignored.contains(id) && !carrierHeld(id, before, after))
			{
				used.merge(id, (long) (b - a), Long::sum);
				priceCache.computeIfAbsent(id, price::applyAsLong);
			}
		}
		for (Map.Entry<String, Integer> e : familyBefore.entrySet())
		{
			int diff = e.getValue() - familyAfter.getOrDefault(e.getKey(), 0);
			if (diff > 0)
			{
				dosesUsed.merge(e.getKey(), (long) diff, Long::sum);
			}
		}
		long food = foodIn(before) - foodIn(after);
		if (food > 0)
		{
			foodUsed += food;
		}
	}

	private boolean carrierHeld(int id, Map<Integer, Integer> before, Map<Integer, Integer> after)
	{
		Set<Integer> carriers = ignoredWhile.get(id);
		if (carriers != null)
		{
			for (int c : carriers)
			{
				if (before.containsKey(c) || after.containsKey(c))
				{
					return true;
				}
			}
		}
		return false;
	}

	private void notePrice(int id, Dose d)
	{
		Dose best = dosePriceFrom.get(d.getFamily());
		if (best != null && best.getDoses() >= d.getDoses())
		{
			return;
		}
		long each = priceCache.computeIfAbsent(id, price::applyAsLong);
		if (each > 0)
		{
			dosePriceFrom.put(d.getFamily(), d);
			dosePrice.put(d.getFamily(), each / (double) d.getDoses());
		}
	}

	private static long foodIn(Map<Integer, Integer> counts)
	{
		long n = 0;
		for (Map.Entry<Integer, Integer> e : counts.entrySet())
		{
			if (FoodItems.isFood(e.getKey()))
			{
				n += e.getValue();
			}
		}
		return n;
	}

	/** The dose family an item belongs to, parsed from a name like "Prayer potion(3)". */
	public Optional<Dose> doseOf(int itemId)
	{
		return doseCache.computeIfAbsent(itemId, id -> parseDose(names.apply(id)));
	}

	static Optional<Dose> parseDose(String name)
	{
		if (name == null)
		{
			return Optional.empty();
		}
		Matcher m = DOSE.matcher(name.trim());
		if (!m.matches() || m.group(1).isEmpty())
		{
			return Optional.empty();
		}
		int doses = Integer.parseInt(m.group(2));
		return doses > 0 ? Optional.of(new Dose(m.group(1), doses)) : Optional.empty();
	}

	public int kills()
	{
		return kills;
	}

	public boolean started()
	{
		return started;
	}

	/** GP value of everything used this task. */
	public double costTotal()
	{
		double total = 0;
		for (Map.Entry<Integer, Long> e : used.entrySet())
		{
			total += e.getValue() * (double) priceCache.getOrDefault(e.getKey(), 0L);
		}
		for (Map.Entry<Integer, Double> e : chargeUsed.entrySet())
		{
			total += e.getValue() * priceCache.getOrDefault(e.getKey(), 0L);
		}
		for (Map.Entry<String, Long> e : dosesUsed.entrySet())
		{
			total += e.getValue() * dosePrice.getOrDefault(e.getKey(), 0.0);
		}
		return total;
	}

	/** Supply cost per kill in GP; empty before the first kill. */
	public OptionalDouble costPerKill()
	{
		return kills > 0 ? OptionalDouble.of(costTotal() / kills) : OptionalDouble.empty();
	}

	/** Quantity of a non-dose item used this task (dose items are counted per family, see {@link #dosesUsed}). */
	public long usedTotal(int itemId)
	{
		return used.getOrDefault(itemId, 0L);
	}

	/** Quantity of an item spent as weapon charges this task (see {@link #addChargeUsed}). */
	public double chargeMaterialUsed(int itemId)
	{
		return chargeUsed.getOrDefault(itemId, 0.0);
	}

	public OptionalDouble usedPerKill(int itemId)
	{
		return kills > 0 ? OptionalDouble.of(usedTotal(itemId) / (double) kills) : OptionalDouble.empty();
	}

	/** Non-dose item id to quantity used this task. */
	public Map<Integer, Long> usedItems()
	{
		return Collections.unmodifiableMap(used);
	}

	public long dosesUsed(String family)
	{
		return dosesUsed.getOrDefault(family, 0L);
	}

	/** Doses used per kill summed over the families, e.g. {@link #PRAYER_FAMILIES}; empty before the first kill. */
	public OptionalDouble dosesUsedPerKill(Set<String> families)
	{
		if (kills <= 0)
		{
			return OptionalDouble.empty();
		}
		long n = 0;
		for (String f : families)
		{
			n += dosesUsed(f);
		}
		return OptionalDouble.of(n / (double) kills);
	}

	/** Quantity of an item carried now (0 before the first snapshot). */
	public int count(int itemId)
	{
		return last == null ? 0 : last.getOrDefault(itemId, 0);
	}

	/** Doses carried now across the families. */
	public int doses(Set<String> families)
	{
		if (last == null)
		{
			return 0;
		}
		int n = 0;
		for (Map.Entry<Integer, Integer> e : last.entrySet())
		{
			Optional<Dose> d = doseOf(e.getKey());
			if (d.isPresent() && families.contains(d.get().getFamily()))
			{
				n += e.getValue() * d.get().getDoses();
			}
		}
		return n;
	}

	/** The food item carried in the largest stack now (lowest id on a tie), or -1 when none is carried. */
	public int mainFoodId()
	{
		int best = -1;
		int most = 0;
		if (last != null)
		{
			for (Map.Entry<Integer, Integer> e : last.entrySet())
			{
				int id = e.getKey();
				int n = e.getValue();
				if (FoodItems.isFood(id) && n > 0 && (n > most || n == most && id < best))
				{
					best = id;
					most = n;
				}
			}
		}
		return best;
	}

	/** Food items ({@link FoodItems}) carried now, or -1 before the first snapshot. */
	public int foodCount()
	{
		return last == null ? -1 : (int) foodIn(last);
	}

	/** Food items eaten this task. */
	public long foodUsed()
	{
		return foodUsed;
	}

	public OptionalInt killsUntilFoodRunsOut()
	{
		if (kills <= 0 || foodUsed <= 0 || last == null)
		{
			return OptionalInt.empty();
		}
		double perKill = (double) foodUsed / kills;
		return OptionalInt.of((int) Math.floor(foodCount() / perKill));
	}
}

package com.slayercompanion.session;

import com.slayercompanion.data.Drop;
import com.slayercompanion.data.Monster;
import com.slayercompanion.task.CurrentTask;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.util.Map;
import java.util.OptionalDouble;
import java.util.OptionalInt;
import java.util.Optional;
import lombok.Value;
import net.runelite.api.ItemID;

/**
 * Stats for the current slayer task. Timing starts at the first kill and excludes time spent logged out.
 */
public class TaskSession
{
	@Value
	public static class BestDrop
	{
		int itemId;
		String name;
		long value;
		double rate;
	}

	private final Clock clock;

	private Monster monster;
	private String taskName;
	private int remaining;
	private int total;
	private boolean hasTask;
	private int kills;
	/** Kills seen in the update that started the clock; time per kill only counts kills after these. */
	private int killsAtStart;
	private boolean started;
	private boolean loggedIn = true;
	private Instant runningSince;
	private Duration accumulated = Duration.ZERO;
	private int superiors;
	private BestDrop best;
	private final SupplyTracker supplies;
	private final PrayerRunway prayer = new PrayerRunway();
	private final CannonRunway cannon = new CannonRunway();
	private final WeaponCharges charges = new WeaponCharges();
	private final PickedUpLoot pickedUp = new PickedUpLoot();
	private final BagPickups bags = new BagPickups();

	/** Supplies are tracked without prices or item names (no cost, no dose families). */
	public TaskSession(Clock clock)
	{
		this(clock, new SupplyTracker(id -> 0, id -> null));
	}

	public TaskSession(Clock clock, SupplyTracker supplies)
	{
		this.clock = clock;
		this.supplies = supplies;
		// Loading the cannon is not using balls; fired balls are reported by the cannon runway instead.
		supplies.ignore(CannonRunway.BALL_IDS);
		// Charging a weapon is not using its materials; spent charges are reported by the weapon charges instead.
		supplies.ignore(WeaponCharges.MATERIAL_IDS);
		supplies.ignoreWhileCarried(WeaponCharges.BLOWPIPE_IDS, WeaponCharges.DART_IDS);
	}

	/** How long prayer lasts this task. */
	public PrayerRunway prayer()
	{
		return prayer;
	}

	/** How long cannonballs last this task. */
	public CannonRunway cannon()
	{
		return cannon;
	}

	/** @param current prayer points now (boosted level) */
	public void onPrayerPoints(int current)
	{
		prayer.onPrayerPoints(current);
	}

	/**
	 * Once per game tick, after {@link #onSupplies}: takes the cannon reading and costs fired balls as supplies.
	 *
	 * @param placed cannon set up
	 * @param ammo   balls in the cannon
	 */
	public void onCannon(boolean placed, int ammo)
	{
		cannon.update(placed, ammo, supplies.count(ItemID.STEEL_CANNONBALL), supplies.count(ItemID.GRANITE_CANNONBALL))
			.forEach(supplies::addUsed);
	}

	/** Attacks made with charged weapons this task, and the blowpipe's dart type. */
	public WeaponCharges weaponCharges()
	{
		return charges;
	}

	/**
	 * Once per game tick: counts a charged-weapon attack and costs the charge's materials as supplies.
	 * See {@link WeaponCharges#onTick} for the parameters.
	 */
	public void onWeaponTick(int weaponId, int capeId, int animation, int animationFrame, boolean animationStarted,
		int graphic, boolean graphicStarted)
	{
		charges.onTick(weaponId, capeId, animation, animationFrame, animationStarted, graphic, graphicStarted)
			.forEach(supplies::addChargeUsed);
	}

	/** A game message (tags removed); the blowpipe's "Check" message names its darts. */
	public void onGameMessage(String message)
	{
		charges.onChatMessage(message);
	}

	/** What the player has used up this task. */
	public SupplyTracker supplies()
	{
		return supplies;
	}

	/** Sets the monster being killed so drop rates can be looked up by item id. */
	public void setMonster(Monster monster)
	{
		this.monster = monster;
	}

	public void onTaskUpdate(CurrentTask current)
	{
		if (current == null)
		{
			reset();
			hasTask = false;
			return;
		}
		String name = current.getTask() == null ? null : current.getTask().getName();
		boolean sameTask = hasTask && java.util.Objects.equals(name, taskName)
			&& current.getRemaining() <= remaining;
		if (!sameTask)
		{
			reset();
			hasTask = true;
			taskName = name;
			remaining = current.getRemaining();
			total = current.getInitialAmount();
			return;
		}
		int delta = remaining - current.getRemaining();
		remaining = current.getRemaining();
		total = current.getInitialAmount();
		if (delta > 0)
		{
			if (!started)
			{
				started = true;
				killsAtStart = delta;
				if (loggedIn)
				{
					runningSince = clock.instant();
				}
			}
			kills += delta;
			supplies.onKill(delta);
			prayer.onKill(delta);
			cannon.onKill(delta);
			charges.onKill(delta);
			pickedUp.onKill(now());
		}
	}

	private void reset()
	{
		remaining = 0;
		total = 0;
		kills = 0;
		killsAtStart = 0;
		started = false;
		runningSince = null;
		accumulated = Duration.ZERO;
		pickedUp.reset();
		superiors = 0;
		best = null;
		supplies.reset();
		prayer.reset();
		cannon.reset();
		charges.reset();
	}

	/**
	 * @param itemName the game's name for the item, used when the drop isn't in the selected
	 *                 monster's table (may be null)
	 */
	public void onLoot(int itemId, String itemName, int qty, long gpEach)
	{
		long value = qty * gpEach;
		pickedUp.onDrop(itemId, itemName, qty, gpEach, now());
		if (best == null || value > best.getValue())
		{
			best = new BestDrop(itemId, nameOf(itemId, itemName), value, rateOf(itemId));
		}
	}

	private Drop dropOf(int itemId)
	{
		if (monster == null)
		{
			return null;
		}
		for (Drop d : monster.getDrops())
		{
			if (d.getItemId() == itemId)
			{
				return d;
			}
		}
		return null;
	}

	private String nameOf(int itemId, String itemName)
	{
		Drop d = dropOf(itemId);
		if (d != null && d.getName() != null)
		{
			return d.getName();
		}
		return itemName != null && !itemName.isEmpty() ? itemName : "Item " + itemId;
	}

	private double rateOf(int itemId)
	{
		Drop d = dropOf(itemId);
		return d == null ? 0 : d.getRate();
	}

	public void onSuperior()
	{
		superiors++;
	}

	public void onLoggedOut()
	{
		if (runningSince != null)
		{
			accumulated = accumulated.plus(Duration.between(runningSince, clock.instant()));
			runningSince = null;
		}
		loggedIn = false;
	}

	public void onLoggedIn()
	{
		loggedIn = true;
		if (started && runningSince == null)
		{
			runningSince = clock.instant();
		}
	}

	/** The player chose "Take" on a ground item; an open gem bag's message doesn't say which. */
	public void onGroundTake(int itemId)
	{
		bags.onTake(itemId);
	}

	/** A game message, in case an open herb sack, gem bag or seed box took task loot off the floor. */
	public void onBagMessage(String message)
	{
		BagPickups.Bagged b = bags.parse(message);
		if (b == null)
		{
			return;
		}
		if (b.name != null)
		{
			pickedUp.onBagged(b.name, b.qty, now());
		}
		else
		{
			pickedUp.onBagged(b.itemId, b.qty, now());
		}
	}

	/**
	 * While a bank or deposit box is open, items leaving the player were banked, not used. Snapshots taken
	 * while it is open become the new baseline.
	 */
	public void setBankOpen(boolean open)
	{
		supplies.setBankOpen(open);
		cannon.setBankOpen(open);
		pickedUp.setBankOpen(open);
	}

	/**
	 * @param counts item id to quantity across inventory, worn equipment and rune pouch
	 * @param looted the same plus the looting bag, for loot picked up
	 */
	public void onSupplies(Map<Integer, Integer> counts, Map<Integer, Integer> looted)
	{
		supplies.onSnapshot(counts);
		charges.onCarried(counts);
		pickedUp.onCarried(looted, now());
	}

	/** Inventory, worn and rune pouch only (no looting bag). */
	public void onSupplies(Map<Integer, Integer> counts)
	{
		onSupplies(counts, counts);
	}

	private Duration now()
	{
		return Duration.between(Instant.EPOCH, clock.instant());
	}

	public int remaining()
	{
		return remaining;
	}

	public int total()
	{
		return total;
	}

	public int kills()
	{
		return kills;
	}

	private double activeSeconds()
	{
		Duration d = accumulated;
		if (runningSince != null)
		{
			d = d.plus(Duration.between(runningSince, clock.instant()));
		}
		return d.toMillis() / 1000.0;
	}

	/**
	 * The clock starts at the first kill, so the time divides over the kills after it
	 * (usually kills - 1). Empty until there is at least one timed kill (kills >= 2).
	 */
	public OptionalDouble secondsPerKill()
	{
		int timedKills = kills - killsAtStart;
		if (!started || timedKills <= 0)
		{
			return OptionalDouble.empty();
		}
		return OptionalDouble.of(activeSeconds() / timedKills);
	}

	public OptionalDouble killsPerHour()
	{
		OptionalDouble spk = secondsPerKill();
		return spk.isPresent() && spk.getAsDouble() > 0 ? OptionalDouble.of(3600.0 / spk.getAsDouble()) : OptionalDouble.empty();
	}

	public OptionalDouble secondsLeft()
	{
		OptionalDouble spk = secondsPerKill();
		return spk.isPresent() ? OptionalDouble.of(spk.getAsDouble() * remaining) : OptionalDouble.empty();
	}

	public OptionalDouble gpPerKill()
	{
		return kills > 0 ? OptionalDouble.of((double) pickedUp.total() / kills) : OptionalDouble.empty();
	}

	/** GP value of task drops picked up so far (left on the floor doesn't count). */
	public long lootTotal()
	{
		return pickedUp.total();
	}

	public double slayerXpPerHour(int xpPerKill)
	{
		OptionalDouble kph = killsPerHour();
		return kph.isPresent() ? kph.getAsDouble() * xpPerKill : 0;
	}

	public int superiors()
	{
		return superiors;
	}

	public Optional<BestDrop> bestDrop()
	{
		return Optional.ofNullable(best);
	}

	public OptionalInt killsUntilFoodRunsOut()
	{
		return supplies.killsUntilFoodRunsOut();
	}

	/** Fraction (0-1) of the way to the next level after finishing the task. */
	public double levelProgressAtTaskEnd(int currentXp, int xpPerKill)
	{
		long xp = (long) currentXp + (long) remaining * xpPerKill;
		int level = levelForXp(xp);
		if (level >= 99)
		{
			return 1.0;
		}
		long lo = xpForLevel(level);
		long hi = xpForLevel(level + 1);
		return (xp - lo) / (double) (hi - lo);
	}

	static long xpForLevel(int level)
	{
		double points = 0;
		for (int l = 1; l < level; l++)
		{
			points += Math.floor(l + 300 * Math.pow(2, l / 7.0));
		}
		return (long) Math.floor(points / 4);
	}

	public static int levelForXp(long xp)
	{
		int level = 1;
		while (level < 99 && xpForLevel(level + 1) <= xp)
		{
			level++;
		}
		return level;
	}

	/** True when the next task's streak value is a multiple of 10. */
	public boolean nextTaskIsBonus(int streak)
	{
		return (streak + 1) % 10 == 0;
	}
}

package com.slayercompanion.session;

import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.Value;
import net.runelite.api.ItemID;

/**
 * What charged weapons use up per attack: trident runes, blowpipe scales and darts, revenant ether and so on.
 * Charges live on the server; the client has no varbit for them and only learns the count from "Check"
 * messages. So, like the Weapon Charges plugin hub plugin, this counts attacks instead: one charge per
 * attack, an attack being the wielded weapon's attack animation (or, for Tumeken's shadow, its cast graphic)
 * starting this tick. The blowpipe loops one animation without restarting it, so a blowpipe shot is its
 * animation at frame 0. Each charge is costed as the materials it is made from (OSRS wiki), which the
 * caller passes to {@link SupplyTracker#addChargeUsed}. As with item supplies, attacks before the task's
 * first kill are not counted.
 * <p>
 * Blowpipe darts: each shot uses 2/3 of a Zulrah's scale on average, and loses a dart at the rate of the
 * worn ranged cape (Ava's assembler or Dizana's quiver 20%, accumulator 28%, attractor 40%, none 100%).
 * The dart type is learnt from the "Check" message or from darts leaving the inventory while a blowpipe is
 * carried (loading it); until then darts are not costed.
 * <p>
 * Crystal shards cannot be traded, so crystal weapon charges are priced through the enhanced crystal
 * teleport seed that Amrod trades for 150 shards (100 charges per shard).
 */
public class WeaponCharges
{
	/** Powered staff cast, used by the tridents and the sanguinesti staff. */
	public static final int POWERED_STAFF_ANIMATION = 11430;
	/** Tumeken's shadow's cast graphic; the staff has no animation of its own. */
	public static final int SHADOW_GRAPHIC = 2125;
	public static final Set<Integer> BLOWPIPE_ANIMATIONS = Set.of(5061, 10656);
	public static final Set<Integer> BLOWPIPE_IDS = Set.of(ItemID.TOXIC_BLOWPIPE, ItemID.BLAZING_BLOWPIPE);
	/** Darts a blowpipe can hold. */
	public static final Set<Integer> DART_IDS = Set.of(ItemID.BRONZE_DART, ItemID.IRON_DART, ItemID.STEEL_DART,
		ItemID.BLACK_DART, ItemID.MITHRIL_DART, ItemID.ADAMANT_DART, ItemID.RUNE_DART, ItemID.AMETHYST_DART,
		ItemID.DRAGON_DART);
	/**
	 * Items used only to charge weapons. Charging moves them into the weapon rather than using them, so the
	 * supply tracker should {@link SupplyTracker#ignore} them; they are costed here when the charge is spent.
	 */
	public static final Set<Integer> MATERIAL_IDS = Set.of(ItemID.ZULRAHS_SCALES, ItemID.REVENANT_ETHER,
		ItemID.VIAL_OF_BLOOD);

	private static final double SCALES_PER_SHOT = 2 / 3.0;
	private static final Pattern DARTS_CHECK = Pattern.compile("^Darts: (\\w+)(?: dart)? x [\\d,]+\\. Scales:");
	private static final Pattern NO_DARTS_CHECK = Pattern.compile("^Darts: None\\. Scales:");
	private static final Map<String, Integer> DART_NAMES = Map.of("Bronze", ItemID.BRONZE_DART,
		"Iron", ItemID.IRON_DART, "Steel", ItemID.STEEL_DART, "Black", ItemID.BLACK_DART,
		"Mithril", ItemID.MITHRIL_DART, "Adamant", ItemID.ADAMANT_DART, "Rune", ItemID.RUNE_DART,
		"Amethyst", ItemID.AMETHYST_DART, "Dragon", ItemID.DRAGON_DART);

	/** How a weapon shows an attack, and the materials one charge is made from. */
	@Value
	static class Weapon
	{
		Set<Integer> animations;
		Set<Integer> graphics;
		Map<Integer, Double> perCharge;
	}

	private static final Map<Integer, Weapon> WEAPONS = new HashMap<>();

	static
	{
		Set<Integer> staff = Set.of(POWERED_STAFF_ANIMATION, 1167);
		Map<Integer, Double> seas = Map.of(ItemID.DEATH_RUNE, 1.0, ItemID.CHAOS_RUNE, 1.0, ItemID.FIRE_RUNE, 5.0,
			ItemID.COINS_995, 10.0);
		Map<Integer, Double> swamp = Map.of(ItemID.DEATH_RUNE, 1.0, ItemID.CHAOS_RUNE, 1.0, ItemID.FIRE_RUNE, 5.0,
			ItemID.ZULRAHS_SCALES, 1.0);
		add(staff, Set.of(), seas, ItemID.TRIDENT_OF_THE_SEAS, ItemID.TRIDENT_OF_THE_SEAS_FULL,
			ItemID.TRIDENT_OF_THE_SEAS_E, ItemID.TRIDENT_OF_THE_SEAS_O, ItemID.TRIDENT_OF_THE_SEAS_FULL_O,
			ItemID.TRIDENT_OF_THE_SEAS_E_O);
		add(staff, Set.of(), swamp, ItemID.TRIDENT_OF_THE_SWAMP, ItemID.TRIDENT_OF_THE_SWAMP_E,
			ItemID.TRIDENT_OF_THE_SWAMP_O, ItemID.TRIDENT_OF_THE_SWAMP_E_O);
		add(staff, Set.of(), Map.of(ItemID.BLOOD_RUNE, 2.0), ItemID.SANGUINESTI_STAFF, ItemID.HOLY_SANGUINESTI_STAFF);
		add(Set.of(), Set.of(SHADOW_GRAPHIC), Map.of(ItemID.SOUL_RUNE, 2.0, ItemID.CHAOS_RUNE, 5.0),
			ItemID.TUMEKENS_SHADOW);
		add(Set.of(8056), Set.of(), Map.of(ItemID.BLOOD_RUNE, 2.0, ItemID.VIAL_OF_BLOOD, 0.01),
			ItemID.SCYTHE_OF_VITUR, ItemID.HOLY_SCYTHE_OF_VITUR, ItemID.SANGUINE_SCYTHE_OF_VITUR);

		Map<Integer, Double> ether = Map.of(ItemID.REVENANT_ETHER, 1.0);
		add(Set.of(1167, 1978, 1979, 1162, POWERED_STAFF_ANIMATION, 7855, 811, 9961), Set.of(), ether,
			ItemID.ACCURSED_SCEPTRE, ItemID.ACCURSED_SCEPTRE_A, ItemID.THAMMARONS_SCEPTRE, ItemID.THAMMARONS_SCEPTRE_A);
		add(Set.of(426, 9964), Set.of(), ether, ItemID.CRAWS_BOW, ItemID.WEBWEAVER_BOW);
		add(Set.of(245, 9963), Set.of(), ether, ItemID.VIGGORAS_CHAINMACE, ItemID.URSINE_CHAINMACE);

		Map<Integer, Double> crystal = Map.of(ItemID.ENHANCED_CRYSTAL_TELEPORT_SEED, 1 / 15000.0);
		add(Set.of(426), Set.of(), crystal, ItemID.BOW_OF_FAERDHINEN, ItemID.CRYSTAL_BOW);
		add(Set.of(390, 386), Set.of(), crystal, ItemID.BLADE_OF_SAELDOR);
	}

	private static void add(Set<Integer> animations, Set<Integer> graphics, Map<Integer, Double> perCharge,
		int... itemIds)
	{
		Weapon w = new Weapon(animations, graphics, perCharge);
		for (int id : itemIds)
		{
			WEAPONS.put(id, w);
		}
	}

	private boolean started;
	private long attacks;
	private int dartId = -1;
	private Map<Integer, Integer> lastCarried;

	/** Clears attacks for a new task. The dart type is kept. */
	public void reset()
	{
		started = false;
		attacks = 0;
	}

	/** Records {@code n} task kills; the first one starts counting. */
	public void onKill(int n)
	{
		if (n > 0)
		{
			started = true;
		}
	}

	/**
	 * Takes this tick's attack reading.
	 *
	 * @param weaponId         item in the weapon slot, or -1
	 * @param capeId           item in the cape slot, or -1 (for the blowpipe's dart loss)
	 * @param animation        the player's animation now
	 * @param animationFrame   its frame now
	 * @param animationStarted the animation was set this tick
	 * @param graphic          the player's graphic now
	 * @param graphicStarted   the graphic was set this tick
	 * @return materials one attack used, item id to quantity (fractional); empty when there was no attack
	 */
	public Map<Integer, Double> onTick(int weaponId, int capeId, int animation, int animationFrame,
		boolean animationStarted, int graphic, boolean graphicStarted)
	{
		if (!started)
		{
			return Collections.emptyMap();
		}
		if (BLOWPIPE_IDS.contains(weaponId))
		{
			if (!BLOWPIPE_ANIMATIONS.contains(animation) || animationFrame != 0)
			{
				return Collections.emptyMap();
			}
			attacks++;
			Map<Integer, Double> m = new HashMap<>();
			m.put(ItemID.ZULRAHS_SCALES, SCALES_PER_SHOT);
			if (dartId != -1)
			{
				m.put(dartId, dartLoss(capeId));
			}
			return m;
		}
		Weapon w = WEAPONS.get(weaponId);
		if (w == null
			|| !(animationStarted && w.getAnimations().contains(animation)
			|| graphicStarted && w.getGraphics().contains(graphic)))
		{
			return Collections.emptyMap();
		}
		attacks++;
		return w.getPerCharge();
	}

	/** Darts lost per blowpipe shot with this cape worn. */
	static double dartLoss(int capeId)
	{
		switch (capeId)
		{
			case ItemID.AVAS_ASSEMBLER:
			case ItemID.AVAS_ASSEMBLER_L:
			case ItemID.ASSEMBLER_MAX_CAPE:
			case ItemID.ASSEMBLER_MAX_CAPE_L:
			case ItemID.MASORI_ASSEMBLER:
			case ItemID.MASORI_ASSEMBLER_L:
			case ItemID.MASORI_ASSEMBLER_MAX_CAPE:
			case ItemID.MASORI_ASSEMBLER_MAX_CAPE_L:
			case ItemID.DIZANAS_QUIVER:
			case ItemID.DIZANAS_QUIVER_L:
			case ItemID.BLESSED_DIZANAS_QUIVER:
			case ItemID.BLESSED_DIZANAS_QUIVER_L:
			case ItemID.DIZANAS_QUIVER_UNCHARGED:
			case ItemID.DIZANAS_QUIVER_L_UNCHARGED:
			case ItemID.DIZANAS_MAX_CAPE:
			case ItemID.DIZANAS_MAX_CAPE_L:
				return 0.2;
			case ItemID.AVAS_ACCUMULATOR:
			case ItemID.ACCUMULATOR_MAX_CAPE:
			case ItemID.RANGING_CAPE:
			case ItemID.RANGING_CAPET:
			case ItemID.MAX_CAPE:
				return 0.28;
			case ItemID.AVAS_ATTRACTOR:
				return 0.4;
			default:
				return 1.0;
		}
	}

	/** Learns the blowpipe's dart type from its "Check" message (tags already removed). */
	public void onChatMessage(String message)
	{
		Matcher m = DARTS_CHECK.matcher(message);
		if (m.find())
		{
			dartId = DART_NAMES.getOrDefault(m.group(1), dartId);
		}
		else if (NO_DARTS_CHECK.matcher(message).find())
		{
			dartId = -1;
		}
	}

	/**
	 * Learns the blowpipe's dart type from darts leaving the player while a blowpipe is carried (loading it).
	 *
	 * @param counts item id to quantity across inventory, worn equipment and rune pouch
	 */
	public void onCarried(Map<Integer, Integer> counts)
	{
		Map<Integer, Integer> before = lastCarried;
		lastCarried = new HashMap<>(counts);
		if (before == null || !carriesBlowpipe(before) || !carriesBlowpipe(counts))
		{
			return;
		}
		for (int id : DART_IDS)
		{
			if (counts.getOrDefault(id, 0) < before.getOrDefault(id, 0))
			{
				dartId = id;
			}
		}
	}

	private static boolean carriesBlowpipe(Map<Integer, Integer> counts)
	{
		for (int id : BLOWPIPE_IDS)
		{
			if (counts.getOrDefault(id, 0) > 0)
			{
				return true;
			}
		}
		return false;
	}

	/** The blowpipe's dart item id, or -1 while unknown. */
	public int dartId()
	{
		return dartId;
	}

	/** Charged-weapon attacks counted this task. */
	public long attacks()
	{
		return attacks;
	}

	/** Whether an item id is a weapon this tracker counts charges for. */
	public static boolean isChargedWeapon(int itemId)
	{
		return BLOWPIPE_IDS.contains(itemId) || WEAPONS.containsKey(itemId);
	}
}

package com.slayercompanion.task;

import com.slayercompanion.data.SlayerTask;
import java.util.Optional;
import lombok.Value;

/** Snapshot of the player's active slayer assignment. */
@Value
public class CurrentTask
{
	SlayerTask task;
	int remaining;
	int initialAmount;
	Optional<String> konarLocation;
	/** Lowercase master id (matches tasks.json), when seen in an assignment chat message. */
	Optional<String> master;
	int streak;
}

package com.slayercompanion.task;

import com.slayercompanion.data.GameData;
import com.slayercompanion.data.Monster;
import com.slayercompanion.data.SlayerTask;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.gameval.DBTableID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.api.gameval.VarbitID;

/** Reads the active slayer task from client state, the same way RuneLite's SlayerPlugin does. */
public class TaskTracker
{
	/** Varp 395 value meaning "boss task"; the actual boss is in the SLAYER_TARGET_BOSSID varbit. */
	private static final int BOSS_TASK_TARGET = 98;

	private static final Pattern MASTER = Pattern.compile(
		"\\b(Turael|Spria|Mazchna|Vannaka|Chaeldar|Konar|Nieve|Steve|Duradel|Krystilia|Aya)\\b",
		Pattern.CASE_INSENSITIVE);
	private static final Pattern ASSIGNMENT = Pattern.compile("assign|task", Pattern.CASE_INSENSITIVE);

	private final Client client;
	private final GameData data;

	private String master;
	private boolean masterFresh;
	private String lastTaskName;
	private String initialFor;
	private int maxInitial;

	public TaskTracker(Client client, GameData data)
	{
		this.client = client;
		this.data = data;
	}

	/** Remembers the slayer master named in an assignment chat message. */
	public void onChatMessage(String message)
	{
		if (message == null || !ASSIGNMENT.matcher(message).find())
		{
			return;
		}
		Matcher m = MASTER.matcher(message);
		if (m.find())
		{
			master = m.group(1).toLowerCase(Locale.ROOT);
			masterFresh = true;
		}
	}

	/** Restores the initial amount persisted by the plugin; the max of this and values seen is kept. */
	public void rememberInitialAmount(String taskName, int amount)
	{
		if (taskName == null)
		{
			return;
		}
		String key = taskName.toLowerCase(Locale.ROOT);
		if (key.equals(initialFor))
		{
			maxInitial = Math.max(maxInitial, amount);
		}
		else
		{
			initialFor = key;
			maxInitial = amount;
		}
	}

	public Optional<CurrentTask> read()
	{
		int remaining = client.getVarpValue(VarPlayerID.SLAYER_COUNT);
		if (remaining <= 0)
		{
			return Optional.empty();
		}
		String name = taskName(client.getVarpValue(VarPlayerID.SLAYER_TARGET));
		if (name == null)
		{
			return Optional.empty();
		}

		String key = name.toLowerCase(Locale.ROOT);
		if (!key.equals(lastTaskName))
		{
			if (!masterFresh)
			{
				master = null;
			}
			masterFresh = false;
			lastTaskName = key;
		}
		if (!key.equals(initialFor))
		{
			initialFor = key;
			maxInitial = remaining;
		}
		maxInitial = Math.max(maxInitial, remaining);

		return Optional.of(new CurrentTask(
			resolve(name),
			remaining,
			maxInitial,
			konarLocation(),
			Optional.ofNullable(master),
			client.getVarbitValue(VarbitID.SLAYER_TASKS_COMPLETED)));
	}

	/** True when an NPC with this name is one of the task's monsters; never true for a task with no monster ids. */
	public static boolean isTaskNpcName(String npcName, SlayerTask task, GameData data)
	{
		if (npcName == null)
		{
			return false;
		}
		for (int id : task.getMonsterIds())
		{
			Optional<Monster> m = data.monster(id);
			if (m.isPresent() && GameData.baseName(m.get().getName()).equalsIgnoreCase(npcName))
			{
				return true;
			}
		}
		return false;
	}

	/** True when the task name changed or the remaining count went up (a fresh assignment). */
	public boolean isNewTask(Optional<CurrentTask> previous, Optional<CurrentTask> now)
	{
		if (!now.isPresent())
		{
			return false;
		}
		if (!previous.isPresent())
		{
			return true;
		}
		String a = previous.get().getTask().getName();
		String b = now.get().getTask().getName();
		return !a.equalsIgnoreCase(b) || now.get().getRemaining() > previous.get().getRemaining();
	}

	private String taskName(int target)
	{
		int taskRow;
		if (target == BOSS_TASK_TARGET)
		{
			List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTaskSublist.ID,
				DBTableID.SlayerTaskSublist.COL_TASK_SUBTABLE_ID, 0, client.getVarbitValue(VarbitID.SLAYER_TARGET_BOSSID));
			if (rows == null || rows.isEmpty())
			{
				return null;
			}
			Object[] f = client.getDBTableField(rows.get(0), DBTableID.SlayerTaskSublist.COL_TASK, 0);
			if (f == null || f.length == 0)
			{
				return null;
			}
			taskRow = (Integer) f[0];
		}
		else
		{
			List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerTask.ID, DBTableID.SlayerTask.COL_ID, 0, target);
			if (rows == null || rows.isEmpty())
			{
				return null;
			}
			taskRow = rows.get(0);
		}
		Object[] f = client.getDBTableField(taskRow, DBTableID.SlayerTask.COL_NAME_UPPERCASE, 0);
		return f == null || f.length == 0 ? null : (String) f[0];
	}

	private Optional<String> konarLocation()
	{
		int area = client.getVarpValue(VarPlayerID.SLAYER_AREA);
		if (area <= 0)
		{
			return Optional.empty();
		}
		List<Integer> rows = client.getDBRowsByValue(DBTableID.SlayerArea.ID, DBTableID.SlayerArea.COL_AREA_ID, 0, area);
		if (rows == null || rows.isEmpty())
		{
			return Optional.empty();
		}
		Object[] f = client.getDBTableField(rows.get(0), DBTableID.SlayerArea.COL_AREA_NAME_IN_HELPER, 0);
		return f == null || f.length == 0 ? Optional.empty() : Optional.ofNullable((String) f[0]);
	}

	/**
	 * Finds bundled data for an in-game name, tolerating case and singular/plural differences.
	 * A task with no tasks.json entry (another master's) gets a stub carrying the ids of the
	 * bundled monsters with that name, so gear and stats still work; it has no locations.
	 */
	private SlayerTask resolve(String name)
	{
		Set<String> candidates = new LinkedHashSet<>();
		String lower = name.trim().toLowerCase(Locale.ROOT);
		candidates.add(lower);
		candidates.add(lower + "s");
		candidates.add(lower + "es");
		if (lower.endsWith("s"))
		{
			candidates.add(lower.substring(0, lower.length() - 1));
		}
		if (lower.endsWith("es"))
		{
			candidates.add(lower.substring(0, lower.length() - 2));
		}
		if (lower.endsWith("ies"))
		{
			candidates.add(lower.substring(0, lower.length() - 3) + "y");
		}
		if (lower.endsWith("y"))
		{
			candidates.add(lower.substring(0, lower.length() - 1) + "ies");
		}
		for (String c : candidates)
		{
			Optional<SlayerTask> t = data.taskByName(c);
			if (t.isPresent())
			{
				return t.get();
			}
		}
		SlayerTask stub = new SlayerTask();
		stub.setName(name);
		for (String c : candidates)
		{
			for (int id : data.monsterIdsNamed(c))
			{
				if (!stub.getMonsterIds().contains(id))
				{
					stub.getMonsterIds().add(id);
				}
			}
		}
		return stub;
	}
}

package com.slayercompanion.ui;

import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.image.BufferedImage;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.overlay.WidgetItemOverlay;

/** Fallback for "Show setup in bank" when Bank Tags is unavailable: outlines the setup items in the bank. */
public class BankHighlightOverlay extends WidgetItemOverlay
{
	private final ItemManager itemManager;
	private volatile Set<Integer> itemIds = Collections.emptySet();

	@Inject
	public BankHighlightOverlay(ItemManager itemManager)
	{
		this.itemManager = itemManager;
		showOnBank();
	}

	/** Canonical item ids to outline; empty turns highlighting off. */
	public void setItems(Set<Integer> ids)
	{
		itemIds = ids == null ? Collections.emptySet() : Collections.unmodifiableSet(new HashSet<>(ids));
	}

	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		Set<Integer> ids = itemIds;
		if (ids.isEmpty() || !(ids.contains(itemId) || ids.contains(itemManager.canonicalize(itemId))))
		{
			return;
		}
		Rectangle bounds = widgetItem.getCanvasBounds();
		BufferedImage outline = itemManager.getItemOutline(itemId, widgetItem.getQuantity(), ColorScheme.BRAND_ORANGE);
		graphics.drawImage(outline, (int) bounds.getX(), (int) bounds.getY(), null);
	}
}

package com.slayercompanion.ui;

import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ScriptID;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.banktags.BankTagsPlugin;
import net.runelite.client.plugins.banktags.BankTagsService;
import net.runelite.client.plugins.banktags.TagManager;
import net.runelite.client.plugins.banktags.tabs.Layout;
import net.runelite.client.plugins.banktags.tabs.LayoutManager;

/**
 * "Show setup in bank": a temporary Bank Tags tab holding only the recommended setup, laid out by
 * {@link com.slayercompanion.gear.SetupLayout}. Same approach as Inventory Setups: a registered (not
 * item-tagged) tag plus a saved layout, opened with the tag name hidden. Client thread only.
 * Requires {@code @PluginDependency(BankTagsPlugin.class)} on the plugin so the Bank Tags services are injectable.
 */
@Slf4j
public class BankSetupTab
{
	public static final String TAG = "slayer companion";
	private static final int OPTIONS = BankTagsService.OPTION_ALLOW_MODIFICATIONS | BankTagsService.OPTION_HIDE_TAG_NAME;

	private final Client client;
	private final ItemManager itemManager;
	private final PluginManager pluginManager;
	private final BankTagsService bankTagsService;
	private final TagManager tagManager;
	private final LayoutManager layoutManager;

	private volatile Set<Integer> itemIds = Collections.emptySet();
	private int[] layout;
	private boolean shown;

	@Inject
	BankSetupTab(Client client, ItemManager itemManager, PluginManager pluginManager, BankTagsService bankTagsService,
		TagManager tagManager, LayoutManager layoutManager)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.pluginManager = pluginManager;
		this.bankTagsService = bankTagsService;
		this.tagManager = tagManager;
		this.layoutManager = layoutManager;
	}

	/** Whether the Bank Tags plugin is enabled, so the tab can be used instead of the highlight overlay. */
	public boolean isAvailable()
	{
		for (Plugin p : pluginManager.getPlugins())
		{
			if (p instanceof BankTagsPlugin)
			{
				return pluginManager.isPluginEnabled(p);
			}
		}
		return false;
	}

	public boolean isShown()
	{
		return shown;
	}

	/**
	 * Shows (or refreshes) the tab with this layout of raw item ids; they are canonicalized to bank ids here.
	 * Opens it now if the bank is open, otherwise the next time it opens.
	 * @return false if Bank Tags rejected it, in which case the caller should fall back to the overlay
	 */
	public boolean show(int[] rawLayout)
	{
		int[] canon = new int[rawLayout.length];
		Set<Integer> ids = new HashSet<>();
		for (int i = 0; i < rawLayout.length; i++)
		{
			canon[i] = rawLayout[i] < 0 ? rawLayout[i] : itemManager.canonicalize(rawLayout[i]);
			if (canon[i] >= 0)
			{
				ids.add(canon[i]);
			}
		}
		if (shown && Arrays.equals(canon, layout))
		{
			return true;
		}
		try
		{
			itemIds = Collections.unmodifiableSet(ids);
			boolean refresh = shown;
			if (!refresh)
			{
				tagManager.registerTag(TAG, this::contains);
			}
			layoutManager.saveLayout(new Layout(TAG, canon));
			layout = canon;
			shown = true;
			// A refresh only redraws the tab if it is the one on screen; it never switches tabs on the player.
			if (!refresh || isOpen())
			{
				openIfBankOpen();
			}
			return true;
		}
		catch (RuntimeException | LinkageError e)
		{
			log.warn("Bank Tags tab unavailable", e);
			hide();
			return false;
		}
	}

	/** Removes a layout left behind if the client closed while the tab was shown. */
	public void clearLeftovers()
	{
		try
		{
			layoutManager.removeLayout(TAG);
		}
		catch (RuntimeException | LinkageError e)
		{
			log.warn("Failed to clear Bank Tags layout", e);
		}
	}

	/** Closes the tab if it is open and removes the tag and its layout. */
	public void hide()
	{
		if (!shown)
		{
			return;
		}
		shown = false;
		layout = null;
		itemIds = Collections.emptySet();
		try
		{
			if (isOpen())
			{
				bankTagsService.closeBankTag();
			}
			tagManager.unregisterTag(TAG);
			layoutManager.removeLayout(TAG);
		}
		catch (RuntimeException | LinkageError e)
		{
			log.warn("Failed to remove Bank Tags tab", e);
		}
	}

	private boolean contains(int itemId)
	{
		return itemIds.contains(itemId);
	}

	private boolean isOpen()
	{
		return TAG.equals(bankTagsService.getActiveTag());
	}

	private void openIfBankOpen()
	{
		if (shown && client.getWidget(InterfaceID.Bankmain.UNIVERSE) != null)
		{
			bankTagsService.openBankTag(TAG, OPTIONS);
		}
	}

	/** Runs after Bank Tags' own handler (as Inventory Setups does) so the tab opens each time the bank does. */
	@Subscribe(priority = -1)
	public void onScriptPreFired(ScriptPreFired e)
	{
		if (e.getScriptId() == ScriptID.BANKMAIN_INIT && shown)
		{
			try
			{
				openIfBankOpen();
			}
			catch (RuntimeException e2)
			{
				log.warn("Failed to open Bank Tags tab", e2);
			}
		}
	}
}

package com.slayercompanion.ui;

import javax.swing.BorderFactory;
import javax.swing.border.Border;

/** Inner stone box (#2e271e, 1px dark edge) stacking rows like {@link Ui.Column}; "best" gets the orange frame. */
class Card extends Ui.Column
{
	private final int pad;

	Card(int gap, int pad)
	{
		super(gap);
		this.pad = pad;
		setOpaque(true);
		setBackground(Ui.CARD);
		setBest(false);
	}

	/** Gap 4, padding 8. */
	Card()
	{
		this(4, 8);
	}

	/** Orange frame with a brown inner line, for the recommended pick. */
	Card setBest(boolean best)
	{
		Border edge = best
			? BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(Ui.ORANGE),
				BorderFactory.createLineBorder(Ui.BEST_INNER))
			: BorderFactory.createLineBorder(Ui.EDGE_DARK);
		int p = best ? pad - 1 : pad;
		setBorder(BorderFactory.createCompoundBorder(edge, BorderFactory.createEmptyBorder(p, p, p, p)));
		return this;
	}

	/** Light-edged variant (the upgrade box: 1px #6b5a42). */
	Card setRaised()
	{
		setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(Ui.BUTTON_TOP),
			BorderFactory.createEmptyBorder(pad, pad, pad, pad)));
		return this;
	}
}

package com.slayercompanion.ui;

import java.text.NumberFormat;
import java.util.Locale;

/** Number and time formatting shared by the panel view models. */
final class Format
{
	private Format()
	{
	}

	/** 1,840 / 12.4k / 101k / 1.2m. */
	static String compact(double value)
	{
		double v = Math.abs(value);
		String sign = value < 0 ? "-" : "";
		if (v < 10_000)
		{
			return sign + NumberFormat.getIntegerInstance(Locale.US).format(Math.round(v));
		}
		if (v < 100_000)
		{
			return sign + oneDecimal(v / 1000) + "k";
		}
		if (v < 1_000_000)
		{
			return sign + Math.round(v / 1000) + "k";
		}
		return sign + oneDecimal(v / 1_000_000) + "m";
	}

	private static String oneDecimal(double v)
	{
		String s = String.format(Locale.US, "%.1f", v);
		return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
	}

	/** ~1m 20s / ~2m / ~45s. */
	static String travel(double seconds)
	{
		long s = Math.round(seconds);
		if (s < 60)
		{
			return "~" + s + "s";
		}
		return "~" + (s / 60) + "m" + (s % 60 == 0 ? "" : " " + (s % 60) + "s");
	}

	static String ordinal(int n)
	{
		int mod100 = n % 100;
		if (mod100 >= 11 && mod100 <= 13)
		{
			return n + "th";
		}
		switch (n % 10)
		{
			case 1:
				return n + "st";
			case 2:
				return n + "nd";
			case 3:
				return n + "rd";
			default:
				return n + "th";
		}
	}

	static String capitalize(String s)
	{
		return s == null || s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}
}

package com.slayercompanion.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import javax.swing.JComponent;

/** Flat bar (.track): dark well with a 1px black edge, a coloured fill, and an optional white marker. */
class Gauge extends JComponent
{
	private final double fraction;
	private final Color fill;
	private final int height;
	private double marker = -1;

	/** @param height total height including the 1px edge; the mockup uses 8 (6px fill) and 9 for supplies. */
	Gauge(double fraction, Color fill, int height)
	{
		this.fraction = clamp(fraction);
		this.fill = fill;
		this.height = height;
		setOpaque(false);
	}

	/** Draws a 2px white tick at this fraction (e.g. where the task ends). */
	Gauge marker(double at)
	{
		marker = clamp(at);
		repaint();
		return this;
	}

	private static double clamp(double f)
	{
		return Double.isNaN(f) ? 0 : Math.max(0, Math.min(1, f));
	}

	@Override
	public Dimension getPreferredSize()
	{
		// Room above and below the bar for the marker overhang.
		return new Dimension(20, height + (marker >= 0 ? 6 : 0));
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		int w = getWidth();
		int h = Math.min(height, getHeight());
		int y = (getHeight() - h) / 2;
		g2.setColor(Color.BLACK);
		g2.fillRect(0, y, w, h);
		g2.setColor(Ui.EDGE_DARK);
		g2.fillRect(1, y + 1, w - 2, h - 2);
		int fw = (int) Math.round((w - 2) * fraction);
		if (fw > 0)
		{
			g2.setColor(fill);
			g2.fillRect(1, y + 1, fw, h - 2);
		}
		if (marker >= 0)
		{
			int mx = 1 + (int) Math.round((w - 2) * marker) - 1;
			mx = Math.max(0, Math.min(w - 2, mx));
			g2.setColor(Color.WHITE);
			g2.fillRect(mx, Math.max(0, y - 3), 2, Math.min(getHeight(), h + 6));
		}
		g2.dispose();
	}
}

