package com.slayercompanion.ui;

import com.slayercompanion.data.Monster;
import com.slayercompanion.session.CannonRunway;
import com.slayercompanion.session.FinishingItems;
import com.slayercompanion.session.PrayerRunway;
import com.slayercompanion.session.SlayerPoints;
import com.slayercompanion.session.TaskSession;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.OptionalDouble;
import java.util.OptionalInt;
import lombok.Value;
import net.runelite.api.ItemID;

/** What the On task tab shows: progress, live stats, supplies and worth-knowing lines. */
@Value
public class OnTaskModel
{
	static final String STARTS_COUNTING = "Tracking starts at first kill";
	private static final String NONE = "—";
	/** First kill starts the clock, so timing needs a second kill to mean anything. */
	private static final int MIN_KILLS_FOR_TIMING = 2;

	@Value
	public static class Stat
	{
		String label;
		String value;
		/** Small trailing unit such as " min"; empty for none. */
		String unit;
	}

	/** One row of the Supplies list: what it is, how long it lasts and how that compares to the task. */
	@Value
	public static class Supply
	{
		/** Shown name: "Food", "Prayer", "Fungicide charges", "Cannonballs". */
		String label;
		/** Item picture id, or -1 to use {@link #skillIcon}. */
		int iconItemId;
		/** Bundled skill icon name ("prayer"), or null. */
		String skillIcon;
		/** Right-hand text, e.g. "lasts ~120 kills". */
		String value;
		/** Shortfall warning shown above the row, or null. */
		String warning;
		/** Kills this supply lasts, or -1 before there is an estimate (no gauge then). */
		int killsItLasts;
		/** Bar fill, min(1, lasts / kills left); -1 with no estimate. */
		double fraction;
		/** Where the task ends on the bar (kills left / lasts) when the supply outlasts the task; -1 for none. */
		double taskEndAt;
		/** Runs out before the task ends. */
		boolean runsShort;

		static Supply of(String label, int iconItemId, String skillIcon, String value, String warning,
			OptionalInt lasts, int killsLeft)
		{
			if (!lasts.isPresent() || killsLeft <= 0)
			{
				return new Supply(label, iconItemId, skillIcon, value, warning, lasts.orElse(-1), -1, -1,
					warning != null);
			}
			int k = Math.max(0, lasts.getAsInt());
			double fraction = Math.min(1, k / (double) killsLeft);
			double end = k > killsLeft ? killsLeft / (double) k : -1;
			return new Supply(label, iconItemId, skillIcon, value, warning, k, fraction, end, k < killsLeft);
		}
	}

	boolean noTask;
	String message;
	String header;
	int remaining;
	int total;
	/** Fraction of the task done, 0-1. */
	double progress;
	List<Stat> stats;
	boolean timingHidden;
	String foodWarning;
	/** "{n} left" for food in the inventory, plus " · lasts ~N kills" when known; null when unknown. */
	String foodLine;
	String prayerWarning;
	String prayerLabel;
	/** "Lasts ~25 kills", or "43 prayer points" before any drain is seen. */
	String prayer;
	String finishingWarning;
	/** Finishing item label, e.g. "Ice coolers"; null for tasks that need none. */
	String finishingLabel;
	/** "23 · 40 left"; null for tasks that need none. */
	String finishingLine;
	String cannonWarning;
	/** "~30 kills · 412 balls"; null with no cannon placed. */
	String cannonLine;
	String superiors;
	String bestDrop;
	/** "Toward lvl {n+1} by task end"; null at 99. */
	String levelLabel;
	String levelValue;
	String nextTask;
	/** "412 → 422", or just the current points when the master is unknown; null when points are unknown. */
	String slayerPoints;
	String note;
	/** Task name alone, for the hero title. */
	String taskName;
	/** Selected location, or null. */
	String locationName;
	/** "55 of 142 done", plus " · ~46 min left" once timing is known. */
	String progressLine;
	/** Supplies rows in display order (food, prayer, finishing item, cannonballs); only rows that apply. */
	List<Supply> supplies;
	/** Item id of the best drop for its icon, or -1. */
	int bestDropItemId;
	/** Fraction (0-1) toward the next level at task end; -1 at 99. */
	double levelFraction;
	/** Profit per kill is known and below zero. */
	boolean profitNegative;

	public static OnTaskModel noTask()
	{
		return new OnTaskModel(true, PrepModel.NO_TASK, null, 0, 0, 0, Collections.emptyList(), true, null, null,
			null, null, null, null, null, null, null, null, null, null, null, null, null, null, null,
			null, null, null, Collections.emptyList(), -1, -1, false);
	}

	/**
	 * @param locationName      selected location, or null
	 * @param monster           monster at the selected location (for xp per kill), or null
	 * @param foodInInventory   food items in the inventory, or negative when unknown
	 * @param slayerXp          current Slayer experience
	 * @param prayerCurrent     prayer points now
	 * @param prayerMax         base prayer level
	 * @param streak            completed-task streak
	 * @param slayerPoints      current slayer reward points, or negative when unknown
	 * @param master            lowercase master id, or null when unknown
	 * @param pointsStreak      streak that decides this master's points (Krystilia's wilderness streak for her)
	 */
	public static OnTaskModel build(String taskName, String locationName, TaskSession s, Monster monster,
		int foodInInventory, int prayerCurrent, int prayerMax, int slayerXp, int streak, int slayerPoints,
		String master, int pointsStreak)
	{
		int xpPerKill = monster == null ? 0 : monster.getSlayerXp();
		int remaining = s.remaining();
		int total = Math.max(s.total(), remaining);
		double progress = total > 0 ? (total - remaining) / (double) total : 0;
		boolean hide = s.kills() < MIN_KILLS_FOR_TIMING;

		List<Stat> stats = new ArrayList<>();
		OptionalDouble left = s.secondsLeft();
		OptionalDouble perKill = s.secondsPerKill();
		OptionalDouble kph = s.killsPerHour();
		OptionalDouble gpk = s.gpPerKill();
		stats.add(hide || !left.isPresent() ? new Stat("Time left", NONE, "")
			: new Stat("Time left", "~" + Math.round(left.getAsDouble() / 60), " min"));
		stats.add(hide || !perKill.isPresent() ? new Stat("Per kill", NONE, "")
			: new Stat("Per kill", String.valueOf(Math.round(perKill.getAsDouble())), "s"));
		OptionalDouble cpk = s.supplies().costPerKill();
		stats.add(new Stat("GP per kill", gpk.isPresent() ? Format.compact(gpk.getAsDouble()) : NONE, ""));
		stats.add(new Stat("Supplies / kill", cpk.isPresent() ? Format.compact(cpk.getAsDouble()) : NONE, ""));
		stats.add(new Stat("Profit / kill", gpk.isPresent() && cpk.isPresent()
			? Format.compact(gpk.getAsDouble() - cpk.getAsDouble()) : NONE, ""));
		stats.add(new Stat("Loot so far", Format.compact(s.lootTotal()), ""));
		stats.add(hide || !kph.isPresent() ? new Stat("Kills / hr", NONE, "")
			: new Stat("Kills / hr", String.valueOf(Math.round(kph.getAsDouble())), ""));
		stats.add(hide || !kph.isPresent() ? new Stat("Slayer XP / hr", NONE, "")
			: new Stat("Slayer XP / hr", Format.compact(s.slayerXpPerHour(xpPerKill)), ""));

		OptionalInt foodKills = s.killsUntilFoodRunsOut();
		String foodWarning = foodKills.isPresent() && foodKills.getAsInt() < remaining
			? "Food runs out in ~" + foodKills.getAsInt() + " kills" : null;
		String foodLine = foodInInventory < 0 ? null : foodInInventory + " left"
			+ (foodKills.isPresent() ? " · lasts ~" + foodKills.getAsInt() + " kills" : "");

		OptionalInt prayerKills = s.prayer().killsLeft(prayerCurrent, s.supplies(), prayerMax);
		String prayerWarning = PrayerRunway.warning(prayerKills, remaining).orElse(null);

		String finishingLabel = null;
		String finishingLine = null;
		String finishingWarning = null;
		FinishingItems.Need need = FinishingItems.forTask(taskName).orElse(null);
		if (need != null && remaining > 0)
		{
			int uses = need.usesCarried(s.supplies());
			finishingLabel = need.getLabel();
			finishingLine = (uses > 0 ? String.valueOf(uses) : "None") + " · " + remaining + " left";
			finishingWarning = need.warning(uses, remaining).orElse(null);
		}

		CannonRunway cannon = s.cannon();
		String cannonLine = cannon.summary().orElse(null);
		String cannonWarning = cannon.warning(remaining).orElse(null);

		String points = null;
		if (slayerPoints >= 0)
		{
			points = master != null && SlayerPoints.isKnown(master)
				? SlayerPoints.summary(slayerPoints, SlayerPoints.pointsForTask(master, pointsStreak))
				: String.valueOf(slayerPoints);
		}

		String bestDrop = s.bestDrop().map(b -> b.getName() + " · " + Format.compact(b.getValue())
			+ (b.getRate() > 0 ? " 1/" + Math.round(1 / b.getRate()) : "")).orElse("None yet");

		String levelLabel = null;
		String levelValue = null;
		double levelFraction = -1;
		int endLevel = TaskSession.levelForXp((long) slayerXp + (long) remaining * xpPerKill);
		if (endLevel < 99)
		{
			levelLabel = "Toward lvl " + (endLevel + 1) + " by task end";
			levelFraction = s.levelProgressAtTaskEnd(slayerXp, xpPerKill);
			levelValue = Math.round(levelFraction * 100) + "%";
		}

		// The streak counts finished tasks, so the one in progress is streak + 1.
		int thisTask = streak + 1;
		String nextTask = s.nextTaskIsBonus(streak) ? Format.ordinal(thisTask) + " · bonus points"
			: Format.ordinal(thisTask) + " · bonus on " + Format.ordinal((thisTask / 10 + 1) * 10);

		List<Supply> supplies = new ArrayList<>();
		if (foodLine != null)
		{
			int foodId = s.supplies().mainFoodId();
			supplies.add(Supply.of("Food", foodId > 0 ? foodId : ItemID.SHARK, null, foodLine, foodWarning, foodKills,
				remaining));
		}
		String prayerLine = PrayerRunway.line(prayerKills, prayerCurrent);
		supplies.add(Supply.of("Prayer", -1, "prayer", prayerLine, prayerWarning, prayerKills, remaining));
		if (finishingLine != null)
		{
			supplies.add(Supply.of(finishingLabel, finishingIcon(need, s), null, finishingLine, finishingWarning,
				OptionalInt.of(need.usesCarried(s.supplies())), remaining));
		}
		if (cannonLine != null)
		{
			supplies.add(Supply.of("Cannonballs", ItemID.STEEL_CANNONBALL, null, cannonLine, cannonWarning,
				cannon.killsLeft(), remaining));
		}

		String progressLine = (total - remaining) + " of " + total + " done"
			+ (hide || !left.isPresent() ? "" : " · ~" + Math.round(left.getAsDouble() / 60) + " min left");
		boolean profitNegative = gpk.isPresent() && cpk.isPresent()
			&& Math.round(gpk.getAsDouble() - cpk.getAsDouble()) < 0;
		int bestId = s.bestDrop().map(TaskSession.BestDrop::getItemId).orElse(-1);

		String header = locationName == null ? taskName : taskName + " · " + locationName;
		return new OnTaskModel(false, null, header, remaining, total, progress, stats, hide, foodWarning, foodLine,
			prayerWarning, "Prayer", PrayerRunway.line(prayerKills, prayerCurrent),
			finishingWarning, finishingLabel, finishingLine, cannonWarning, cannonLine,
			String.valueOf(s.superiors()), bestDrop, levelLabel, levelValue, nextTask, points,
			hide ? STARTS_COUNTING : "Estimated from kills this task", taskName, locationName, progressLine,
			supplies, bestId, levelFraction, profitNegative);
	}

	/** The carried item of a finishing need with the most uses (a fungicide spray), else its fullest item. */
	private static int finishingIcon(FinishingItems.Need need, TaskSession s)
	{
		int icon = -1;
		int best = -1;
		for (java.util.Map.Entry<Integer, Integer> e : need.getUsesPerItem().entrySet())
		{
			int score = e.getValue() + (s.supplies().count(e.getKey()) > 0 ? 1000 : 0);
			if (score > best)
			{
				best = score;
				icon = e.getKey();
			}
		}
		return icon;
	}
}

package com.slayercompanion.ui;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridLayout;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;

/** On task tab: progress ring, live stats, profit, supply runways and task info. */
class OnTaskTab extends Ui.Column
{
	private static final int RING_GAP = 10;
	private static final String NONE = "—";

	private final IconSource icons;

	OnTaskTab(IconSource icons)
	{
		super(0);
		this.icons = icons;
	}

	void show(OnTaskModel m)
	{
		removeAll();
		rebuild(m);
		revalidate();
		repaint();
	}

	private void rebuild(OnTaskModel m)
	{
		if (m.isNoTask())
		{
			addRow(Ui.message(m.getMessage()));
			return;
		}
		addRow(hero(m));
		addRow(stats(m));
		addRow(supplies(m));
		addRow(taskInfo(m));
		addRow(Ui.note(m.getNote()));
	}


	/** Ring with kills left beside the task title, location and progress line. */
	private static JComponent hero(OnTaskModel m)
	{
		Ui.Column hero = Ui.hero();
		JPanel row = new JPanel(new BorderLayout(RING_GAP, 0));
		row.setOpaque(false);
		row.add(new ProgressRing(m.getProgress(), String.valueOf(m.getRemaining()), "left"), BorderLayout.WEST);

		int textWidth = Ui.INNER_WIDTH - 70 - RING_GAP - 16;
		Ui.Column text = new Ui.Column(1);
		String title = m.getTaskName() != null ? m.getTaskName() : m.getHeader();
		text.addRow(Ui.title(title, Ui.ORANGE, textWidth));
		if (m.getLocationName() != null)
		{
			text.addRow(Ui.wrapped(m.getLocationName(), Ui.sans(Font.PLAIN, 11.5f), Ui.MUTED, textWidth));
		}
		if (m.getProgressLine() != null)
		{
			text.addRow(Ui.wrapped(m.getProgressLine(), Ui.sans(Font.PLAIN, 11.5f), Ui.MUTED, textWidth));
		}
		JPanel center = new JPanel(new java.awt.GridBagLayout());
		center.setOpaque(false);
		java.awt.GridBagConstraints g = new java.awt.GridBagConstraints();
		g.weightx = 1;
		g.fill = java.awt.GridBagConstraints.HORIZONTAL;
		center.add(text, g);
		row.add(center, BorderLayout.CENTER);
		hero.addRow(row);
		return hero;
	}

	/** 2x2 stat tiles, then the profit sum card. */
	private static JComponent stats(OnTaskModel m)
	{
		Ui.Column sec = Ui.section();
		JPanel grid = new JPanel(new GridLayout(0, 2, 4, 4));
		grid.setOpaque(false);
		grid.add(tile(m, "Per kill", Ui.TEXT));
		grid.add(tile(m, "Kills / hr", Ui.TEXT));
		grid.add(tile(m, "Slayer XP / hr", Ui.TEXT));
		grid.add(tile(m, "Loot so far", Ui.YELLOW));
		sec.addRow(grid);

		Card profit = new Card(2, 7);
		profit.addRow(sumRow("Loot / kill", stat(m, "GP per kill"), Ui.YELLOW, false));
		String cost = stat(m, "Supplies / kill");
		profit.addRow(sumRow("Supplies / kill", NONE.equals(cost) ? cost : "− " + cost, Ui.BAD, false));
		JPanel line = new JPanel();
		line.setBackground(Ui.EDGE_LIGHT);
		line.setPreferredSize(new Dimension(10, 1));
		profit.addRow(spaced(line, 2));
		profit.addRow(sumRow("Profit / kill", stat(m, "Profit / kill"), m.isProfitNegative() ? Ui.BAD : Ui.OK, true));
		sec.addRow(profit);
		return sec;
	}

	private static JComponent spaced(JComponent c, int v)
	{
		JPanel p = new JPanel(new BorderLayout());
		p.setOpaque(false);
		p.setBorder(BorderFactory.createEmptyBorder(v, 0, v, 0));
		p.add(c, BorderLayout.CENTER);
		return p;
	}

	private static StatTile tile(OnTaskModel m, String label, Color color)
	{
		OnTaskModel.Stat s = find(m, label);
		if (s == null)
		{
			return new StatTile(label, NONE, "", color);
		}
		return new StatTile(label, s.getValue(), s.getUnit(), color);
	}

	private static String stat(OnTaskModel m, String label)
	{
		OnTaskModel.Stat s = find(m, label);
		return s == null ? NONE : s.getValue();
	}

	private static OnTaskModel.Stat find(OnTaskModel m, String label)
	{
		for (OnTaskModel.Stat s : m.getStats())
		{
			if (s.getLabel().equals(label))
			{
				return s;
			}
		}
		return null;
	}

	private static JPanel sumRow(String key, String value, Color color, boolean big)
	{
		JPanel p = new JPanel(new BorderLayout(6, 0));
		p.setOpaque(false);
		p.add(Ui.label(key, Ui.sans(Font.PLAIN, big ? 13f : 11.5f), Ui.FAINT), BorderLayout.WEST);
		p.add(Ui.label(value, Ui.sans(Font.BOLD, big ? 16f : 12f), color), BorderLayout.EAST);
		return p;
	}

	/** Supply runways: bar end = task end; red when short, white tick where the task ends when it lasts longer. */
	private JComponent supplies(OnTaskModel m)
	{
		Ui.Column sec = Ui.section();
		sec.addRow(Ui.header("Supplies", "bar end = task end"));
		for (OnTaskModel.Supply s : m.getSupplies())
		{
			if (s.getWarning() != null)
			{
				sec.addRow(new WarnBox(s.getWarning(), Ui.INNER_WIDTH));
			}
			sec.addRow(supplyRow(s));
		}
		return sec;
	}

	private JComponent supplyRow(OnTaskModel.Supply s)
	{
		Ui.Column col = new Ui.Column(3);
		JPanel top = row(4);
		JPanel left = new JPanel();
		left.setLayout(new BoxLayout(left, BoxLayout.X_AXIS));
		left.setOpaque(false);
		ItemIcon icon = s.getSkillIcon() != null ? ItemIcon.skill(s.getSkillIcon(), ItemIcon.INLINE)
			: ItemIcon.item(icons, s.getIconItemId(), ItemIcon.INLINE);
		left.add(icon);
		left.add(Box.createHorizontalStrut(5));
		left.add(Ui.label(s.getLabel(), Ui.sans(Font.PLAIN, 11.5f), Ui.MUTED));
		top.add(left, BorderLayout.CENTER);
		top.add(Ui.label(s.getValue(), Ui.sans(Font.BOLD, 10f), Ui.MUTED), BorderLayout.EAST);
		col.addRow(top);
		if (s.getFraction() >= 0)
		{
			Gauge gauge = new Gauge(s.getFraction(), s.isRunsShort() ? Ui.BAD : Ui.OK, 9);
			if (s.getTaskEndAt() >= 0)
			{
				gauge.marker(s.getTaskEndAt());
			}
			col.addRow(fixed(gauge));
		}
		return col;
	}

	private JComponent taskInfo(OnTaskModel m)
	{
		Ui.Column sec = Ui.section("Task info");
		JComponent dropIcon = m.getBestDropItemId() > 0
			? ItemIcon.item(icons, m.getBestDropItemId(), ItemIcon.INLINE) : null;
		String drop = m.getBestDrop();
		int rateAt = drop.lastIndexOf(" 1/");
		sec.addRow(kv("Best drop", dropIcon, Ui.label(rateAt < 0 ? drop : drop.substring(0, rateAt),
			Ui.body(), Ui.YELLOW)));
		if (rateAt >= 0)
		{
			JLabel rate = Ui.label("drop rate " + drop.substring(rateAt + 1), Ui.small(), Ui.FAINT);
			rate.setHorizontalAlignment(JLabel.RIGHT);
			sec.addRow(rate);
		}
		sec.addRow(Ui.kv("Superiors", m.getSuperiors(), Ui.TEXT));
		if (m.getSlayerPoints() != null)
		{
			sec.addRow(kv("Slayer points", null, points(m.getSlayerPoints())));
		}
		sec.addRow(Ui.kv("This task", m.getNextTask(), Ui.YELLOW));
		if (m.getLevelLabel() != null)
		{
			Ui.Column lvl = new Ui.Column(3);
			JPanel top = row(6);
			JPanel key = new JPanel();
			key.setLayout(new BoxLayout(key, BoxLayout.X_AXIS));
			key.setOpaque(false);
			key.add(ItemIcon.skill("slayer", ItemIcon.INLINE));
			key.add(Box.createHorizontalStrut(4));
			key.add(Ui.label(m.getLevelLabel(), Ui.sans(Font.PLAIN, 11.5f), Ui.FAINT));
			top.add(key, BorderLayout.CENTER);
			top.add(Ui.label(m.getLevelValue(), Ui.body(), Ui.TEXT), BorderLayout.EAST);
			lvl.addRow(top);
			if (m.getLevelFraction() >= 0)
			{
				lvl.addRow(fixed(new Gauge(m.getLevelFraction(), Ui.BLUE, 8)));
			}
			sec.addRow(spaced(lvl, 2));
		}
		return sec;
	}

	/**
	 * A key / value row that never asks for more width than it gets: the value (EAST) keeps its size and the
	 * key (CENTER) is cut short with "..." if both don't fit, so one long line can't squeeze the whole tab.
	 */
	private static JPanel row(int gap)
	{
		JPanel p = new JPanel(new BorderLayout(gap, 0))
		{
			@Override
			public Dimension getPreferredSize()
			{
				return new Dimension(0, super.getPreferredSize().height);
			}

			@Override
			public Dimension getMinimumSize()
			{
				return getPreferredSize();
			}
		};
		p.setOpaque(false);
		return p;
	}

	/** Gauges have no minimum size of their own; keep their height when the column is squeezed. */
	private static Gauge fixed(Gauge g)
	{
		g.setMinimumSize(new Dimension(10, g.getPreferredSize().height));
		return g;
	}

	/** Key on the left; on the right an optional icon then the value component. */
	private static JPanel kv(String key, Component icon, Component value)
	{
		JPanel p = row(6);
		p.add(Ui.label(key, Ui.body(), Ui.FAINT), BorderLayout.CENTER);
		JPanel right = new JPanel();
		right.setLayout(new BoxLayout(right, BoxLayout.X_AXIS));
		right.setOpaque(false);
		if (icon != null)
		{
			right.add(icon);
			right.add(Box.createHorizontalStrut(4));
		}
		right.add(value);
		p.add(right, BorderLayout.EAST);
		return p;
	}

	/** "412 → 562": the after-value in green, the arrow faint; plain text when there is no arrow. */
	private static JComponent points(String text)
	{
		int i = text.indexOf('→');
		if (i < 0)
		{
			return Ui.label(text, Ui.body(), Ui.TEXT);
		}
		JLabel l = Ui.label("<html>" + Ui.esc(text.substring(0, i).trim())
			+ " <font color='" + Ui.hex(Ui.FAINT) + "'>→</font> <b><font color='" + Ui.hex(Ui.OK) + "'>"
			+ Ui.esc(text.substring(i + 1).trim()) + "</font></b></html>", Ui.body(), Ui.TEXT);
		return l;
	}
}

package com.slayercompanion.ui;

import com.slayercompanion.data.Equipment;
import com.slayercompanion.data.ItemNeed;
import com.slayercompanion.data.Monster;
import com.slayercompanion.data.SlayerTask;
import com.slayercompanion.gear.GearOptimizer;
import com.slayercompanion.gear.Loadout;
import com.slayercompanion.gear.OwnedItems;
import com.slayercompanion.gear.SetupLayout;
import com.slayercompanion.gear.Style;
import com.slayercompanion.gear.WeaponEffects;
import com.slayercompanion.task.CurrentTask;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;
import java.util.TreeMap;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.function.ToIntFunction;
import lombok.Value;

/** What the Prep tab shows, built from domain objects on the client thread. */
@Value
public class PrepModel
{
	static final String NO_TASK = "No slayer task";
	static final String OPEN_BANK = "Open your bank to load gear";
	static final String UNTRADEABLE = "Untradeable";
	static final String NO_REQUIREMENTS = "No requirements";
	private static final String[] SLOT_ORDER = {"weapon", "shield", "head", "body", "legs", "neck", "cape", "ammo",
		"hands", "feet", "ring"};
	private static final String[] MELEE_TYPES = {"stab", "slash", "crush"};

	public enum ChipKind
	{
		NORMAL, GOOD, BLUE, BAD
	}

	@Value
	public static class Chip
	{
		String bold;
		String rest;
		ChipKind kind;
		/** Skill icon drawn before the text ("hitpoints"), or null. */
		String icon;
	}

	/** One "Weak to" tile: "Water spells" / "+50% damage", with the skill icon for that combat style. */
	@Value
	public static class Weakness
	{
		String name;
		String detail;
		/** Skill icon: "magic" for spells, "attack" for melee styles, "ranged" for ranged. */
		String icon;
		/** The strongest weakness (shown first, in blue). */
		boolean best;
	}

	@Value
	public static class BringLine
	{
		String name;
		String status;
		boolean have;
		/** Item to picture: the first variant the player owns, else the first listed; 0 when none. */
		int itemId;
	}

	@Value
	public static class Slot
	{
		String label;
		String item;
		/** Equipped right now, so the player can see what's left to put on. */
		boolean worn;
		/** Item to picture; 0 for the spell row. */
		int itemId;
	}

	/** One requirement of the upgrade item: "65 Defence" or a quest name, met or not. */
	@Value
	public static class Need
	{
		String text;
		boolean met;
	}

	/**
	 * Client-side facts about the upgrade item, gathered on the client thread so the model stays testable.
	 * A price of 0 or less means untradeable.
	 */
	@Value
	public static class UpgradeFacts
	{
		long price;
		ToIntFunction<String> skillLevel;
		Predicate<String> questDone;
		Function<String, String> questName;
	}

	boolean noTask;
	String message;
	String title;
	String subtitle;
	List<Weakness> weakTo;
	List<Chip> facts;
	boolean noSpecialItem;
	List<BringLine> bring;
	Style style;
	List<Slot> slots;
	/** Shown in place of the slots when there is nothing to list (e.g. nothing owned for this style). */
	String gearMessage;
	/** The gear message is a warning: nothing owned for this style can hurt the monster (e.g. Kurask). */
	boolean gearWarning;
	String upgradeItem;
	int upgradeItemId;
	int upgradePercent;
	/** "≈ 14.6m GE" or "Untradeable"; null when there is no upgrade or no facts were supplied. */
	String upgradeCost;
	/** How to get an untradeable upgrade ("TzHaar Fight Cave reward"); null when tradeable or unknown. */
	String upgradeSource;
	/** Requirements of the upgrade item; empty means none ({@link #NO_REQUIREMENTS}). */
	List<Need> upgradeNeeds;
	/** "Show setup in bank" is on (bank tab, or the highlight overlay when Bank Tags is unavailable). */
	boolean highlighting;
	Set<Integer> highlightIds;
	/** {@link SetupLayout} of the recommended gear and bring items, for the bank tab. */
	int[] setupLayout;
	String footer;
	/** "Assumes Piety and a super combat" under the gear list; null when no gear is listed. */
	String boostNote;

	public static PrepModel noTask()
	{
		return new PrepModel(true, NO_TASK, null, null, Collections.emptyList(), Collections.emptyList(), true,
			Collections.emptyList(), Style.MELEE, Collections.emptyList(), null, false, null, 0, 0, null, null, Collections.emptyList(), false, Collections.emptySet(), new int[0], null, null);
	}

	public String getSetupButtonText()
	{
		return highlighting ? "Hide setup" : "Show setup in bank";
	}

	/** Gear slots (not the spell row) that are equipped right now. */
	public int getWornCount()
	{
		return (int) slots.stream().filter(s -> s.getItemId() > 0 && s.isWorn()).count();
	}

	/** "3 of 6 worn", or null when there is no gear listed. */
	public String getWornText()
	{
		long items = slots.stream().filter(s -> s.getItemId() > 0).count();
		return items == 0 ? null : getWornCount() + " of " + items + " worn";
	}

	/** "+4% dps", or null when there is no upgrade. */
	public String getUpgradeGain()
	{
		return upgradeItem == null ? null : "+" + upgradePercent + "% dps";
	}

	/** "Biggest upgrade: {item} (+{n}% dps)", or null when there is no upgrade. */
	public String getUpgradeText()
	{
		return upgradeItem == null ? null : "Biggest upgrade: " + upgradeItem + " (+" + upgradePercent + "% dps)";
	}

	/** Gear advice needs the bank: until it has been seen, inventory and worn items alone would mislead. */
	public static <T> Optional<T> gateOnBank(OwnedItems owned, Optional<T> value)
	{
		return owned.bankSeen() ? value : Optional.empty();
	}

	/**
	 * @param monster     the monster at the selected location; null when the task has no bundled data
	 * @param hasSafespot whether the selected location has a known safespot (affects suggested supplies)
	 * @param best        {@link GearOptimizer#best} for the style; ignored until the bank has been seen
	 */
	public static PrepModel build(CurrentTask current, Monster monster, boolean hasSafespot, OwnedItems owned,
		Style style, Optional<Loadout> bestGear, Optional<GearOptimizer.Upgrade> bestUpgrade, boolean highlighting,
		Instant now)
	{
		return build(current, monster, hasSafespot, owned, style, bestGear, bestUpgrade, null, highlighting, now);
	}

	/** @param facts price and requirement state for the upgrade item; null leaves Cost and Needs out */
	public static PrepModel build(CurrentTask current, Monster monster, boolean hasSafespot, OwnedItems owned,
		Style style, Optional<Loadout> bestGear, Optional<GearOptimizer.Upgrade> bestUpgrade, UpgradeFacts facts,
		boolean highlighting, Instant now)
	{
		return build(current, monster, hasSafespot, owned, style, bestGear, bestUpgrade, facts, highlighting, now, null);
	}

	/** @param boostNote prayer and potion the dps maths assumes ({@code Boosts.note}); shown with the gear list */
	public static PrepModel build(CurrentTask current, Monster monster, boolean hasSafespot, OwnedItems owned,
		Style style, Optional<Loadout> bestGear, Optional<GearOptimizer.Upgrade> bestUpgrade, UpgradeFacts facts,
		boolean highlighting, Instant now, String boostNote)
	{
		Optional<Loadout> best = gateOnBank(owned, bestGear);
		Optional<GearOptimizer.Upgrade> upgrade = gateOnBank(owned, bestUpgrade);
		SlayerTask task = current.getTask();
		StringBuilder sub = new StringBuilder().append(current.getRemaining()).append(" left");
		current.getMaster().ifPresent(m -> sub.append(" · ").append(Format.capitalize(m)));
		if (monster != null && monster.getSlayerXp() > 0)
		{
			sub.append(" · ").append(monster.getSlayerXp()).append(" xp each");
		}

		Set<Integer> highlight = new LinkedHashSet<>();
		List<BringLine> bring = new ArrayList<>();
		List<Integer> bringIds = new ArrayList<>();
		addBring(task.getRequiredItems(), owned, bring, highlight, bringIds);
		addBring(task.getRecommendedSupplies().isEmpty() ? Supplies.derive(monster, hasSafespot)
			: task.getRecommendedSupplies(), owned, bring, highlight, bringIds);
		Map<String, Integer> slotIds = new HashMap<>();

		List<Slot> slots = new ArrayList<>();
		String gearMessage = owned.bankSeen() ? null : OPEN_BANK;
		boolean gearWarning = false;
		if (best.isPresent() && monster != null && WeaponEffects.isImmune(best.get(), monster))
		{
			// Listing armour around a weapon that can't hurt the monster would only mislead.
			gearMessage = WeaponEffects.immunityHint(monster);
			gearWarning = true;
		}
		else if (best.isPresent())
		{
			Loadout l = best.get();
			Map<String, Equipment> bySlot = l.getBySlot();
			for (String slot : SLOT_ORDER)
			{
				Equipment e = bySlot.get(slot);
				if (e != null)
				{
					slots.add(new Slot(Format.capitalize(slot), e.getName(), owned.isWorn(e.getItemId()), e.getItemId()));
					highlight.add(e.getItemId());
					slotIds.put(slot, e.getItemId());
				}
				if ("weapon".equals(slot) && l.getStyle() == Style.MAGIC && l.getSpell() != null)
				{
					slots.add(new Slot("Spell", l.getSpell(), false, 0));
				}
			}
			if (slots.isEmpty())
			{
				gearMessage = "No owned gear for this style";
			}
		}

		String footer = owned.bankSeenAt()
			.map(t -> "Bank last read " + Math.max(0, Duration.between(t, now).toMinutes()) + " min ago")
			.orElse(OPEN_BANK);

		return new PrepModel(false, null, task.getName(), sub.toString(), weakTo(monster), facts(monster),
			task.getRequiredItems().isEmpty(), bring, style, slots, gearMessage, gearWarning,
			upgrade.map(u -> u.getItem().getName()).orElse(null),
			upgrade.map(u -> u.getItem().getItemId()).orElse(0),
			upgrade.map(u -> (int) Math.round(u.getDpsGainPercent())).orElse(0),
			upgrade.isPresent() && facts != null ? cost(facts.getPrice()) : null,
			upgrade.isPresent() && facts != null && facts.getPrice() <= 0 ? upgrade.get().getItem().getSource() : null,
			upgrade.isPresent() && facts != null ? needs(upgrade.get().getItem(), facts) : Collections.emptyList(),
			highlighting, Collections.unmodifiableSet(highlight), SetupLayout.build(slotIds, bringIds), footer,
			slots.isEmpty() ? null : boostNote);
	}

	static String cost(long price)
	{
		return price > 0 ? Format.compact(price) : UNTRADEABLE;
	}

	private static List<Need> needs(Equipment item, UpgradeFacts facts)
	{
		List<Need> out = new ArrayList<>();
		// Sorted by skill so the row reads the same every time.
		for (Map.Entry<String, Integer> r : new TreeMap<>(item.getSkillReqs()).entrySet())
		{
			out.add(new Need(r.getValue() + " " + Format.capitalize(r.getKey().toLowerCase(java.util.Locale.ROOT)),
				facts.getSkillLevel().applyAsInt(r.getKey()) >= r.getValue()));
		}
		for (String q : item.getQuestReqs())
		{
			out.add(new Need(facts.getQuestName().apply(q), facts.getQuestDone().test(q)));
		}
		return out;
	}

	private static void addBring(List<ItemNeed> needs, OwnedItems owned, List<BringLine> out, Set<Integer> highlight,
		List<Integer> setupIds)
	{
		for (ItemNeed need : needs)
		{
			int count = 0;
			Integer setupId = need.getItemIds().isEmpty() ? null : need.getItemIds().get(0);
			boolean ownedFound = false;
			for (int id : need.getItemIds())
			{
				int c = owned.count(id);
				if (c > 0)
				{
					highlight.add(id);
					if (!ownedFound)
					{
						// The first variant the player has, so the bank tab finds it.
						setupId = id;
						ownedFound = true;
					}
				}
				count += c;
			}
			if (setupId != null)
			{
				setupIds.add(setupId);
			}
			out.add(new BringLine(need.getName(), count > 0 ? count + " in bank" : "Missing", count > 0,
				setupId == null ? 0 : setupId));
		}
	}

	private static List<Weakness> weakTo(Monster m)
	{
		List<Weakness> out = new ArrayList<>();
		if (m == null)
		{
			return out;
		}
		if (m.getElementalWeakness() != null && m.getElementalWeaknessPercent() > 0)
		{
			out.add(new Weakness(Format.capitalize(m.getElementalWeakness()) + " spells",
				"+" + m.getElementalWeaknessPercent() + "% damage", "magic", true));
		}
		String lowest = null;
		int lowestDef = Integer.MAX_VALUE;
		for (String type : MELEE_TYPES)
		{
			Integer d = m.getDefensiveBonuses().get(type);
			if (d != null && d < lowestDef)
			{
				lowestDef = d;
				lowest = type;
			}
		}
		if (lowest != null)
		{
			out.add(new Weakness(Format.capitalize(lowest), "lowest defence", styleIcon(lowest), out.isEmpty()));
		}
		return out;
	}

	/** Skill icon for an attack type: spells are magic, ranged types ranged, melee types attack. */
	static String styleIcon(String type)
	{
		String t = type.toLowerCase(java.util.Locale.ROOT);
		if (t.contains("magic") || t.contains("spell"))
		{
			return "magic";
		}
		if (t.contains("ranged") || t.contains("arrow") || t.contains("bolt") || t.contains("dart"))
		{
			return "ranged";
		}
		return "attack";
	}

	private static List<Chip> facts(Monster m)
	{
		List<Chip> out = new ArrayList<>();
		if (m == null)
		{
			return out;
		}
		if (m.getMaxHit() > 0)
		{
			out.add(new Chip("", "Max hit " + m.getMaxHit(), ChipKind.NORMAL, "hitpoints"));
		}
		if (!m.getAttackStyles().isEmpty())
		{
			List<String> styles = new ArrayList<>();
			for (String st : m.getAttackStyles())
			{
				styles.add(Format.capitalize(st));
			}
			out.add(new Chip("", String.join(", ", styles), ChipKind.NORMAL, null));
		}
		boolean poison = m.isVenomous() || m.isPoisonous();
		out.add(new Chip("", m.isVenomous() ? "Venomous" : m.isPoisonous() ? "Poisonous" : "Not poisonous",
			poison ? ChipKind.BAD : ChipKind.GOOD, null));
		return out;
	}
}

package com.slayercompanion.ui;

import com.slayercompanion.gear.Style;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.GridLayout;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;

/** Prep tab: task header, weaknesses, what to bring and the best gear the player owns. */
class PrepTab extends Ui.Column
{
	private static final Font ROW_FONT = Ui.sans(Font.PLAIN, 12f);
	private static final Font CHIP_FONT = Ui.sans(Font.PLAIN, 10f);
	private static final Font WEAK_FONT = Ui.sans(Font.PLAIN, 11f);
	private static final Font SLOT_FONT = Ui.sans(Font.PLAIN, 11f);
	private static final Font STATUS_FONT = Ui.sans(Font.PLAIN, 12f);
	/** Slot card: half the inner width, less border (2), padding (10), icon square (30) and gap (6). */
	private static final int SLOT_TEXT_WIDTH = (Ui.INNER_WIDTH - 4) / 2 - 2 - 10 - 30 - 6 - 3;
	/** Weak-to tile: half the inner width, less border (2), padding (8), icon (14) and gap (4). */
	private static final int WEAK_TEXT_WIDTH = (Ui.INNER_WIDTH - 5) / 2 - 2 - 8 - 14 - 4 - 3;

	private final IconSource icons;
	private final Consumer<Style> onStyle;
	private final Runnable onToggleHighlight;

	PrepTab(IconSource icons, Consumer<Style> onStyle, Runnable onToggleHighlight)
	{
		super(0);
		this.icons = icons;
		this.onStyle = onStyle;
		this.onToggleHighlight = onToggleHighlight;
	}

	void show(PrepModel m)
	{
		removeAll();
		rebuild(m);
		revalidate();
		repaint();
	}

	private void rebuild(PrepModel m)
	{
		if (m.isNoTask())
		{
			addRow(Ui.message(m.getMessage()));
			return;
		}

		addRow(hero(m));

		if (!m.getWeakTo().isEmpty() || !m.getFacts().isEmpty())
		{
			Ui.Column weak = Ui.section("Weak to");
			if (!m.getWeakTo().isEmpty())
			{
				weak.addRow(weakTiles(m.getWeakTo()));
			}
			if (!m.getFacts().isEmpty())
			{
				weak.addRow(chips(m.getFacts()));
			}
			addRow(weak);
		}

		Ui.Column bring = Ui.section("Bring");
		if (m.isNoSpecialItem())
		{
			bring.addRow(Ui.label("No slayer item required", Ui.small(), Ui.OK));
		}
		for (PrepModel.BringLine line : m.getBring())
		{
			bring.addRow(bringRow(line));
		}
		addRow(bring);

		Ui.Column gear = Ui.section("Best owned gear");
		gear.addRow(styleSwitch(m.getStyle()));
		if (!m.getSlots().isEmpty())
		{
			JPanel grid = new JPanel(new GridLayout(0, 2, 4, 4));
			grid.setOpaque(false);
			for (PrepModel.Slot s : m.getSlots())
			{
				grid.add(slot(s));
			}
			gear.addRow(grid);
		}
		if (m.getWornText() != null)
		{
			gear.addRow(wornNote(m.getWornText()));
		}
		if (m.getBoostNote() != null)
		{
			gear.addRow(Ui.wrapped(m.getBoostNote(), Ui.small(), Ui.FAINT, Ui.INNER_WIDTH));
		}
		if (m.getGearMessage() != null)
		{
			gear.addRow(m.isGearWarning() ? new WarnBox(m.getGearMessage(), Ui.INNER_WIDTH)
				: Ui.wrapped(m.getGearMessage(), Ui.body(), Ui.MUTED, Ui.INNER_WIDTH));
		}
		if (m.getUpgradeItem() != null)
		{
			gear.addRow(upgradeCard(m));
		}
		if (!m.getSlots().isEmpty())
		{
			JPanel button = new JPanel(new BorderLayout());
			button.setOpaque(false);
			button.setBorder(BorderFactory.createEmptyBorder(3, 0, 0, 0));
			button.add(Ui.ghost(m.getSetupButtonText(), onToggleHighlight).setPrimary(!m.isHighlighting()));
			gear.addRow(button);
		}
		addRow(gear);

		addRow(Ui.note(m.getFooter()));
	}

	/** Slayer icon beside the orange pixel title and the sans subtitle. */
	private static JPanel hero(PrepModel m)
	{
		Ui.Column hero = Ui.hero();
		JPanel top = new JPanel(new BorderLayout(8, 0));
		top.setOpaque(false);
		JPanel icon = new JPanel(new GridBagLayout());
		icon.setOpaque(false);
		icon.add(ItemIcon.skill("slayer", new Dimension(22, 22)));
		top.add(icon, BorderLayout.WEST);
		int textWidth = Ui.INNER_WIDTH - 2 - 22 - 8 - 4;
		Ui.Column text = new Ui.Column(1);
		text.addRow(Ui.title(m.getTitle(), Ui.ORANGE, textWidth));
		text.addRow(Ui.wrapped(m.getSubtitle(), Ui.sans(Font.PLAIN, 11f), Ui.MUTED, textWidth));
		top.add(text, BorderLayout.CENTER);
		hero.addRow(top);
		return hero;
	}

	/** Weaknesses as tiles, two per row: style icon, name (blue for the best) and a faint detail line. */
	private static JPanel weakTiles(List<PrepModel.Weakness> weak)
	{
		JPanel grid = new JPanel(new GridLayout(0, 2, 5, 5));
		grid.setOpaque(false);
		for (PrepModel.Weakness w : weak)
		{
			JPanel tile = new JPanel(new BorderLayout(4, 0));
			tile.setBackground(Ui.CARD);
			tile.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(Ui.EDGE_DARK),
				BorderFactory.createEmptyBorder(5, 4, 5, 4)));
			tile.add(centred(ItemIcon.skill(w.getIcon(), new Dimension(14, 14))), BorderLayout.WEST);
			Ui.Column text = new Ui.Column(0);
			text.addRow(Ui.wrapped(w.getName(), WEAK_FONT, w.isBest() ? Ui.BLUE : Ui.TEXT, WEAK_TEXT_WIDTH));
			text.addRow(Ui.wrapped(w.getDetail(), Ui.small(), Ui.FAINT, WEAK_TEXT_WIDTH));
			tile.add(text, BorderLayout.CENTER);
			grid.add(tile);
		}
		return grid;
	}

	/** Boxed fact chips (max hit with the hitpoints icon, attack style, poison in green or red). */
	private static JPanel chips(List<PrepModel.Chip> chips)
	{
		JPanel flow = Ui.flow();
		for (PrepModel.Chip c : chips)
		{
			Color fg = c.getKind() == PrepModel.ChipKind.BLUE ? Ui.BLUE
				: c.getKind() == PrepModel.ChipKind.GOOD ? Ui.OK
				: c.getKind() == PrepModel.ChipKind.BAD ? Ui.BAD : Ui.MUTED;
			JPanel chip = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
			chip.setBackground(Ui.CARD);
			chip.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(Ui.EDGE_DARK),
				BorderFactory.createEmptyBorder(2, 4, 2, 4)));
			if (c.getIcon() != null)
			{
				chip.add(ItemIcon.skill(c.getIcon(), new Dimension(13, 13)));
				chip.add(javax.swing.Box.createHorizontalStrut(4));
			}
			chip.add(Ui.label(c.getBold() + c.getRest(), CHIP_FONT, fg));
			flow.add(chip);
		}
		return flow;
	}

	/** Item icon (dimmed when missing), name, and bank count or "Missing" on the right. */
	private JPanel bringRow(PrepModel.BringLine line)
	{
		JPanel row = new JPanel(new BorderLayout(7, 0));
		row.setOpaque(false);
		row.setBorder(BorderFactory.createEmptyBorder(2, 0, 2, 0));
		row.add(centred(ItemIcon.item(icons, line.getItemId(), ItemIcon.ROW).setDimmed(!line.isHave())),
			BorderLayout.WEST);
		JLabel status = Ui.label(line.getStatus(), STATUS_FONT, line.isHave() ? Ui.OK : Ui.BAD);
		int nameWidth = Ui.INNER_WIDTH - ItemIcon.ROW.width - 14 - status.getPreferredSize().width - 4;
		row.add(Ui.wrapped(Format.capitalize(line.getName()), ROW_FONT, Ui.TEXT, nameWidth), BorderLayout.CENTER);
		row.add(status, BorderLayout.EAST);
		return row;
	}

	/** Melee / Ranged / Magic segmented control, each with its skill icon. */
	private JPanel styleSwitch(Style selected)
	{
		JPanel seg = new JPanel(new GridLayout(1, 3, 2, 0));
		seg.setBackground(Ui.TAB_BG);
		seg.setOpaque(true);
		seg.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(Ui.EDGE_DARK),
			BorderFactory.createEmptyBorder(2, 2, 2, 2)));
		for (Style s : Style.values())
		{
			seg.add(segCell(s, s == selected));
		}
		JPanel wrap = new JPanel(new BorderLayout());
		wrap.setOpaque(false);
		wrap.setBorder(BorderFactory.createEmptyBorder(0, 0, 2, 0));
		wrap.add(seg);
		return wrap;
	}

	private JPanel segCell(Style s, boolean on)
	{
		String skill = s == Style.MELEE ? "attack" : s == Style.RANGED ? "ranged" : "magic";
		JPanel cell = new JPanel(new GridBagLayout());
		cell.setOpaque(true);
		Color base = on ? Ui.BUTTON_TOP : Ui.TAB_BG;
		Color hover = on ? Ui.BUTTON_TOP : Ui.HEADER_BG;
		cell.setBackground(base);
		cell.setBorder(on
			? BorderFactory.createCompoundBorder(BorderFactory.createMatteBorder(1, 0, 0, 0, Ui.BUTTON_SHINE),
				BorderFactory.createEmptyBorder(4, 2, 5, 2))
			: BorderFactory.createEmptyBorder(5, 2, 5, 2));
		GridBagConstraints g = new GridBagConstraints();
		g.insets = new Insets(0, 0, 0, 4);
		cell.add(ItemIcon.skill(skill, new Dimension(15, 15)), g);
		g.insets = new Insets(0, 0, 0, 0);
		cell.add(Ui.label(Format.capitalize(s.name().toLowerCase()), Ui.sans(Font.PLAIN, 11f),
			on ? Ui.YELLOW : Ui.FAINT), g);
		cell.setCursor(java.awt.Cursor.getPredefinedCursor(java.awt.Cursor.HAND_CURSOR));
		cell.addMouseListener(new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				onStyle.accept(s);
			}

			@Override
			public void mouseEntered(MouseEvent e)
			{
				cell.setBackground(hover);
			}

			@Override
			public void mouseExited(MouseEvent e)
			{
				cell.setBackground(base);
			}
		});
		return cell;
	}

	/** Slot card: icon in a stone square (green when worn), faint slot name over the item name. */
	private JPanel slot(PrepModel.Slot s)
	{
		JPanel p = new JPanel(new BorderLayout(6, 0));
		p.setBackground(Ui.CARD);
		p.setBorder(BorderFactory.createCompoundBorder(BorderFactory.createLineBorder(Ui.EDGE_DARK),
			BorderFactory.createEmptyBorder(4, 5, 4, 5)));
		ItemIcon icon = s.getItemId() > 0 ? ItemIcon.item(icons, s.getItemId(), ItemIcon.SLOT)
			: ItemIcon.skill("magic", new Dimension(16, 16));
		p.add(centred(new IconSlot(icon).setWorn(s.isWorn())), BorderLayout.WEST);
		Ui.Column text = new Ui.Column(0);
		text.addRow(Ui.label(s.getLabel(), Ui.small(), Ui.FAINT));
		text.addRow(Ui.wrapped(s.getItem(), SLOT_FONT, s.isWorn() ? Ui.OK : Ui.TEXT, SLOT_TEXT_WIDTH));
		JPanel middle = new JPanel(new GridBagLayout());
		middle.setOpaque(false);
		GridBagConstraints g = new GridBagConstraints();
		g.weightx = 1;
		g.fill = GridBagConstraints.HORIZONTAL;
		middle.add(text, g);
		p.add(middle, BorderLayout.CENTER);
		return p;
	}

	/** "● 3 of 6 worn". */
	private static JPanel wornNote(String text)
	{
		JPanel row = new JPanel(new FlowLayout(FlowLayout.LEFT, 0, 0));
		row.setOpaque(false);
		row.setBorder(BorderFactory.createEmptyBorder(1, 0, 0, 0));
		row.add(new Dot(Ui.OK));
		row.add(javax.swing.Box.createHorizontalStrut(5));
		row.add(Ui.label(text, Ui.sans(Font.PLAIN, 11f), Ui.FAINT));
		return row;
	}

	/** Raised card: large item icon, "Biggest upgrade", the item in yellow, dps gain on the right, cost and needs. */
	private JPanel upgradeCard(PrepModel m)
	{
		Card card = new Card(3, 7);
		card.setRaised();
		JPanel top = new JPanel(new BorderLayout(7, 0));
		top.setOpaque(false);
		top.add(centred(ItemIcon.item(icons, m.getUpgradeItemId(), ItemIcon.LARGE)), BorderLayout.WEST);
		JLabel gain = Ui.label(m.getUpgradeGain(), Ui.sans(Font.BOLD, 11f), Ui.OK);
		int textWidth = Ui.INNER_WIDTH - 16 - ItemIcon.LARGE.width - 14 - gain.getPreferredSize().width - 4;
		Ui.Column text = new Ui.Column(0);
		text.addRow(Ui.label("Biggest upgrade", Ui.small(), Ui.FAINT));
		text.addRow(Ui.wrapped(m.getUpgradeItem(), Ui.bold(), Ui.YELLOW, textWidth));
		top.add(text, BorderLayout.CENTER);
		top.add(gain, BorderLayout.EAST);
		card.addRow(top);
		if (m.getUpgradeCost() != null)
		{
			JPanel cost = new JPanel(new BorderLayout(6, 0));
			cost.setOpaque(false);
			cost.setBorder(BorderFactory.createEmptyBorder(3, 0, 0, 0));
			cost.add(Ui.label("Cost", ROW_FONT, Ui.FAINT), BorderLayout.WEST);
			boolean tradeable = !PrepModel.UNTRADEABLE.equals(m.getUpgradeCost());
			JPanel value = new JPanel(new FlowLayout(FlowLayout.RIGHT, 0, 0));
			value.setOpaque(false);
			if (tradeable)
			{
				value.add(ItemIcon.item(icons, 995, ItemIcon.INLINE));
				value.add(javax.swing.Box.createHorizontalStrut(4));
			}
			value.add(Ui.label(m.getUpgradeCost(), ROW_FONT, tradeable ? Ui.TEXT : Ui.MUTED));
			cost.add(value, BorderLayout.EAST);
			card.addRow(cost);
			if (m.getUpgradeSource() != null)
			{
				card.addRow(sourceRow(m.getUpgradeSource(), Ui.INNER_WIDTH - 16));
			}
			card.addRow(needsRow(m.getUpgradeNeeds(), Ui.INNER_WIDTH - 16));
		}
		return card;
	}

	/** "Get" key with how to get an untradeable upgrade, right-aligned and wrapped to the width. */
	private static JPanel sourceRow(String source, int rowWidth)
	{
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		JLabel key = Ui.label("Get", ROW_FONT, Ui.FAINT);
		key.setVerticalAlignment(JLabel.TOP);
		row.add(key, BorderLayout.WEST);
		String html = Ui.wrapHtml(source, ROW_FONT, rowWidth - key.getPreferredSize().width - 12, false)
			.replaceFirst("^<html>", "<html><div align='right'>").replaceFirst("</html>$", "</div></html>");
		row.add(Ui.label(html, ROW_FONT, Ui.TEXT), BorderLayout.EAST);
		return row;
	}

	/** "Needs" key with comma-separated requirements, each green with a tick when met, wrapped to the width. */
	private static JPanel needsRow(List<PrepModel.Need> needs, int rowWidth)
	{
		if (needs.isEmpty())
		{
			JPanel p = new JPanel(new BorderLayout(6, 0));
			p.setOpaque(false);
			p.add(Ui.label("Needs", ROW_FONT, Ui.FAINT), BorderLayout.WEST);
			p.add(Ui.label(PrepModel.NO_REQUIREMENTS, ROW_FONT, Ui.MUTED), BorderLayout.EAST);
			return p;
		}
		JPanel row = new JPanel(new BorderLayout(6, 0));
		row.setOpaque(false);
		JLabel key = Ui.label("Needs", ROW_FONT, Ui.FAINT);
		key.setVerticalAlignment(JLabel.TOP);
		row.add(key, BorderLayout.WEST);
		int width = rowWidth - key.getPreferredSize().width - 12;
		FontMetrics fm = key.getFontMetrics(ROW_FONT);
		StringBuilder html = new StringBuilder("<html><div align='right'>");
		int lineWidth = 0;
		for (int i = 0; i < needs.size(); i++)
		{
			PrepModel.Need n = needs.get(i);
			String text = n.getText() + (n.isMet() ? " ✓" : "") + (i < needs.size() - 1 ? "," : "");
			int w = fm.stringWidth(text) + (n.isMet() ? 4 : 0);
			if (lineWidth > 0)
			{
				if (lineWidth + fm.stringWidth(" ") + w > width)
				{
					html.append("<br>");
					lineWidth = 0;
				}
				else
				{
					html.append(' ');
					lineWidth += fm.stringWidth(" ");
				}
			}
			// Non-breaking spaces keep one requirement on one line.
			html.append("<font color='").append(Ui.hex(n.isMet() ? Ui.OK : Ui.BAD)).append("'>")
				.append(glyphs(Ui.esc(text).replace(" ", "&nbsp;"))).append("</font>");
			lineWidth += w;
		}
		row.add(Ui.label(html.append("</div></html>").toString(), ROW_FONT, Ui.TEXT), BorderLayout.EAST);
		return row;
	}

	/** Draw characters the sans font lacks (✓) in a fallback font so they don't show as boxes. */
	private static String glyphs(String html)
	{
		StringBuilder out = new StringBuilder();
		for (char c : html.toCharArray())
		{
			if (c > 127 && !ROW_FONT.canDisplay(c))
			{
				out.append("<font face='Dialog'>").append(c).append("</font>");
			}
			else
			{
				out.append(c);
			}
		}
		return out.toString();
	}

	/** Wraps a fixed-size component so it sits vertically centred in a BorderLayout side. */
	private static JPanel centred(JComponent c)
	{
		JPanel p = new JPanel(new GridBagLayout());
		p.setOpaque(false);
		p.add(c);
		return p;
	}

	/** Small filled circle (.dot). */
	private static final class Dot extends JComponent
	{
		private final Color color;

		Dot(Color color)
		{
			this.color = color;
		}

		@Override
		public Dimension getPreferredSize()
		{
			return new Dimension(7, 7);
		}

		@Override
		protected void paintComponent(Graphics g)
		{
			Graphics2D g2 = (Graphics2D) g.create();
			g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
			g2.setColor(color);
			g2.fillOval(0, 0, 7, 7);
			g2.dispose();
		}
	}
}

package com.slayercompanion.ui;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Arc2D;
import javax.swing.JComponent;

/** Task ring (.ring): dark track, green arc clockwise from the top, big number with a small label inside. 70x70. */
class ProgressRing extends JComponent
{
	private static final int SIZE = 70;
	private static final float STROKE = 7.5f;

	private final double fraction;
	private final String number;
	private final String label;

	ProgressRing(double fraction, String number, String label)
	{
		this.fraction = Double.isNaN(fraction) ? 0 : Math.max(0, Math.min(1, fraction));
		this.number = number;
		this.label = label;
		setOpaque(false);
	}

	@Override
	public Dimension getPreferredSize()
	{
		return new Dimension(SIZE, SIZE);
	}

	@Override
	public Dimension getMinimumSize()
	{
		return getPreferredSize();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		int d = Math.min(getWidth(), getHeight());
		double r = d / 2.0 - STROKE / 2 - 1;
		double cx = getWidth() / 2.0;
		double cy = getHeight() / 2.0;
		g2.setStroke(new BasicStroke(STROKE, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER));
		g2.setColor(Ui.EDGE_DARK);
		g2.draw(new Arc2D.Double(cx - r, cy - r, 2 * r, 2 * r, 0, 360, Arc2D.OPEN));
		if (fraction > 0)
		{
			g2.setColor(Ui.OK);
			g2.draw(new Arc2D.Double(cx - r, cy - r, 2 * r, 2 * r, 90, -360 * fraction, Arc2D.OPEN));
		}

		Font big = Ui.sans(Font.BOLD, 22f);
		Font small = Ui.small();
		FontMetrics fb = g2.getFontMetrics(big);
		FontMetrics fs = g2.getFontMetrics(small);
		boolean hasLabel = label != null && !label.isEmpty();
		int total = fb.getAscent() - 2 + (hasLabel ? fs.getAscent() : 0);
		int y = (int) Math.round(cy - total / 2.0) + fb.getAscent() - 2;
		int x = (int) Math.round(cx - fb.stringWidth(number) / 2.0);
		g2.setFont(big);
		g2.setColor(Color.BLACK);
		g2.drawString(number, x + 1, y + 1);
		g2.setColor(Ui.YELLOW);
		g2.drawString(number, x, y);
		if (hasLabel)
		{
			g2.setFont(small);
			g2.setColor(Ui.MUTED);
			g2.drawString(label, (int) Math.round(cx - fs.stringWidth(label) / 2.0), y + fs.getAscent());
		}
		g2.dispose();
	}
}

package com.slayercompanion.ui;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.Insets;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.SwingConstants;

/**
 * Plain-text label drawn with a 1px black drop shadow, like in-game interface text. Draws its own text (no HTML),
 * so the pixel fonts render crisply; wraps on spaces when given a width.
 */
class ShadowLabel extends JLabel
{
	private int wrapWidth;

	ShadowLabel(String text)
	{
		super(text);
	}

	/** Wrap onto several lines to fit this many pixels (0 = one line). */
	ShadowLabel wrap(int width)
	{
		wrapWidth = width;
		revalidate();
		return this;
	}

	private List<String> lines(FontMetrics fm)
	{
		List<String> out = new ArrayList<>();
		String text = getText() == null ? "" : getText();
		if (wrapWidth <= 0)
		{
			out.add(text);
			return out;
		}
		StringBuilder line = new StringBuilder();
		for (String word : text.split(" "))
		{
			String next = line.length() == 0 ? word : line + " " + word;
			if (line.length() > 0 && fm.stringWidth(next) > wrapWidth)
			{
				out.add(line.toString());
				line = new StringBuilder(word);
			}
			else
			{
				line = new StringBuilder(next);
			}
		}
		out.add(line.toString());
		return out;
	}

	@Override
	public Dimension getPreferredSize()
	{
		if (isPreferredSizeSet())
		{
			return super.getPreferredSize();
		}
		FontMetrics fm = getFontMetrics(getFont());
		List<String> lines = lines(fm);
		int w = 0;
		for (String l : lines)
		{
			w = Math.max(w, fm.stringWidth(l));
		}
		Insets in = getInsets();
		return new Dimension(w + 1 + in.left + in.right, lines.size() * fm.getHeight() + 1 + in.top + in.bottom);
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		if (isOpaque())
		{
			g.setColor(getBackground());
			g.fillRect(0, 0, getWidth(), getHeight());
		}
		Graphics2D g2 = (Graphics2D) g.create();
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, Ui.isPixel(getFont())
			? RenderingHints.VALUE_TEXT_ANTIALIAS_OFF : RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		g2.setFont(getFont());
		FontMetrics fm = g2.getFontMetrics();
		Insets in = getInsets();
		List<String> lines = lines(fm);
		int inner = getWidth() - in.left - in.right;
		int block = lines.size() * fm.getHeight();
		int y = in.top + Math.max(0, (getHeight() - in.top - in.bottom - block) / 2) + fm.getAscent();
		Color fg = getForeground();
		for (String l : lines)
		{
			int x = in.left;
			if (getHorizontalAlignment() == SwingConstants.CENTER)
			{
				x += (inner - fm.stringWidth(l)) / 2;
			}
			else if (getHorizontalAlignment() == SwingConstants.RIGHT || getHorizontalAlignment() == SwingConstants.TRAILING)
			{
				x += inner - fm.stringWidth(l) - 1;
			}
			g2.setColor(Color.BLACK);
			g2.drawString(l, x + 1, y + 1);
			g2.setColor(fg);
			g2.drawString(l, x, y);
			y += fm.getHeight();
		}
		g2.dispose();
	}
}

package com.slayercompanion.ui;

import java.awt.image.BufferedImage;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import javax.imageio.ImageIO;

/**
 * Small skill icons bundled with the plugin (resources/com/slayercompanion/skills/{name}.png), since a sideloaded
 * plugin can't read the client's own skill icon resources. Names: slayer, prayer, hitpoints, magic, attack, ranged,
 * defence.
 */
final class SkillIcons
{
	private static final Map<String, BufferedImage> CACHE = new HashMap<>();

	private SkillIcons()
	{
	}

	/** The icon for a skill name (any case), or null if it isn't bundled. */
	static synchronized BufferedImage get(String skill)
	{
		String key = skill.toLowerCase();
		if (CACHE.containsKey(key))
		{
			return CACHE.get(key);
		}
		BufferedImage img = null;
		try (InputStream in = SkillIcons.class.getResourceAsStream("/com/slayercompanion/skills/" + key + ".png"))
		{
			if (in != null)
			{
				img = ImageIO.read(in);
			}
		}
		catch (Exception e)
		{
			img = null;
		}
		CACHE.put(key, img);
		return img;
	}
}

package com.slayercompanion.ui;

import com.slayercompanion.gear.Style;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.Rectangle;
import java.util.Objects;
import javax.swing.BorderFactory;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.Scrollable;
import javax.swing.SwingConstants;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

/** The side panel: a Prep / Where to go / On task tab bar over scrollable tab content. Swing thread only. */
public class SlayerCompanionPanel extends PluginPanel
{
	static final String ISSUES_URL = "https://github.com/idayley/osrs-slayer-companion/issues/new/choose";

	public interface Actions
	{
		void selectStyle(Style style);

		void selectLocation(String locationId);

		void toggleBankHighlight();

		void takeMeThere();

		void sendSafespots();
	}

	public enum Tab
	{
		PREP("Prep"), WHERE("Where to go"), ON_TASK("On task");

		private final String title;

		Tab(String title)
		{
			this.title = title;
		}
	}

	private final PrepTab prep;
	private final WhereToGoTab where;
	private final OnTaskTab onTask;
	private final JComponent[] tabPages = new JComponent[Tab.values().length];
	private final JLabel[] tabLabels = new JLabel[Tab.values().length];
	private final ScrollContent content = new ScrollContent();
	private final JScrollPane scroll;
	private final JLabel report = reportLink();

	private PrepModel lastPrep;
	private WhereToGoModel lastWhere;
	private OnTaskModel lastOnTask;

	/** @param icons item pictures for the tabs (ItemManager-backed in the client). */
	public SlayerCompanionPanel(Actions actions, IconSource icons)
	{
		super(false);
		setLayout(new BorderLayout());
		setBorder(BorderFactory.createEmptyBorder());
		setBackground(Ui.BG);

		prep = new PrepTab(icons, actions::selectStyle, actions::toggleBankHighlight);
		where = new WhereToGoTab(icons, actions::selectLocation, actions::takeMeThere, actions::sendSafespots);
		onTask = new OnTaskTab(icons);

		add(tabBar(), BorderLayout.NORTH);

		tabPages[Tab.PREP.ordinal()] = prep;
		tabPages[Tab.WHERE.ordinal()] = where;
		tabPages[Tab.ON_TASK.ordinal()] = onTask;

		scroll = new JScrollPane(content, JScrollPane.VERTICAL_SCROLLBAR_AS_NEEDED,
			JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
		scroll.setBorder(BorderFactory.createEmptyBorder());
		scroll.getViewport().setBackground(Ui.BG);
		scroll.getVerticalScrollBar().setUnitIncrement(16);
		add(scroll, BorderLayout.CENTER);

		PrepModel p = PrepModel.noTask();
		WhereToGoModel w = WhereToGoModel.noTask();
		OnTaskModel o = OnTaskModel.noTask();
		update(p, w, o);
		select(Tab.PREP);
	}

	private JPanel tabBar()
	{
		JPanel bar = new JPanel(new GridLayout(1, Tab.values().length));
		bar.setBackground(Ui.TAB_BG);
		bar.setBorder(BorderFactory.createMatteBorder(0, 0, 2, 0, Ui.EDGE_DARK));
		for (Tab t : Tab.values())
		{
			ShadowLabel l = new ShadowLabel(t.title);
			l.setHorizontalAlignment(SwingConstants.CENTER);
			l.setFont(Ui.pixelFont());
			Ui.aa(l);
			l.setOpaque(true);
			l.setBackground(Ui.TAB_BG);
			Ui.onClick(l, () -> select(t));
			tabLabels[t.ordinal()] = l;
			bar.add(l);
		}
		return bar;
	}

	/** Faint "wrong info?" line under every tab that opens the GitHub issue forms. */
	private static JLabel reportLink()
	{
		JLabel l = Ui.note("");
		l.setText("<html><center>Something wrong, or a safespot to share?<br><u>Report it on GitHub</u></center></html>");
		Ui.onClick(l, () -> LinkBrowser.browse(ISSUES_URL));
		return l;
	}

	public void select(Tab tab)
	{
		// Only the shown tab is in the scroll content, so the scroll range fits it.
		content.removeAll();
		content.add(tabPages[tab.ordinal()], BorderLayout.NORTH);
		content.add(report, BorderLayout.SOUTH);
		for (Tab t : Tab.values())
		{
			boolean on = t == tab;
			JLabel l = tabLabels[t.ordinal()];
			l.setForeground(on ? Ui.YELLOW : Ui.FAINT);
			l.setBackground(on ? Ui.TAB_ACTIVE : Ui.TAB_BG);
			boolean last = t.ordinal() == Tab.values().length - 1;
			l.setBorder(BorderFactory.createCompoundBorder(
				BorderFactory.createMatteBorder(0, 0, 0, last ? 0 : 1, Ui.EDGE_DARK),
				BorderFactory.createEmptyBorder(7, 0, 6, 0)));
		}
		content.revalidate();
		content.repaint();
		scroll.getVerticalScrollBar().setValue(0);
	}

	/** Shows new models; tabs whose model did not change are left alone. */
	public void update(PrepModel p, WhereToGoModel w, OnTaskModel o)
	{
		if (!Objects.equals(p, lastPrep))
		{
			lastPrep = p;
			prep.show(p);
		}
		if (!Objects.equals(w, lastWhere))
		{
			lastWhere = w;
			where.show(w);
		}
		if (!Objects.equals(o, lastOnTask))
		{
			lastOnTask = o;
			onTask.show(o);
		}
	}

	public void showWhereMessage(String message)
	{
		where.showActionMessage(message);
	}

	/** The tab content without the scroll pane, for headless rendering. */
	JComponent tabComponent(Tab tab)
	{
		switch (tab)
		{
			case PREP:
				return prep;
			case WHERE:
				return where;
			default:
				return onTask;
		}
	}

	JComponent reportComponent()
	{
		return report;
	}

	JComponent tabBarComponent()
	{
		return (JComponent) getComponent(0);
	}

	/** Scroll content that always matches the viewport width, so only vertical scrolling happens. */
	private static class ScrollContent extends JPanel implements Scrollable
	{
		ScrollContent()
		{
			super(new BorderLayout());
			setBackground(Ui.BG);
		}

		@Override
		public Dimension getPreferredScrollableViewportSize()
		{
			return getPreferredSize();
		}

		@Override
		public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return 16;
		}

		@Override
		public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction)
		{
			return visibleRect.height;
		}

		@Override
		public boolean getScrollableTracksViewportWidth()
		{
			return true;
		}

		@Override
		public boolean getScrollableTracksViewportHeight()
		{
			return false;
		}
	}
}

