	{
		assertEquals(Style.MELEE, GearOptimizer.classify(item(22398, "Ivandis flail", "weapon", "Staff", 5, false)));
		assertEquals(Style.MELEE, GearOptimizer.classify(item(24699, "Blisterwood flail", "weapon", "Staff", 5, false)));
		assertEquals(Style.MELEE, GearOptimizer.classify(item(7639, "Rod of Ivandis (10)", "weapon", "Staff", 5, false)));
		assertEquals(Style.MAGIC, GearOptimizer.classify(item(1, "Staff of air", "weapon", "Staff", 4, false)));
	}

	@Test
	public void juvinatePicksIvandisFlailOverWhip()
	{
		Equipment flail = item(22398, "Ivandis flail", "weapon", "Staff", 5, false, "crush", 33, "str", 40);
		Monster juvinate = giant();
		juvinate.setId(3694);
		GearOptimizer g = new GearOptimizer(List.of(WHIP, flail));
		assertEquals("Ivandis flail",
			g.best(stats(99), Style.MELEE, juvinate, true, owned(WHIP, flail)).get().getBySlot().get("weapon").getName());
	}

	@Test
	public void smokeRealEquipmentUnder500ms()
	{
		com.slayercompanion.data.GameData data = com.slayercompanion.data.GameData.load(GSON, "/com/slayercompanion");
		Monster m = data.monster(2084).orElseGet(GearOptimizerTest::giant);
		GearOptimizer g = new GearOptimizer(data.allEquipment());
		List<Equipment> all = new ArrayList<>(data.allEquipment());
		OwnedItems o = new OwnedItems();
		Map<Integer, Integer> bank = new HashMap<>();
		for (int i = 0; i < all.size(); i += 3)
		{
			bank.put(all.get(i).getItemId(), 1);
		}
		o.updateBank(bank, Instant.now());
		CombatStats s = stats(80);
		s.setAssumeBoosts(true);
		long t0 = System.nanoTime();
		Loadout l = null;
		for (Style st : Style.values())
		{
			Optional<Loadout> r = g.best(s, st, m, true, o);
			assertTrue(r.isPresent());
			l = r.get();
		}
		Loadout cur = new Loadout();
		g.biggestUpgrade(s, new HashSet<>(), cur, m, true, o);
		long ms = (System.nanoTime() - t0) / 1_000_000;
		System.out.println("SMOKE_TIMING_MS=" + ms + " catalogue=" + all.size());
		assertTrue("took " + ms + " ms", ms < 500);
	}

	// ---- set bonuses ----

	private static Equipment piece(int id, String name, String slot, int bonus)
	{
		return eq(id, name, slot, 0, "slash", bonus, "str", bonus, null);
	}

	private static final Equipment VOID_HELM = piece(11665, "Void melee helm (Normal)", "head", 0);
	private static final Equipment VOID_TOP = piece(8839, "Void knight top (Normal)", "body", 0);
	private static final Equipment VOID_ROBE = piece(8840, "Void knight robe (Normal)", "legs", 0);
	private static final Equipment VOID_GLOVES = piece(8842, "Void knight gloves (Normal)", "hands", 0);
	private static final Equipment[] PLUS_ONE = {piece(101, "Plus helm", "head", 1), piece(102, "Plus body", "body", 1),
		piece(103, "Plus legs", "legs", 1), piece(104, "Plus gloves", "hands", 1)};

	/** Each +1 piece beats a lone void piece, so slot-by-slot swaps alone would never find the set. */
	@Test
	public void picksCompleteOwnedVoidSet()
	{
		List<Equipment> cat = new ArrayList<>(List.of(WHIP, VOID_HELM, VOID_TOP, VOID_ROBE, VOID_GLOVES));
		cat.addAll(List.of(PLUS_ONE));
		List<Equipment> own = new ArrayList<>(cat);
		GearOptimizer g = new GearOptimizer(cat);
		Loadout l = g.best(stats(99), Style.MELEE, giant(), false, owned(own.toArray(new Equipment[0]))).get();
		assertEquals("Void melee helm (Normal)", l.getBySlot().get("head").getName());
		assertEquals("Void knight gloves (Normal)", l.getBySlot().get("hands").getName());
		assertEquals("Abyssal whip", l.getBySlot().get("weapon").getName());
	}

	@Test
	public void ignoresVoidSetWhenPiecesAreBetter()
	{
		Equipment[] strong = {piece(201, "Strong helm", "head", 15), piece(202, "Strong body", "body", 15),
			piece(203, "Strong legs", "legs", 15), piece(204, "Strong gloves", "hands", 15)};
		List<Equipment> cat = new ArrayList<>(List.of(WHIP, VOID_HELM, VOID_TOP, VOID_ROBE, VOID_GLOVES));
		cat.addAll(List.of(strong));
		GearOptimizer g = new GearOptimizer(cat);
		Loadout l = g.best(stats(99), Style.MELEE, giant(), false, owned(cat.toArray(new Equipment[0]))).get();
		assertEquals("Strong helm", l.getBySlot().get("head").getName());
	}

	/** The missing helm is the upgrade, valued with the owned void pieces it completes. */
	@Test
	public void upgradeCompletesAnOwnedSet()
	{
		List<Equipment> cat = new ArrayList<>(List.of(WHIP, VOID_HELM, VOID_TOP, VOID_ROBE, VOID_GLOVES));
		cat.addAll(List.of(PLUS_ONE));
		OwnedItems o = owned(WHIP, VOID_TOP, VOID_ROBE, VOID_GLOVES, PLUS_ONE[0], PLUS_ONE[1], PLUS_ONE[2], PLUS_ONE[3]);
		GearOptimizer g = new GearOptimizer(cat);
		Loadout best = g.best(stats(99), Style.MELEE, giant(), false, o).get();
		assertEquals("Plus helm", best.getBySlot().get("head").getName());
		GearOptimizer.Upgrade u = g.biggestUpgrade(stats(99), new HashSet<>(), best, giant(), false, o).get();
		assertEquals("Void melee helm (Normal)", u.getItem().getName());
		assertTrue(u.getDpsGainPercent() > 0);
	}

	/** Prayers and potions apply to both sides of the comparison, so the gain is upgrade vs best under the same boosts. */
	@Test
	public void upgradePercentUsesTheSameBoostsOnBothSides()
	{
		CombatStats s = stats(99);
		s.setAssumeBoosts(true);
		s.setPietyUnlocked(true);
		GearOptimizer g = new GearOptimizer(List.of(SCIM, WHIP));
		Loadout cur = g.best(s, Style.MELEE, giant(), false, owned(SCIM)).get();
		GearOptimizer.Upgrade u = g.biggestUpgrade(s, new HashSet<>(), cur, giant(), false, owned(SCIM)).get();
		Loadout up = new Loadout();
		up.getBySlot().put("weapon", WHIP);
		up.setMeleeType("slash");
		double before = DpsCalculator.dps(s, cur, giant(), false);
		double after = DpsCalculator.dps(s, up, giant(), false);
		assertEquals((after - before) / before * 100.0, u.getDpsGainPercent(), 1e-6);
		// And it differs from the unboosted figure (boosted strength scales bonuses differently).
		Loadout curPlain = g.best(stats(99), Style.MELEE, giant(), false, owned(SCIM)).get();
		double plain = g.biggestUpgrade(stats(99), new HashSet<>(), curPlain, giant(), false, owned(SCIM)).get().getDpsGainPercent();
		assertTrue(Math.abs(plain - u.getDpsGainPercent()) > 0.01);
	}
}

package com.slayercompanion.gear;

import com.google.gson.Gson;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class OwnedItemsTest
{
	private static final Gson GSON = new Gson();

	@Test
	public void ownedItemsRoundTripJson()
	{
		OwnedItems o = new OwnedItems();
		Instant t = Instant.parse("2026-01-02T03:04:05Z");
		o.updateBank(Map.of(4151, 1, 995, 500), t);
		o.updateInventory(Map.of(4151, 1));
		o.updateWorn(Map.of(1234, 1));
		OwnedItems back = OwnedItems.fromJson(GSON, o.toJson(GSON));
		assertEquals(2, back.count(4151));
		assertEquals(500, back.count(995));
		assertEquals(1, back.count(1234));
		assertTrue(back.bankSeen());
		assertEquals(t, back.bankSeenAt().get());
	}

	@Test
	public void notedBankItemCountsAsOwned()
	{
		Map<Integer, Integer> canon = new HashMap<>();
		canon.put(4152, 4151);
		OwnedItems o = new OwnedItems(id -> canon.getOrDefault(id, id));
		o.updateBank(Map.of(4152, 3), Instant.now());
		assertEquals(3, o.count(4151));
	}

	@Test
	public void bankNotSeenByDefault()
	{
		assertFalse(new OwnedItems().bankSeen());
	}
}

package com.slayercompanion.gear;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.slayercompanion.data.Equipment;
import com.slayercompanion.data.Monster;
import org.junit.Test;

/**
 * Armour set bonuses, checked against the OSRS Wiki DPS calculator (PlayerVsNPCCalc.ts / BaseCalc.ts).
 * Maxed stats without boosts: melee effective strength 110 / attack 107, ranged 110, magic 108.
 */
public class SetBonusesTest
{
	private static final CombatStats MAXED = new CombatStats(99, 99, 99, 99, 99, 99, 99, 99);

	private static Equipment item(String name, String slot, Object... kv)
	{
		Equipment e = new Equipment();
		e.setName(name);
		e.setSlot(slot);
		e.setSpeedTicks(4);
		for (int i = 0; i < kv.length; i += 2)
		{
			e.getBonuses().put((String) kv[i], (Integer) kv[i + 1]);
		}
		return e;
	}

	private static Loadout loadout(Style style, String meleeType, Equipment... items)
	{
		Loadout l = new Loadout();
		l.setStyle(style);
		l.setMeleeType(meleeType);
		for (Equipment e : items)
		{
			l.getBySlot().put(e.getSlot(), e);
		}
		return l;
	}

	private static Monster monster()
	{
		Monster m = new Monster();
		m.setDefenceLevel(100);
		m.setMagicLevel(100);
		return m;
	}

	private static Equipment whip()
	{
		return item("Abyssal whip", "weapon", "slash", 82, "str", 82);
	}

	private static Equipment[] voidRobes(boolean elite)
	{
		String top = elite ? "Elite void top (Normal)" : "Void knight top (Normal)";
		String robe = elite ? "Elite void robe (Normal)" : "Void knight robe (or) (Normal)";
		return new Equipment[]{item(top, "body"), item(robe, "legs"), item("Void knight gloves (Normal)", "hands")};
	}

	private static Loadout withAll(Loadout l, Equipment... items)
	{
		for (Equipment e : items)
		{
			l.getBySlot().put(e.getSlot(), e);
		}
		return l;
	}

	// ---- void ----

	/** Melee void: effective levels x 11/10 after stance: 110 -> 121 (max 28), 107 -> 117 (roll 117 * 146). */
	@Test
	public void meleeVoid()
	{
		Loadout l = withAll(loadout(Style.MELEE, "slash", whip(), item("Void melee helm (Normal)", "head")), voidRobes(false));
		assertEquals(28, DpsCalculator.maxHit(MAXED, l, monster(), false));
		assertEquals(117L * 146, DpsCalculator.attackRoll(MAXED, l, monster(), false));
	}

	@Test
	public void voidNeedsEveryPiece()
	{
		Loadout l = loadout(Style.MELEE, "slash", whip(), item("Void melee helm (Normal)", "head"),
			voidRobes(false)[0], voidRobes(false)[1]);
		assertEquals(25, DpsCalculator.maxHit(MAXED, l, monster(), false));
		// Broken pieces cannot be worn, so they never complete a set.
		Loadout broken = withAll(loadout(Style.MELEE, "slash", whip(), item("Void melee helm (Broken)", "head")),
			voidRobes(false));
		assertEquals(25, DpsCalculator.maxHit(MAXED, broken, monster(), false));
	}

	/** Ranged void: accuracy 110 -> 121; damage x 11/10 (121), elite x 9/8 (123). */
	@Test
	public void rangedVoidAndElite()
	{
		Equipment rcb = item("Rune crossbow", "weapon", "ranged", 90);
		Equipment bolts = item("Runite bolts", "ammo", "ranged_str", 100);
		Equipment helm = item("Void ranger helm (Normal)", "head");
		Loadout normal = withAll(loadout(Style.RANGED, "slash", rcb, bolts, helm), voidRobes(false));
		assertEquals(121L * 154, DpsCalculator.attackRoll(MAXED, normal, monster(), false));
		assertEquals(31, DpsCalculator.maxHit(MAXED, normal, monster(), false)); // floor((121*164+320)/640)
		Loadout elite = withAll(loadout(Style.RANGED, "slash", rcb, bolts, helm), voidRobes(true));
		assertEquals(32, DpsCalculator.maxHit(MAXED, elite, monster(), false)); // floor((123*164+320)/640)
	}

	/** Magic void: accuracy x 29/20 (108 -> 156); elite adds 5% magic damage (50 tenths) to gear's. */
	@Test
	public void magicVoidAndElite()
	{
		Equipment staff = item("Staff of water", "weapon", "magic", 10, "magic_str", 100);
		Equipment helm = item("Void mage helm (or) (Normal)", "head");
		Loadout normal = withAll(loadout(Style.MAGIC, "slash", staff, helm), voidRobes(false));
		normal.setSpell("Water Wave");
		assertEquals(156L * 74, DpsCalculator.attackRoll(MAXED, normal, monster(), false));
		assertEquals(19, DpsCalculator.maxHit(MAXED, normal, monster(), false)); // 18 + floor(18 * 0.10)
		Loadout elite = withAll(loadout(Style.MAGIC, "slash", staff, helm), voidRobes(true));
		elite.setSpell("Water Wave");
		assertEquals(20, DpsCalculator.maxHit(MAXED, elite, monster(), false)); // 18 + floor(18 * 0.15)
	}

	@Test
	public void wrongHelmGivesNoBonus()
	{
		Loadout l = withAll(loadout(Style.MELEE, "slash", whip(), item("Void ranger helm (Normal)", "head")), voidRobes(false));
		assertEquals(25, DpsCalculator.maxHit(MAXED, l, monster(), false));
	}

	// ---- obsidian / berserker necklace ----

	private static Loadout obsidian(Equipment weapon, boolean armour)
	{
		Loadout l = loadout(Style.MELEE, "stab", weapon);
		if (armour)
		{
			withAll(l, item("Obsidian helmet", "head"), item("Obsidian platebody", "body"), item("Obsidian platelegs", "legs"));
		}
		return l;
	}

	/** Full obsidian with a Tzhaar weapon: + floor(base / 10) to the base roll and base max hit. */
	@Test
	public void obsidianArmourWithTzhaarWeapon()
	{
		Equipment ak = item("Toktz-xil-ak", "weapon", "stab", 47, "str", 49);
		// base max floor((110 * 113 + 320) / 640) = 19, + 1; base roll 107 * 111 = 11877, + 1187
		assertEquals(19, DpsCalculator.maxHit(MAXED, obsidian(ak, false), monster(), false));
		assertEquals(20, DpsCalculator.maxHit(MAXED, obsidian(ak, true), monster(), false));
		assertEquals(13064L, DpsCalculator.attackRoll(MAXED, obsidian(ak, true), monster(), false));
		Equipment sword = item("Rune sword", "weapon", "stab", 47, "str", 49);
		assertEquals(19, DpsCalculator.maxHit(MAXED, obsidian(sword, true), monster(), false));
	}

	/** Berserker necklace with a Tzhaar weapon: every hit x 6/5 (calculator scales the hit distribution). */
	@Test
	public void berserkerNecklaceWithTzhaarWeapon()
	{
		Equipment ak = item("Toktz-xil-ak", "weapon", "stab", 47, "str", 49);
		Loadout l = obsidian(ak, true);
		l.getBySlot().put("neck", item("Berserker necklace (or)", "neck"));
		assertEquals(24, DpsCalculator.maxHit(MAXED, l, monster(), false)); // floor(20 * 6 / 5)
		// Expected damage per accurate hit is the mean of floor(6d / 5) over d = 0..20, not 24 / 2.
		double mean = 0;
		for (int d = 0; d <= 20; d++)
		{
			mean += Math.floor(6.0 * d / 5);
		}
		mean /= 21;
		double expected = DpsCalculator.hitChance(MAXED, l, monster(), false) * mean / 2.4;
		assertEquals(expected, DpsCalculator.dps(MAXED, l, monster(), false), 1e-9);
		Loadout plain = obsidian(item("Rune sword", "weapon", "stab", 47, "str", 49), false);
		plain.getBySlot().put("neck", item("Berserker necklace", "neck"));
		assertEquals(19, DpsCalculator.maxHit(MAXED, plain, monster(), false));
	}

	// ---- inquisitor ----

	/** Crush only: helm +1, hauberk +2, plateskirt +2 over 200 to the final roll and max hit. */
	@Test
	public void inquisitorPerPieceOnCrush()
	{
		Equipment mace = item("Test mace", "weapon", "crush", 80, "str", 120);
		Loadout helmOnly = loadout(Style.MELEE, "crush", mace, item("Inquisitor's great helm", "head"));
		assertEquals(15408L * 201 / 200, DpsCalculator.attackRoll(MAXED, helmOnly, monster(), false));
		Loadout full = withAll(loadout(Style.MELEE, "crush", mace, item("Inquisitor's great helm", "head")),
			item("Inquisitor's hauberk", "body"), item("Inquisitor's plateskirt", "legs"));
		assertEquals(15408L * 205 / 200, DpsCalculator.attackRoll(MAXED, full, monster(), false));
		CombatStats piety = new CombatStats(99, 99, 99, 99, 99, 99, 99, 99);
		piety.setAssumeBoosts(true);
		piety.setPietyUnlocked(true);
		// strength 156 effective: floor((156 * 184 + 320) / 640) = 45 -> floor(45 * 205 / 200) = 46
		assertEquals(46, DpsCalculator.maxHit(piety, full, monster(), false));
		full.setMeleeType("slash");
		assertEquals(107L * 64, DpsCalculator.attackRoll(MAXED, full, monster(), false));
	}

	// ---- crystal ----

	/**
	 * Calculator's in-game test: slayer helmet (i) + crystal legs + crystal body + bow of faerdhinen, 99 Ranged, no
	 * prayer, on task: max 36 (it would be 37 with the crystal bonus after the helm).
	 */
	@Test
	public void crystalArmourWithBowfaBeforeSlayerHelm()
	{
		Loadout l = loadout(Style.RANGED, "slash", item("Bow of Faerdhinen (c)", "weapon", "ranged", 128, "ranged_str", 106),
			item("Slayer helmet (i)", "head"), item("Crystal body (Active)", "body"), item("Crystal legs (perfected)", "legs"));
		assertEquals(36, DpsCalculator.maxHit(MAXED, l, monster(), true));
		// roll 110 * 192 = 21120 -> x 25/20 = 26400 -> x 23/20 = 30360
		assertEquals(30360L, DpsCalculator.attackRoll(MAXED, l, monster(), true));
	}

	@Test
	public void crystalArmourNeedsCrystalBow()
	{
		Loadout l = loadout(Style.RANGED, "slash", item("Magic shortbow", "weapon", "ranged", 128, "ranged_str", 106),
			item("Crystal body (Active)", "body"));
		assertEquals(110L * 192, DpsCalculator.attackRoll(MAXED, l, monster(), false));
	}

	// ---- barrows ----

	/** Verac's: 25% of hits ignore accuracy and deal 1..max+1. */
	@Test
	public void veracsSet()
	{
		Loadout l = loadout(Style.MELEE, "crush", item("Verac's flail (Undamaged)", "weapon", "crush", 68, "str", 72),
			item("Verac's helm (Undamaged)", "head"), item("Verac's brassard (100)", "body"),
			item("Verac's plateskirt (Undamaged)", "legs"));
		int max = DpsCalculator.maxHit(MAXED, l, monster(), false);
		double acc = DpsCalculator.hitChance(MAXED, l, monster(), false);
		double expected = (0.75 * acc * max / 2.0 + 0.25 * (max + 2) / 2.0) / 2.4;
		assertEquals(expected, DpsCalculator.dps(MAXED, l, monster(), false), 1e-9);
		l.getBySlot().put("head", item("Verac's helm (0)", "head"));
		assertEquals(acc * max / 2.0 / 2.4, DpsCalculator.dps(MAXED, l, monster(), false), 1e-9);
	}

	/** Karil's with the amulet of the damned: 25% of hits add a second hitsplat of half the damage. */
	@Test
	public void karilsDamned()
	{
		Loadout l = loadout(Style.RANGED, "slash", item("Karil's crossbow (Undamaged)", "weapon", "ranged", 84),
			item("Bolt rack", "ammo", "ranged_str", 55), item("Karil's coif (Undamaged)", "head"),
			item("Karil's leathertop (Undamaged)", "body"), item("Karil's leatherskirt (Undamaged)", "legs"),
			item("Amulet of the damned (full)", "neck"));
		int max = DpsCalculator.maxHit(MAXED, l, monster(), false);
		double acc = DpsCalculator.hitChance(MAXED, l, monster(), false);
		double halves = 0;
		for (int d = 0; d <= max; d++)
		{
			halves += d / 2;
		}
		double expected = acc * (max / 2.0 + 0.25 * halves / (max + 1)) / 2.4;
		assertEquals(expected, DpsCalculator.dps(MAXED, l, monster(), false), 1e-9);
		assertTrue(expected > acc * max / 2.0 / 2.4);
	}
}

package com.slayercompanion.gear;

import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;

import java.util.Arrays;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;

public class SetupLayoutTest
{
	private static final int E = SetupLayout.EMPTY;

	@Test
	public void paperDollMatchesEquipmentScreen()
	{
		Map<String, Integer> slots = new LinkedHashMap<>();
		slots.put("head", 1);
		slots.put("cape", 2);
		slots.put("neck", 3);
		slots.put("ammo", 4);
		slots.put("weapon", 5);
		slots.put("body", 6);
		slots.put("shield", 7);
		slots.put("legs", 8);
		slots.put("hands", 9);
		slots.put("feet", 10);
		slots.put("ring", 11);

		int[] layout = SetupLayout.build(slots, Collections.emptyList());

		assertArrayEquals(new int[]{
			E, 1, E, E, E, E, E, E,
			2, 3, 4, E, E, E, E, E,
			5, 6, 7, E, E, E, E, E,
			E, 8, E, E, E, E, E, E,
			9, 10, 11}, layout);
	}

	@Test
	public void bringStartsAfterBlankRowBelowDoll()
	{
		Map<String, Integer> slots = Collections.singletonMap("weapon", 4151);
		int[] layout = SetupLayout.build(slots, Arrays.asList(385, 2434, 385, 4151, -1));

		// Row 5 is blank; bring starts at row 6, col 0. Duplicates and the worn weapon are skipped.
		assertEquals(6 * 8 + 2, layout.length);
		assertEquals(4151, layout[16]);
		for (int i = 5 * 8; i < 6 * 8; i++)
		{
			assertEquals(E, layout[i]);
		}
		assertEquals(385, layout[48]);
		assertEquals(2434, layout[49]);
	}

	@Test
	public void longBringListWrapsToNextRow()
	{
		int[] layout = SetupLayout.build(Collections.singletonMap("head", 1),
			Arrays.asList(10, 11, 12, 13, 14, 15, 16, 17, 18));
		assertEquals(17, layout[55]);
		assertEquals(18, layout[56]);
	}

	@Test
	public void bringOnlyStartsAtTop()
	{
		assertArrayEquals(new int[]{385, 2434}, SetupLayout.build(Collections.emptyMap(), Arrays.asList(385, 2434)));
	}

	@Test
	public void unknownSlotsAreIgnored()
	{
		assertEquals(E, SetupLayout.slotPosition("tail"));
		assertArrayEquals(new int[0], SetupLayout.build(Collections.singletonMap("tail", 5), null));
	}
}

package com.slayercompanion.gear;

import com.google.gson.Gson;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.slayercompanion.data.Equipment;
import com.slayercompanion.data.Monster;
import org.junit.Test;

/**
 * Monster-specific damage rules, checked against the OSRS Wiki DPS calculator maths.
 * Maxed stats: melee effective strength 110 / attack 107, ranged 110, magic 108.
 */
public class WeaponEffectsTest
{
	private static final Gson GSON = new Gson();

	private static final CombatStats MAXED = new CombatStats(99, 99, 99, 99, 99, 99, 99, 99);

	private static final int KURASK = 410;
	private static final int TUROTH = 427;
	private static final int KALPHITE_WORKER = 955;
	private static final int FERAL_VAMPYRE = 3237;
	private static final int VAMPYRE_JUVINATE = 3694;
	private static final int VYREWATCH_SENTINEL = 9756;

	private static Equipment item(String name, String slot, Object... kv)
	{
		Equipment e = new Equipment();
		e.setName(name);
		e.setSlot(slot);
		e.setSpeedTicks(4);
		for (int i = 0; i < kv.length; i += 2)
		{
			e.getBonuses().put((String) kv[i], (Integer) kv[i + 1]);
		}
		return e;
	}

	/** slash 70 / str 72: base max 23, attack roll 14338 at 99s. */
	private static Equipment sword(String name)
	{
		return item(name, "weapon", "slash", 70, "str", 72);
	}

	private static Loadout loadout(Style style, Equipment... items)
	{
		Loadout l = new Loadout();
		l.setStyle(style);
		l.setMeleeType("slash");
		for (Equipment e : items)
		{
			l.getBySlot().put(e.getSlot(), e);
		}
		return l;
	}

	private static Loadout spell(String spell, Equipment staff)
	{
		Loadout l = loadout(Style.MAGIC, staff);
		l.setSpell(spell);
		return l;
	}

	private static Monster monster(int id)
	{
		Monster m = new Monster();
		m.setId(id);
		m.setDefenceLevel(100);
		m.setMagicLevel(100);
		return m;
	}

	private static Monster plain()
	{
		return monster(1);
	}

	private static Monster dragon()
	{
		Monster m = monster(265);
		m.setDragon(true);
		return m;
	}

	private static Monster demon()
	{
		Monster m = monster(240);
		m.setDemon(true);
		return m;
	}

	private static int max(Loadout l, Monster m)
	{
		return DpsCalculator.maxHit(MAXED, l, m, false);
	}

	private static long roll(Loadout l, Monster m)
	{
		return DpsCalculator.attackRoll(MAXED, l, m, false);
	}

	// ---- Kurask / Turoth: leaf-bladed weapons, broad ammo or Magic Dart only ----

	@Test
	public void kuraskImmuneToOrdinaryMelee()
	{
		Loadout whip = loadout(Style.MELEE, item("Abyssal whip", "weapon", "slash", 82, "str", 82));
		assertEquals(0, max(whip, monster(KURASK)));
		assertEquals(0.0, DpsCalculator.dps(MAXED, whip, monster(KURASK), true), 0);
		assertTrue(WeaponEffects.isImmune(whip, monster(KURASK)));
		assertEquals(25, max(whip, plain()));
	}

	@Test
	public void leafBladedSpearAndSwordHurtKuraskAndTurothWithoutBonus()
	{
		Loadout spear = loadout(Style.MELEE, item("Leaf-bladed spear", "weapon", "slash", 47, "str", 50));
		assertEquals(20, max(spear, monster(KURASK)));
		Loadout sword = loadout(Style.MELEE, item("Leaf-bladed sword", "weapon", "slash", 47, "str", 50));
		assertEquals(20, max(sword, monster(TUROTH)));
	}

	@Test
	public void leafBladedBattleaxeDealsSeventeenPointFivePercentMoreDamageOnly()
	{
		Loadout axe = loadout(Style.MELEE, item("Leaf-bladed battleaxe", "weapon", "slash", 72, "str", 92));
		assertEquals(27, max(axe, plain()));
		// 27 * 47/40 = 31.7 -> 31; accuracy is unchanged (wiki: damage only)
		assertEquals(31, max(axe, monster(KURASK)));
		assertEquals(14552L, roll(axe, monster(KURASK)));
		assertEquals(14552L, roll(axe, plain()));
		// stacks after the slayer helm: floor(27 * 7/6) = 31, then * 47/40 = 36
		axe.getBySlot().put("head", item("Slayer helmet", "head"));
		assertEquals(36, DpsCalculator.maxHit(MAXED, axe, monster(TUROTH), true));
	}

	@Test
	public void kuraskNeedsBroadAmmoForRanged()
	{
		Equipment xbow = item("Rune crossbow", "weapon", "ranged", 90);
		Loadout runite = loadout(Style.RANGED, xbow, item("Runite bolts", "ammo", "ranged_str", 115));
		assertEquals(0, max(runite, monster(KURASK)));
		Loadout broad = loadout(Style.RANGED, xbow, item("Broad bolts", "ammo", "ranged_str", 100));
		assertEquals(28, max(broad, monster(KURASK)));
		Loadout amethyst = loadout(Style.RANGED, xbow, item("Amethyst broad bolts", "ammo", "ranged_str", 115));
		assertTrue(max(amethyst, monster(TUROTH)) > 0);
		Loadout arrows = loadout(Style.RANGED, item("Magic shortbow", "weapon", "ranged", 69),
			item("Broad arrows", "ammo", "ranged_str", 28));
		assertTrue(max(arrows, monster(KURASK)) > 0);
	}

	@Test
	public void kuraskOnlyTakesMagicDartFromSpells()
	{
		Equipment staff = item("Slayer's staff", "weapon", "magic", 10);
		assertEquals(0, max(spell("Fire Surge", staff), monster(KURASK)));
		// Magic Dart: floor(99 / 10) + 10 = 19
		assertEquals(19, max(spell("Magic Dart", staff), monster(KURASK)));
		assertEquals(5, DpsCalculator.speedTicks(spell("Magic Dart", staff)));
	}

	@Test
	public void magicDartWithEnchantedSlayerStaffOnTask()
	{
		Loadout l = spell("Magic Dart", item("Slayer's staff (e)", "weapon", "magic", 10));
		// floor(99 / 6) + 13 = 29 on task, the normal 19 off task
		assertEquals(29, DpsCalculator.maxHit(MAXED, l, monster(KURASK), true));
		assertEquals(19, DpsCalculator.maxHit(MAXED, l, monster(KURASK), false));
	}

	@Test
	public void magicDartNeedsASlayerStyleStaff()
	{
		assertEquals(0, max(spell("Magic Dart", item("Staff of air", "weapon", "magic", 10)), plain()));
		assertTrue(WeaponEffects.canCastMagicDart(item("Toxic staff of the dead (Charged)", "weapon")));
		assertTrue(WeaponEffects.canCastMagicDart(item("Staff of the Dead", "weapon")));
		assertTrue(WeaponEffects.canCastMagicDart(item("Staff of Light", "weapon")));
		assertTrue(WeaponEffects.canCastMagicDart(item("Staff of Balance", "weapon")));
		assertFalse(WeaponEffects.canCastMagicDart(item("Mystic water staff", "weapon")));
	}

	@Test
	public void restrictionHints()
	{
		assertEquals("Needs a leaf-bladed weapon, broad ammo or Magic Dart", WeaponEffects.immunityHint(monster(KURASK)));
		assertNotNull(WeaponEffects.immunityHint(monster(VAMPYRE_JUVINATE)));
		assertNotNull(WeaponEffects.immunityHint(monster(VYREWATCH_SENTINEL)));
		assertNull(WeaponEffects.immunityHint(monster(FERAL_VAMPYRE)));
		assertNull(WeaponEffects.immunityHint(plain()));
	}

	// ---- dragon hunter weapons vs draconic ----

	@Test
	public void dragonHunterLance()
	{
		Loadout l = loadout(Style.MELEE, item("Dragon hunter lance", "weapon", "slash", 85, "str", 70));
		assertEquals(23, max(l, plain()));
		assertEquals(15943L, roll(l, plain()));
		// +20% accuracy and damage: 23 * 6/5 = 27, 15943 * 6/5 = 19131
		assertEquals(27, max(l, dragon()));
