public class LocationRankerTest
{
	private static final WorldPoint PLAYER = new WorldPoint(3000, 3000, 0);

	private static Location loc(String id, String name, int x, int y, int plane)
	{
		Location l = new Location();
		l.setId(id);
		l.setName(name);
		WorldPointDto e = new WorldPointDto();
		e.setX(x);
		e.setY(y);
		e.setPlane(plane);
		l.setEntrance(e);
		return l;
	}

	private static List<RankedLocation> rank(List<Location> locs, Style style, Function<Location, Optional<String>> lock,
		Optional<String> konar, Set<String> safe)
	{
		return LocationRanker.rank(locs, style, PLAYER, lock, konar, l -> safe.contains(l.getId()), l -> 0, l -> 0);
	}

	private static final Function<Location, Optional<String>> OPEN = l -> Optional.empty();

	@Test
	public void lockedLocationsGoLastWithReason()
	{
		Location near = loc("near", "Near", 3001, 3000, 0);
		Location far = loc("far", "Far", 3050, 3000, 0);
		List<RankedLocation> r = rank(Arrays.asList(near, far), Style.MELEE,
			l -> l == near ? Optional.of("Needs boots of stone") : Optional.empty(),
			Optional.empty(), Collections.emptySet());
		assertEquals("far", r.get(0).getLocation().getId());
		assertTrue(r.get(0).isUsable());
		assertFalse(r.get(1).isUsable());
		assertEquals("Needs boots of stone", r.get(1).getLockedReason());
		assertFalse(r.get(1).isRecommended());
	}

	@Test
	public void konarOnlyAllowsAssignedArea()
	{
		Location a = loc("a", "Kourend Catacombs", 3001, 3000, 0);
		Location b = loc("b", "Slayer Tower", 3002, 3000, 0);
		List<RankedLocation> r = rank(Arrays.asList(b, a), Style.MELEE, OPEN,
			Optional.of("kourend catacombs"), Collections.emptySet());
		assertEquals("a", r.get(0).getLocation().getId());
		assertTrue(r.get(0).isUsable());
		assertFalse(r.get(1).isUsable());
		assertEquals("Not your Konar location", r.get(1).getLockedReason());
	}

	@Test
	public void konarWithNoMatchLocksNothing()
	{
		Location a = loc("a", "Slayer Tower", 3001, 3000, 0);
		List<RankedLocation> r = rank(Arrays.asList(a), Style.MELEE, OPEN,
			Optional.of("Nowhere Land"), Collections.emptySet());
		assertTrue(r.get(0).isUsable());
	}

	@Test
	public void safespotFirstForRanged()
	{
		Location near = loc("near", "Near", 3001, 3000, 0);
		Location safe = loc("safe", "Safe", 3100, 3000, 0);
		List<RankedLocation> r = rank(Arrays.asList(near, safe), Style.RANGED, OPEN, Optional.empty(),
			new HashSet<>(Arrays.asList("safe")));
		assertEquals("safe", r.get(0).getLocation().getId());
		assertTrue(r.get(0).isHasSafespot());
	}

	@Test
	public void safespotIgnoredForMelee()
	{
		Location near = loc("near", "Near", 3001, 3000, 0);
		Location safe = loc("safe", "Safe", 3100, 3000, 0);
		List<RankedLocation> r = rank(Arrays.asList(safe, near), Style.MELEE, OPEN, Optional.empty(),
			new HashSet<>(Arrays.asList("safe")));
		assertEquals("near", r.get(0).getLocation().getId());
	}

	@Test
	public void farLocationsAreStillOrderedByDistance()
	{
		Location far = loc("f", "F", 3300, 3000, 0);
		Location farther = loc("ff", "FF", 3600, 3000, 0);
		List<RankedLocation> r = rank(Arrays.asList(farther, far), Style.MELEE, OPEN, Optional.empty(),
			Collections.emptySet());
		assertEquals("f", r.get(0).getLocation().getId());
		assertEquals(90, r.get(0).getTravelSeconds(), 0.001);
		assertEquals(180, r.get(1).getTravelSeconds(), 0.001);
	}

	@Test
	public void planeChangeAddsThirtySeconds()
	{
		Location plane = loc("p", "P", 3010, 3000, 1);
		List<RankedLocation> r = rank(Arrays.asList(plane), Style.MELEE, OPEN, Optional.empty(), Collections.emptySet());
		assertEquals(3 + 30, r.get(0).getTravelSeconds(), 0.001);
	}

	@Test
	public void undergroundEntranceUsesOverworldEquivalent()
	{
		// 3020,9400 underground lies under 3020,3000: 20 tiles east -> 6 s, plus 30 s level change
		Location dungeon = loc("d", "D", 3020, 9400, 0);
		List<RankedLocation> r = rank(Arrays.asList(dungeon), Style.MELEE, OPEN, Optional.empty(), Collections.emptySet());
		assertEquals(6 + 30, r.get(0).getTravelSeconds(), 0.001);
	}

	@Test
	public void tiedTravelIsNotCalledClosest()
	{
		Location a = loc("a", "A", 3010, 3000, 0);
		Location b = loc("b", "B", 2990, 3000, 0);
		List<RankedLocation> r = rank(Arrays.asList(a, b), Style.MELEE, OPEN, Optional.empty(), Collections.emptySet());
		assertEquals("Best available", r.get(0).getWhy());
	}

	@Test
	public void travelIsChebyshevTimesPointThree()
	{
		Location l = loc("a", "A", 3010, 3004, 0);
		List<RankedLocation> r = rank(Arrays.asList(l), Style.MELEE, OPEN, Optional.empty(), Collections.emptySet());
		assertEquals(3.0, r.get(0).getTravelSeconds(), 0.001);
	}

	@Test
	public void recommendedWhyText()
	{
		Location near = loc("near", "Near", 3001, 3000, 0);
		Location safe = loc("safe", "Safe", 3002, 3000, 0);
		List<RankedLocation> r = rank(Arrays.asList(near, safe), Style.RANGED, OPEN, Optional.empty(),
			new HashSet<>(Arrays.asList("safe", "near")));
		assertTrue(r.get(0).isRecommended());
		assertEquals("Safespot · Closest", r.get(0).getWhy());
		assertFalse(r.get(1).isRecommended());
	}

	@Test
	public void recommendedWhySingleAndFallback()
	{
		Location a = loc("a", "A", 3001, 3000, 0);
		List<RankedLocation> melee = rank(Arrays.asList(a), Style.MELEE, OPEN, Optional.empty(), Collections.emptySet());
		assertEquals("Closest", melee.get(0).getWhy());

		// Safespot chosen but farther than a locked-out... usable but not closest
		Location close = loc("close", "Close", 3001, 3000, 0);
		Location safe = loc("safe", "Safe", 3100, 3000, 0);
		List<RankedLocation> r = rank(Arrays.asList(close, safe), Style.MAGIC, OPEN, Optional.empty(),
			new HashSet<>(Arrays.asList("safe")));
		assertEquals("Safespot", r.get(0).getWhy());
	}

	@Test
	public void noLocationsReturnsEmptyList()
	{
		assertTrue(rank(Collections.emptyList(), Style.MELEE, OPEN, Optional.empty(), Collections.emptySet()).isEmpty());
	}

	@Test
	public void allLockedMeansNoRecommendation()
	{
		Location a = loc("a", "A", 3001, 3000, 0);
		List<RankedLocation> r = rank(Arrays.asList(a), Style.MELEE, l -> Optional.of("x"), Optional.empty(),
			Collections.emptySet());
		assertFalse(r.get(0).isRecommended());
	}

	@Test
	public void routedTimeBeatsStraightLine()
	{
		// Straight-line, "far" is 10 minutes away; Shortest Path knows a teleport that makes it 1 minute.
		Location near = loc("near", "Near", 3300, 3000, 0); // 90 s on foot
		Location far = loc("far", "Far", 1000, 3000, 0);
		List<RankedLocation> r = LocationRanker.rank(Arrays.asList(near, far), Style.MELEE, PLAYER, OPEN,
			Optional.empty(), l -> false, l -> 0, l -> 0,
			l -> l == far ? java.util.OptionalDouble.of(60) : java.util.OptionalDouble.empty());
		assertEquals("far", r.get(0).getLocation().getId());
		assertEquals(60, r.get(0).getTravelSeconds(), 0.001);
		assertTrue(r.get(0).isTravelRouted());
		assertFalse(r.get(1).isTravelRouted());
	}
}

package com.slayercompanion.locations;

import static org.junit.Assert.assertEquals;

import com.slayercompanion.data.ItemNeed;
import com.slayercompanion.data.Location;
import com.slayercompanion.gear.OwnedItems;
import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.Optional;
import org.junit.Test;

public class RequirementsTest
{
	private static Location loc()
	{
		Location l = new Location();
		l.setId("x");
		l.setName("X");
		return l;
	}

	private static Optional<String> reason(Location l, int slayer, boolean questDone, OwnedItems owned)
	{
		return Requirements.lockReason(l, s -> "slayer".equals(s) ? slayer : -1, q -> questDone,
			q -> "Waterfall Quest", owned);
	}

	@Test
	public void usableWhenNothingRequired()
	{
		assertEquals(Optional.empty(), reason(loc(), 1, false, new OwnedItems()));
	}

	@Test
	public void skillReason()
	{
		Location l = loc();
		l.setSkillReqs(Collections.singletonMap("slayer", 62));
		assertEquals(Optional.of("Needs 62 Slayer"), reason(l, 61, true, new OwnedItems()));
		assertEquals(Optional.empty(), reason(l, 62, true, new OwnedItems()));
	}

	@Test
	public void unknownSkillDoesNotLock()
	{
		Location l = loc();
		l.setSkillReqs(Collections.singletonMap("sailing", 50));
		assertEquals(Optional.empty(), reason(l, 1, true, new OwnedItems()));
	}

	@Test
	public void questReason()
	{
		Location l = loc();
		l.setQuestReqs(Collections.singletonList("WATERFALL_QUEST"));
		assertEquals(Optional.of("Needs Waterfall Quest"), reason(l, 99, false, new OwnedItems()));
		assertEquals(Optional.empty(), reason(l, 99, true, new OwnedItems()));
	}

	@Test
	public void itemReasonSatisfiedByAnyId()
	{
		Location l = loc();
		ItemNeed boots = new ItemNeed();
		boots.setName("boots of stone");
		boots.setItemIds(Arrays.asList(23037, 22951));
		l.setItemReqs(Collections.singletonList(boots));
		assertEquals(Optional.of("Needs boots of stone"), reason(l, 99, true, new OwnedItems()));
		OwnedItems owned = new OwnedItems();
		owned.updateBank(Collections.singletonMap(22951, 1), Instant.now());
		assertEquals(Optional.empty(), reason(l, 99, true, owned));
	}
}

package com.slayercompanion.safespot;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.slayercompanion.data.Safespot;
import java.util.Collections;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class SafespotExportTest
{
	private static final Gson GSON = new Gson();

	private static List<Safespot> parse(String json)
	{
		return new Gson().fromJson(json, new TypeToken<List<Safespot>>() {}.getType());
	}

	@Test
	public void exportMatchesBundledFormat()
	{
		SafespotStore store = new SafespotStore(GSON, Collections.emptyList(), null);
		store.mark("loc", 5, new WorldPoint(10, 20, 1), "behind rock");
		List<Safespot> parsed = parse(SafespotExport.export(GSON, store));
		assertEquals(1, parsed.size());
		assertEquals(store.forLocation("loc"), parsed);
		Safespot s = parsed.get(0);
		assertEquals("player", s.getSource());
		assertTrue(s.isVerified());
		assertEquals(1, s.getTile().getPlane());
	}

	@Test
	public void exportExcludesUntouchedBuiltin()
	{
		SafespotStore store = new SafespotStore(GSON, List.of(SafespotStoreTest.builtin("loc", 1, 3, 4)), null);
		assertEquals(0, parse(SafespotExport.export(GSON, store)).size());
	}

	@Test
	public void exportIncludesConfirmedBuiltin()
	{
		SafespotStore store = new SafespotStore(GSON, List.of(SafespotStoreTest.builtin("loc", 1, 3, 4)), null);
		store.confirm(new WorldPoint(3, 4, 0));
		List<Safespot> parsed = parse(SafespotExport.export(GSON, store));
		assertEquals(1, parsed.size());
		assertTrue(parsed.get(0).isVerified());
		assertEquals("builtin", parsed.get(0).getSource());
	}
}

package com.slayercompanion.safespot;

import static org.junit.Assert.assertSame;

import com.slayercompanion.data.Location;
import com.slayercompanion.data.WorldPointDto;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class SafespotMenuTest
{
	private static Location loc(String id, int x, int y, int plane)
	{
		Location l = new Location();
		l.setId(id);
		l.setName(id);
		WorldPointDto e = new WorldPointDto();
		e.setX(x);
		e.setY(y);
		e.setPlane(plane);
		l.setEntrance(e);
		return l;
	}

	private static final Location WATERFALL = loc("waterfall", 2575, 9891, 0);
	private static final Location CATACOMBS = loc("catacombs", 1629, 10056, 0);
	private static final Location TOWER = loc("tower", 2580, 9895, 1);
	private static final List<Location> ALL = Arrays.asList(WATERFALL, CATACOMBS, TOWER);

	@Test
	public void picksLocationWhoseEntranceIsNearestThePlayer()
	{
		// Catacombs selected in the panel, but the player stands in the Waterfall Dungeon
		assertSame(WATERFALL, SafespotMenu.locationForMark(ALL, CATACOMBS, new WorldPoint(2600, 9900, 0)));
	}

	@Test
	public void ignoresOtherPlanes()
	{
		assertSame(TOWER, SafespotMenu.locationForMark(ALL, CATACOMBS, new WorldPoint(2581, 9895, 1)));
		assertSame(CATACOMBS, SafespotMenu.locationForMark(Collections.singletonList(TOWER), CATACOMBS,
			new WorldPoint(2581, 9895, 0)));
	}

	@Test
	public void fallsBackToSelectedWhenNothingWithin150Tiles()
	{
		assertSame(CATACOMBS, SafespotMenu.locationForMark(ALL, CATACOMBS, new WorldPoint(3200, 3200, 0)));
		assertSame(WATERFALL, SafespotMenu.locationForMark(ALL, CATACOMBS, new WorldPoint(2575 + 150, 9891, 0)));
		assertSame(CATACOMBS, SafespotMenu.locationForMark(ALL, CATACOMBS, new WorldPoint(2575 + 151, 9891, 0)));
		assertSame(CATACOMBS, SafespotMenu.locationForMark(ALL, CATACOMBS, null));
	}
}

package com.slayercompanion.safespot;

import com.google.gson.Gson;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import com.slayercompanion.data.Safespot;
import com.slayercompanion.data.WorldPointDto;
import java.util.Collections;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class SafespotStoreTest
{
	private static final Gson GSON = new Gson();

	static Safespot builtin(String loc, int monster, int x, int y)
	{
		Safespot s = new Safespot();
		s.setLocationId(loc);
		s.setMonsterId(monster);
		WorldPointDto t = new WorldPointDto();
		t.setX(x);
		t.setY(y);
		t.setPlane(0);
		s.setTile(t);
		s.setNote("wiki");
		s.setVerified(false);
		s.setSource("builtin");
		return s;
	}

	@Test
	public void markedSpotIsReturnedForLocation()
	{
		SafespotStore store = new SafespotStore(GSON, Collections.emptyList(), null);
		assertFalse(store.hasAny("loc"));
		store.mark("loc", 5, new WorldPoint(10, 20, 0), "behind rock");
		List<Safespot> spots = store.forLocation("loc");
		assertEquals(1, spots.size());
		assertTrue(spots.get(0).isVerified());
		assertEquals("player", spots.get(0).getSource());
		assertEquals("behind rock", spots.get(0).getNote());
		assertTrue(store.hasAny("loc"));
		assertTrue(store.forLocation("other").isEmpty());
	}

	@Test
	public void confirmFlipsVerified()
	{
		SafespotStore store = new SafespotStore(GSON, List.of(builtin("loc", 1, 3, 4)), "");
		assertFalse(store.forLocation("loc").get(0).isVerified());
		store.confirm(new WorldPoint(3, 4, 0));
		assertTrue(store.forLocation("loc").get(0).isVerified());
	}

	@Test
	public void rejectHidesBuiltin()
	{
		SafespotStore store = new SafespotStore(GSON, List.of(builtin("loc", 1, 3, 4)), null);
		store.reject(new WorldPoint(3, 4, 0));
		assertTrue(store.forLocation("loc").isEmpty());
		assertFalse(store.hasAny("loc"));
	}

	@Test
	public void persistsAcrossReload()
	{
		List<Safespot> b = List.of(builtin("loc", 1, 3, 4), builtin("loc", 1, 7, 8));
		SafespotStore store = new SafespotStore(GSON, b, null);
		store.mark("loc2", 9, new WorldPoint(1, 2, 1), "n");
		store.confirm(new WorldPoint(3, 4, 0));
		store.reject(new WorldPoint(7, 8, 0));
		SafespotStore reloaded = new SafespotStore(GSON, b, store.toJson());
		assertEquals(store.forLocation("loc"), reloaded.forLocation("loc"));
		assertEquals(1, reloaded.forLocation("loc").size());
		assertTrue(reloaded.forLocation("loc").get(0).isVerified());
		assertEquals(store.forLocation("loc2"), reloaded.forLocation("loc2"));
	}

	@Test
	public void badSavedJsonIsIgnored()
	{
		SafespotStore store = new SafespotStore(GSON, List.of(builtin("loc", 1, 3, 4)), "{not json");
		assertEquals(1, store.forLocation("loc").size());
	}

	@Test
	public void spotAtMatchesOnlyExactTileInLocation()
	{
		SafespotStore store = new SafespotStore(GSON, List.of(builtin("loc", 1, 3, 4)), null);
		assertEquals(3, store.spotAt("loc", new WorldPoint(3, 4, 0)).getTile().getX());
		assertEquals(null, store.spotAt("loc", new WorldPoint(3, 5, 0)));
		assertEquals(null, store.spotAt("loc", new WorldPoint(3, 4, 1)));
		assertEquals(null, store.spotAt("other", new WorldPoint(3, 4, 0)));
		store.reject(new WorldPoint(3, 4, 0));
		assertEquals(null, store.spotAt("loc", new WorldPoint(3, 4, 0)));
	}

	@Test
	public void loadReplacesPlayerStateAndCountsExportable()
	{
		SafespotStore a = new SafespotStore(GSON, List.of(builtin("loc", 1, 3, 4)), null);
		a.mark("loc", 1, new WorldPoint(10, 10, 0), "");
		a.confirm(new WorldPoint(3, 4, 0));
		assertEquals(2, a.exportableCount());

		SafespotStore b = new SafespotStore(GSON, List.of(builtin("loc", 1, 3, 4)), null);
		b.mark("loc", 1, new WorldPoint(20, 20, 0), "");
		b.load(a.toJson());
		assertEquals(2, b.exportableCount());
		assertEquals(null, b.spotAt("loc", new WorldPoint(20, 20, 0)));
		b.load(null);
		assertEquals(0, b.exportableCount());
		assertEquals(1, b.forLocation("loc").size());
	}
}

package com.slayercompanion.session;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import org.junit.Test;

public class BagPickupsTest
{
