		assertEquals(Optional.of("1 bag of salt · 3 left"), FinishingItems.BAG_OF_SALT.line(1, 3));
		assertEquals(Optional.of("No fungicide charges carried · 9 left"), FinishingItems.FUNGICIDE.line(0, 9));
		assertFalse(FinishingItems.ICE_COOLER.line(5, 0).isPresent());
	}

	@Test
	public void warningWhenShort()
	{
		assertEquals(Optional.of("Ice coolers run out ~17 kills before task end"),
			FinishingItems.ICE_COOLER.warning(23, 40));
		assertEquals(Optional.of("Bags of salt run out ~1 kill before task end"),
			FinishingItems.BAG_OF_SALT.warning(9, 10));
		assertEquals(Optional.of("No fungicide charges carried · needed to finish kills"),
			FinishingItems.FUNGICIDE.warning(0, 10));
		assertFalse(FinishingItems.ICE_COOLER.warning(40, 40).isPresent());
		assertFalse(FinishingItems.ICE_COOLER.warning(0, 0).isPresent());
	}
}

package com.slayercompanion.session;

import static org.junit.Assert.assertEquals;

import java.time.Duration;
import java.util.HashMap;
import java.util.Map;
import org.junit.Test;

public class PickedUpLootTest
{
	private static final int RUNE_SCIM = 1333;
	private static final int BONES = 532;
	private static final int COINS = 995;
	private static final int RANARR = 207;
	private static final int UNCUT_RUBY = 1619;

	private Duration now = Duration.ZERO;
	private final PickedUpLoot loot = new PickedUpLoot();

	private static Map<Integer, Integer> inv(int... idQty)
	{
		Map<Integer, Integer> m = new HashMap<>();
		for (int i = 0; i < idQty.length; i += 2)
		{
			m.put(idQty[i], idQty[i + 1]);
		}
		return m;
	}

	@Test
	public void countsOnlyWhatIsPickedUp()
	{
		loot.onDrop(RUNE_SCIM, 1, 15_000, now);
		loot.onDrop(BONES, 1, 100, now);
		loot.onCarried(inv(), now);
		loot.onCarried(inv(RUNE_SCIM, 1), now.plusSeconds(5)); // bones left on the floor
		assertEquals(15_000, loot.total());
	}

	@Test
	public void stackablesCountUpToWhatDropped()
	{
		loot.onDrop(COINS, 300, 1, now);
		loot.onCarried(inv(COINS, 1000), now);
		loot.onCarried(inv(COINS, 1300), now);
		assertEquals(300, loot.total());
		loot.onCarried(inv(COINS, 1700), now); // more coins than dropped: not task loot
		assertEquals(300, loot.total());
	}

	@Test
	public void dropsExpireOffTheGround()
	{
		loot.onDrop(RUNE_SCIM, 1, 15_000, now);
		loot.onCarried(inv(), now);
		loot.onCarried(inv(RUNE_SCIM, 1), now.plus(PickedUpLoot.GROUND_TIME).plusSeconds(1));
		assertEquals(0, loot.total());
	}

	@Test
	public void bankWithdrawalsAreNotLoot()
	{
		loot.onDrop(RUNE_SCIM, 1, 15_000, now);
		loot.onCarried(inv(), now);
		loot.setBankOpen(true);
		loot.onCarried(inv(RUNE_SCIM, 1), now);
		loot.setBankOpen(false);
		loot.onCarried(inv(RUNE_SCIM, 1), now);
		assertEquals(0, loot.total());
	}

	@Test
	public void droppingAndRepickingCountsOnce()
	{
		loot.onDrop(RUNE_SCIM, 1, 15_000, now);
		loot.onCarried(inv(), now);
		loot.onCarried(inv(RUNE_SCIM, 1), now);
		loot.onCarried(inv(), now);
		loot.onCarried(inv(RUNE_SCIM, 1), now);
		assertEquals(15_000, loot.total());
	}

	@Test
	public void ringOfWealthCoinsCountWhenTheyArriveWithAKill()
	{
		loot.onCarried(inv(COINS, 1000), now);
		loot.onKill(now);
		loot.onCarried(inv(COINS, 1250), now.plusMillis(600)); // never hit the ground
		assertEquals(250, loot.total());
	}

	@Test
	public void ringOfWealthCoinsJustBeforeTheKillCountToo()
	{
		loot.onCarried(inv(COINS, 1000), now);
		loot.onCarried(inv(COINS, 1250), now);
		loot.onKill(now.plusMillis(600));
		assertEquals(250, loot.total());
	}

	@Test
	public void coinsLongAfterAKillAreNotLoot()
	{
		loot.onCarried(inv(COINS, 1000), now);
		loot.onKill(now);
		loot.onCarried(inv(COINS, 5000), now.plusSeconds(30)); // e.g. sold something
		assertEquals(0, loot.total());
	}

	@Test
	public void groundCoinsAreNotCountedTwice()
	{
		loot.onCarried(inv(COINS, 1000), now);
		loot.onKill(now);
		loot.onDrop(COINS, 300, 1, now);
		loot.onCarried(inv(COINS, 1300), now.plusMillis(600));
		assertEquals(300, loot.total());
	}

	@Test
	public void herbsIntoAnOpenSackCountByName()
	{
		loot.onDrop(RANARR, "Grimy ranarr weed", 1, 7_000, now);
		loot.onCarried(inv(), now);
		loot.onBagged("grimy ranarr weed", 1, now.plusSeconds(5)); // never reaches the inventory
		assertEquals(7_000, loot.total());
		loot.onBagged("Grimy ranarr weed", 1, now.plusSeconds(6)); // e.g. from a herbiboar, not dropped
		assertEquals(7_000, loot.total());
	}

	@Test
	public void gemsIntoAnOpenBagCountById()
	{
		loot.onDrop(UNCUT_RUBY, 1, 1_000, now);
		loot.onBagged(UNCUT_RUBY, 1, now.plusSeconds(5));
		assertEquals(1_000, loot.total());
	}

	@Test
	public void baggedItemsMustMatchAPendingDrop()
	{
		loot.onDrop(RANARR, "Grimy ranarr weed", 1, 7_000, now);
		loot.onBagged("Grimy toadflax", 1, now);
		loot.onBagged(UNCUT_RUBY, 1, now);
		loot.onBagged("Grimy ranarr weed", 1, now.plus(PickedUpLoot.GROUND_TIME).plusSeconds(1)); // despawned
		assertEquals(0, loot.total());
	}

	@Test
	public void baggedSeedsCountUpToWhatDropped()
	{
		loot.onDrop(5295, "Ranarr seed", 2, 30_000, now);
		loot.onBagged("Ranarr seed", 3, now);
		assertEquals(60_000, loot.total());
	}
}

package com.slayercompanion.session;

import java.util.HashMap;
import java.util.Map;
import java.util.OptionalInt;
import net.runelite.api.ItemID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class PrayerRunwayTest
{
	private PrayerRunway r;

	@Before
	public void setUp()
	{
		r = new PrayerRunway();
	}

	@Test
	public void restoreFormulas()
	{
		assertEquals(7 + 17, PrayerRunway.restorePerDose("Prayer potion", 70));
		assertEquals(8 + 17, PrayerRunway.restorePerDose("Super restore", 70));
		assertEquals(8 + 24, PrayerRunway.restorePerDose("Sanfew serum", 99));
		assertEquals(8 + 10, PrayerRunway.restorePerDose("Blighted super restore", 43));
		assertEquals(0, PrayerRunway.restorePerDose("Ranging potion", 70));
	}

	@Test
	public void drainWithNoPotions()
	{
		r.onPrayerPoints(70);
		r.onPrayerPoints(65);
		r.onKill(1);
		// drain before the first kill is not counted
		r.onPrayerPoints(60);
		r.onPrayerPoints(55);
		r.onKill(1);
		r.onPrayerPoints(50);
		r.onKill(1);
		assertEquals(15, r.drained());
		assertEquals(7.5, r.drainPerKill().getAsDouble(), 1e-9);
		// 50 points / 7.5 = 6.67 -> 6
		assertEquals(OptionalInt.of(6), r.killsLeft(50, 0, 70));
		// plus 2 prayer potion doses at 70: 50 + 2 * 24 = 98 / 7.5 = 13
		assertEquals(OptionalInt.of(13), r.killsLeft(50, 2, 70));
	}

	@Test
	public void drinkingADoseIsNotDrain()
	{
		r.onPrayerPoints(40);
		r.onKill(1);
		r.onPrayerPoints(30);
		r.onKill(1);
		r.onPrayerPoints(54); // drank a dose
		r.onPrayerPoints(44);
		r.onKill(1);
		assertEquals(20, r.drained());
		assertEquals(10.0, r.drainPerKill().getAsDouble(), 1e-9);
	}

	@Test
	public void notPrayingIsEmpty()
	{
		r.onPrayerPoints(70);
		r.onKill(1);
		r.onKill(1);
		r.onKill(1);
		OptionalInt left = r.killsLeft(70, 4, 70);
		assertFalse(left.isPresent());
		assertEquals("70 prayer points", PrayerRunway.line(left, 70));
		assertFalse(PrayerRunway.warning(left, 30).isPresent());
	}

	@Test
	public void emptyBeforeAMeasuredKill()
	{
		r.onPrayerPoints(70);
		r.onKill(1);
		r.onPrayerPoints(60);
		assertFalse(r.killsLeft(60, 0, 70).isPresent());
	}

	@Test
	public void resetClearsDrain()
	{
		r.onPrayerPoints(70);
		r.onKill(1);
		r.onPrayerPoints(60);
		r.onKill(1);
		assertTrue(r.drainPerKill().isPresent());
		r.reset();
		assertEquals(0, r.drained());
		assertFalse(r.drainPerKill().isPresent());
		// drain before the new task's first kill is not counted; the last reading stays the baseline
		r.onPrayerPoints(55);
		r.onKill(1);
		r.onPrayerPoints(50);
		r.onKill(1);
		assertEquals(5, r.drained());
	}

	@Test
	public void linesAndWarning()
	{
		assertEquals("Lasts ~25 kills", PrayerRunway.line(OptionalInt.of(25), 40));
		assertEquals("Lasts ~1 kill", PrayerRunway.line(OptionalInt.of(1), 40));
		assertEquals("Prayer runs out ~15 kills before task end",
			PrayerRunway.warning(OptionalInt.of(25), 40).get());
		assertFalse(PrayerRunway.warning(OptionalInt.of(40), 40).isPresent());
	}

	@Test
	public void killsLeftFromSupplyTracker()
	{
		Map<Integer, String> names = new HashMap<>();
		names.put(ItemID.PRAYER_POTION4, "Prayer potion(4)");
		names.put(ItemID.SUPER_RESTORE2, "Super restore(2)");
		SupplyTracker s = new SupplyTracker(id -> 0, names::get);
		Map<Integer, Integer> inv = new HashMap<>();
		inv.put(ItemID.PRAYER_POTION4, 1);
		inv.put(ItemID.SUPER_RESTORE2, 1);
		s.onSnapshot(inv);

		r.onPrayerPoints(70);
		r.onKill(1);
		r.onPrayerPoints(60);
		r.onKill(1);
		// 10 + 4 * 24 + 2 * 25 = 156 / 10 per kill
		assertEquals(OptionalInt.of(15), r.killsLeft(10, s, 70));
	}
}

