package com.slayercompanion.session;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import net.runelite.api.ItemID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class SupplyTrackerTest
{
	private static final int ARROW = ItemID.RUNE_ARROW;
	private static final int BOW = ItemID.MAGIC_SHORTBOW;
	private static final int FIRE = ItemID.FIRE_RUNE;
	private static final int PRAY4 = ItemID.PRAYER_POTION4;
	private static final int PRAY3 = ItemID.PRAYER_POTION3;
	private static final int PRAY2 = ItemID.PRAYER_POTION2;
	private static final int RESTORE1 = ItemID.SUPER_RESTORE1;

	private final Map<Integer, Long> prices = new HashMap<>();
	private final Map<Integer, String> names = new HashMap<>();
	private SupplyTracker t;

	@Before
	public void setUp()
	{
		prices.put(ARROW, 60L);
		prices.put(FIRE, 5L);
		prices.put(PRAY4, 8000L);
		prices.put(PRAY3, 6000L);
		prices.put(ItemID.SHARK, 900L);
		prices.put(ItemID.SUPER_RESTORE4, 12000L);
		prices.put(RESTORE1, 3000L);
		names.put(PRAY4, "Prayer potion(4)");
		names.put(PRAY3, "Prayer potion(3)");
		names.put(PRAY2, "Prayer potion(2)");
		names.put(RESTORE1, "Super restore(1)");
		names.put(ItemID.VIAL, "Vial");
		t = new SupplyTracker(id -> prices.getOrDefault(id, 0L), names::get);
	}

	private static Map<Integer, Integer> items(int... idQty)
	{
		Map<Integer, Integer> m = new HashMap<>();
		for (int i = 0; i < idQty.length; i += 2)
		{
			m.put(idQty[i], idQty[i + 1]);
		}
		return m;
	}

	@Test
	public void arrowsFired()
	{
		t.onSnapshot(items(BOW, 1, ARROW, 500));
		t.onKill(1);
		t.onSnapshot(items(BOW, 1, ARROW, 480));
		t.onKill(1);
		t.onSnapshot(items(BOW, 1, ARROW, 460));
		assertEquals(40, t.usedTotal(ARROW));
		assertEquals(20.0, t.usedPerKill(ARROW).getAsDouble(), 1e-9);
		assertEquals(20 * 60.0, t.costPerKill().getAsDouble(), 1e-9);
		assertEquals(460, t.count(ARROW));
	}

	@Test
	public void runesCast()
	{
		t.onSnapshot(items(FIRE, 1000));
		t.onKill(1);
		t.onSnapshot(items(FIRE, 900));
		assertEquals(100, t.usedTotal(FIRE));
		assertEquals(500.0, t.costPerKill().getAsDouble(), 1e-9);
	}

	@Test
	public void potionDoseIsOneDose()
	{
		t.onSnapshot(items(PRAY4, 2));
		t.onKill(1);
		t.onSnapshot(items(PRAY4, 1, PRAY3, 1));
		assertEquals(1, t.dosesUsed("Prayer potion"));
		assertEquals(0, t.usedTotal(PRAY4));
		// one dose at 8000 / 4
		assertEquals(2000.0, t.costPerKill().getAsDouble(), 1e-9);
		t.onKill(1);
		t.onSnapshot(items(PRAY4, 1, PRAY2, 1));
		assertEquals(2, t.dosesUsed("Prayer potion"));
		assertEquals(1.0, t.dosesUsedPerKill(SupplyTracker.PRAYER_FAMILIES).getAsDouble(), 1e-9);
		assertEquals(6, t.doses(SupplyTracker.PRAYER_FAMILIES));
	}

	@Test
	public void lastDoseLeavesEmptyVialAtNoCost()
	{
		names.put(ItemID.SUPER_RESTORE4, "Super restore(4)");
		t.onSnapshot(items(RESTORE1, 1, ItemID.SUPER_RESTORE4, 1));
		t.onKill(1);
		t.onSnapshot(items(ItemID.VIAL, 1, ItemID.SUPER_RESTORE4, 1));
		t.onSnapshot(items(ItemID.SUPER_RESTORE4, 1)); // vial smashed or dropped
		assertEquals(1, t.dosesUsed("Super restore"));
		assertEquals(0, t.usedTotal(ItemID.VIAL));
		assertEquals(3000.0, t.costPerKill().getAsDouble(), 1e-9);
	}

	@Test
	public void bankingNotCounted()
	{
		t.onSnapshot(items(ItemID.SHARK, 10, ARROW, 500));
		t.onKill(1);
		t.setBankOpen(true);
		t.onSnapshot(items(ARROW, 500));
		t.onSnapshot(items(ItemID.SHARK, 20, ARROW, 100));
		t.setBankOpen(false);
		assertEquals(0, t.costPerKill().getAsDouble(), 0.0);
		t.onSnapshot(items(ItemID.SHARK, 19, ARROW, 100));
		assertEquals(1, t.foodUsed());
		assertEquals(1, t.usedTotal(ItemID.SHARK));
		assertEquals(0, t.usedTotal(ARROW));
	}

	@Test
	public void equippingNotCounted()
	{
		// The bow moves from inventory to worn; the combined snapshot is unchanged.
		t.onSnapshot(items(BOW, 1, ARROW, 500));
		t.onKill(1);
		t.onSnapshot(items(BOW, 1, ARROW, 500));
		assertEquals(0, t.usedTotal(BOW));
		assertEquals(0.0, t.costPerKill().getAsDouble(), 0.0);
	}

	@Test
	public void lootIgnored()
	{
		t.onSnapshot(items(ARROW, 500));
		t.onKill(1);
		t.onSnapshot(items(ARROW, 500, FIRE, 50, ItemID.SHARK, 3));
		assertEquals(0.0, t.costPerKill().getAsDouble(), 0.0);
		assertEquals(0, t.usedTotal(FIRE));
	}

	@Test
	public void beforeFirstKillIgnored()
	{
		t.onSnapshot(items(ARROW, 500, ItemID.SHARK, 10));
		t.onSnapshot(items(ARROW, 450, ItemID.SHARK, 8));
		assertFalse(t.costPerKill().isPresent());
		assertEquals(0, t.usedTotal(ARROW));
		t.onKill(1);
		t.onSnapshot(items(ARROW, 440, ItemID.SHARK, 8));
		assertEquals(10, t.usedTotal(ARROW));
		assertEquals(0, t.foodUsed());
	}

	@Test
	public void resetClearsUsageButKeepsBaseline()
	{
		t.onSnapshot(items(ARROW, 500));
		t.onKill(1);
		t.onSnapshot(items(ARROW, 400));
		t.reset();
		assertEquals(0, t.usedTotal(ARROW));
		assertFalse(t.costPerKill().isPresent());
		t.onKill(1);
		t.onSnapshot(items(ARROW, 390));
		assertEquals(10, t.usedTotal(ARROW));
	}

	@Test
	public void foodRunway()
	{
		t.onSnapshot(items(ItemID.SHARK, 20));
		t.onKill(2);
		t.onSnapshot(items(ItemID.SHARK, 16)); // 2 per kill
		assertEquals(8, t.killsUntilFoodRunsOut().getAsInt());
		assertEquals(16, t.foodCount());
	}

	@Test
	public void parsesDoseNames()
	{
		assertEquals(new SupplyTracker.Dose("Prayer potion", 4), SupplyTracker.parseDose("Prayer potion(4)").get());
		assertEquals(new SupplyTracker.Dose("Black mask", 10), SupplyTracker.parseDose("Black mask (10)").get());
		assertFalse(SupplyTracker.parseDose("Black mask (i)").isPresent());
		assertFalse(SupplyTracker.parseDose("Shark").isPresent());
		assertFalse(SupplyTracker.parseDose(null).isPresent());
		assertTrue(SupplyTracker.PRAYER_FAMILIES.containsAll(Set.of("Prayer potion", "Super restore")));
	}

	@Test
	public void chargesUsedAreCostedInFractions()
	{
		prices.put(ItemID.ZULRAHS_SCALES, 150L);
		t.onSnapshot(items());
		t.onKill(1);
		for (int i = 0; i < 3; i++)
		{
			t.addChargeUsed(ItemID.ZULRAHS_SCALES, 2 / 3.0);
		}
		assertEquals(2.0, t.chargeMaterialUsed(ItemID.ZULRAHS_SCALES), 1e-9);
		assertEquals(300.0, t.costTotal(), 1e-6);
		assertEquals(0, t.usedTotal(ItemID.ZULRAHS_SCALES));
		t.reset();
		assertEquals(0.0, t.costTotal(), 0.0);
	}

	@Test
	public void itemsIgnoredWhileTheirCarrierIsCarried()
	{
		int pipe = ItemID.TOXIC_BLOWPIPE;
		int dart = ItemID.DRAGON_DART;
		t.ignoreWhileCarried(Set.of(pipe), Set.of(dart));
		t.onSnapshot(items(pipe, 1, dart, 300));
		t.onKill(1);
		t.onSnapshot(items(pipe, 1, dart, 100)); // loaded into the blowpipe
		assertEquals(0, t.usedTotal(dart));
		t.onSnapshot(items(dart, 100));
		t.onSnapshot(items(dart, 90)); // no blowpipe: thrown
		assertEquals(10, t.usedTotal(dart));
	}
}

package com.slayercompanion.session;

import com.slayercompanion.data.Drop;
import com.slayercompanion.data.Monster;
import com.slayercompanion.data.SlayerTask;
import com.slayercompanion.task.CurrentTask;
import java.time.Clock;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import java.time.ZoneOffset;
import java.util.Map;
import java.util.Optional;
import net.runelite.api.ItemID;
import org.junit.Test;
import static org.junit.Assert.*;

public class TaskSessionTest
{
	private static class MutableClock extends Clock
	{
		Instant now = Instant.parse("2026-01-01T00:00:00Z");

		void advance(long seconds)
		{
			now = now.plus(Duration.ofSeconds(seconds));
		}

		@Override
		public ZoneId getZone()
		{
			return ZoneOffset.UTC;
		}

		@Override
		public Clock withZone(ZoneId zone)
		{
			return this;
		}

		@Override
		public Instant instant()
		{
			return now;
		}
	}

	private final MutableClock clock = new MutableClock();
	private final TaskSession session = new TaskSession(clock);

	private static CurrentTask task(String name, int remaining, int initial)
	{
		SlayerTask t = new SlayerTask();
		t.setId(name.toLowerCase());
		t.setName(name);
		return new CurrentTask(t, remaining, initial, Optional.empty(), Optional.empty(), 0);
	}

	@Test
	public void killsComeFromGameCounter()
	{
		session.onTaskUpdate(task("Abyssal demons", 142, 142));
		session.onTaskUpdate(task("Abyssal demons", 139, 142));
		assertEquals(139, session.remaining());
		assertEquals(142, session.total());
		assertEquals(3, session.kills());
	}

	@Test
	public void secondsPerKillAndTimeLeft()
	{
		session.onTaskUpdate(task("Abyssal demons", 142, 142));
		session.onTaskUpdate(task("Abyssal demons", 141, 142)); // kill 1 starts the clock
		clock.advance(96);
		session.onTaskUpdate(task("Abyssal demons", 138, 142)); // 4 kills over 96 s -> 3 timed kills
		assertEquals(32.0, session.secondsPerKill().getAsDouble(), 1e-9);
		assertEquals(32.0 * 138, session.secondsLeft().getAsDouble(), 1e-9);
		assertEquals(112.5, session.killsPerHour().getAsDouble(), 1e-9);
	}

	@Test
	public void timingHiddenAfterOnlyOneKill()
	{
		session.onTaskUpdate(task("Abyssal demons", 142, 142));
		session.onTaskUpdate(task("Abyssal demons", 141, 142));
		clock.advance(40);
		assertFalse(session.secondsPerKill().isPresent());
		assertFalse(session.killsPerHour().isPresent());
		assertFalse(session.secondsLeft().isPresent());
	}

	@Test
	public void pausesWhileLoggedOut()
	{
		session.onTaskUpdate(task("Abyssal demons", 100, 100));
		session.onTaskUpdate(task("Abyssal demons", 99, 100));
		clock.advance(30);
		session.onLoggedOut();
		clock.advance(10_000);
		session.onLoggedIn();
		clock.advance(30);
		session.onTaskUpdate(task("Abyssal demons", 97, 100));
		// 3 kills, the 2 after the first took 60 active seconds
		assertEquals(30.0, session.secondsPerKill().getAsDouble(), 1e-9);
	}

	@Test
	public void newTaskResets()
	{
		session.onTaskUpdate(task("Abyssal demons", 100, 100));
		session.onTaskUpdate(task("Abyssal demons", 99, 100));
		clock.advance(30);
		session.onTaskUpdate(task("Abyssal demons", 98, 100));
		session.onLoot(4151, "Abyssal whip", 1, 2_000_000L);
		session.onSuperior();
		session.onTaskUpdate(task("Gargoyles", 120, 120));
		assertEquals(120, session.remaining());
		assertEquals(0, session.kills());
		assertEquals(0, session.superiors());
		assertEquals(0L, session.lootTotal());
		assertFalse(session.secondsPerKill().isPresent());
		assertFalse(session.bestDrop().isPresent());
	}

	@Test
	public void bestDropKeepsHighestValueWithRate()
	{
		Monster m = new Monster();
		Drop scim = new Drop();
		scim.setItemId(1333);
		scim.setName("Rune scimitar");
		scim.setRate(1.0 / 128);
		m.getDrops().add(scim);
		session.setMonster(m);
		session.onTaskUpdate(task("Abyssal demons", 10, 10));
		session.onSupplies(Map.of());
		session.onLoot(995, "Coins", 500, 1);
		session.onLoot(1333, "Rune scim", 1, 15000);
		session.onLoot(560, "Death rune", 10, 100);
		session.onLoot(532, "Bones", 1, 100); // left on the floor
		session.onSupplies(Map.of(995, 500, 1333, 1, 560, 10));
		TaskSession.BestDrop best = session.bestDrop().get();
		assertEquals("Rune scimitar", best.getName());
		assertEquals(15000L, best.getValue());
		assertEquals(1.0 / 128, best.getRate(), 1e-12);
		assertEquals(500 + 15000 + 1000, session.lootTotal());
	}

	@Test
	public void lootTakenByAnOpenBagCounts()
	{
		session.onTaskUpdate(task("Abyssal demons", 10, 10));
		session.onSupplies(Map.of());
		session.onLoot(207, "Grimy ranarr weed", 1, 7000);
		session.onLoot(1619, "Uncut ruby", 1, 1000);
		session.onBagMessage("You put the Grimy ranarr weed herb into your herb sack.");
		session.onGroundTake(1619);
		session.onBagMessage("You put it straight into your open gem bag.");
		assertEquals(8000L, session.lootTotal());
	}

	@Test
	public void bestDropOffTableUsesItemNameWithNoRate()
	{
		session.setMonster(new Monster());
		session.onTaskUpdate(task("Abyssal demons", 10, 10));
		session.onLoot(12345, "Clue scroll (hard)", 1, 5000);
		TaskSession.BestDrop best = session.bestDrop().get();
		assertEquals("Clue scroll (hard)", best.getName());
		assertEquals(0.0, best.getRate(), 0.0);
		session.onLoot(23456, null, 1, 9000);
		assertEquals("Item 23456", session.bestDrop().get().getName());
	}

	private static Map<Integer, Integer> food(int sharks)
	{
		return Map.of(ItemID.SHARK, sharks);
	}

	@Test
	public void foodRunway()
	{
		session.onTaskUpdate(task("Abyssal demons", 100, 100));
		session.onSupplies(food(6));
		session.onTaskUpdate(task("Abyssal demons", 99, 100));
		session.onTaskUpdate(task("Abyssal demons", 75, 100)); // 25 kills
		session.onSupplies(food(10)); // withdrawing, ignored
		session.onSupplies(food(6)); // 4 eaten / 25 kills = 0.16
		assertEquals(37, session.killsUntilFoodRunsOut().getAsInt());
	}

	@Test
	public void bankingDoesNotCountAsEating()
	{
		session.onTaskUpdate(task("Abyssal demons", 100, 100));
		session.onSupplies(food(10));
		session.onTaskUpdate(task("Abyssal demons", 90, 100)); // 10 kills
		session.onSupplies(food(8)); // 2 eaten
		session.setBankOpen(true);
		session.onSupplies(food(0)); // deposited
		session.onSupplies(food(20)); // withdrew
		session.onSupplies(food(18)); // put two back
		session.setBankOpen(false);
		session.onSupplies(food(17)); // 1 eaten
		// 3 eaten / 10 kills = 0.3 per kill; 17 left -> 56 kills
		assertEquals(56, session.killsUntilFoodRunsOut().getAsInt());
	}

	@Test
	public void nextTaskBonusAt49()
	{
		assertTrue(session.nextTaskIsBonus(49));
		assertFalse(session.nextTaskIsBonus(50));
	}

	@Test
	public void levelProgress()
	{
		// level 50 = 101333 xp, level 51 = 111945 xp
		assertEquals(0.0, session.levelProgressAtTaskEnd(101_333, 0), 1e-9);
		session.onTaskUpdate(task("Abyssal demons", 10, 10));
		double expected = (101_333 + 10 * 100 - 101_333) / (double) (111_945 - 101_333);
		assertEquals(expected, session.levelProgressAtTaskEnd(101_333, 100), 1e-9);
	}

	@Test
	public void noStatsBeforeFirstKill()
	{
		session.onTaskUpdate(task("Abyssal demons", 142, 142));
		assertFalse(session.secondsPerKill().isPresent());
		assertFalse(session.killsPerHour().isPresent());
		assertFalse(session.secondsLeft().isPresent());
		assertFalse(session.gpPerKill().isPresent());
		assertFalse(session.killsUntilFoodRunsOut().isPresent());
		assertFalse(session.bestDrop().isPresent());
		assertEquals(0.0, session.slayerXpPerHour(100), 0.0);
	}

	@Test
	public void weaponChargesAreCostedAsSupplies()
	{
		Map<Integer, Long> prices = Map.of(ItemID.DEATH_RUNE, 200L, ItemID.CHAOS_RUNE, 80L, ItemID.FIRE_RUNE, 5L,
			ItemID.COINS_995, 1L, ItemID.ZULRAHS_SCALES, 150L);
		TaskSession s = new TaskSession(clock, new SupplyTracker(id -> prices.getOrDefault(id, 0L), id -> null));
		s.onSupplies(Map.of(ItemID.TRIDENT_OF_THE_SEAS, 1, ItemID.ZULRAHS_SCALES, 1000));
		s.onTaskUpdate(task("Abyssal demons", 100, 100));
		s.onWeaponTick(ItemID.TRIDENT_OF_THE_SEAS, -1, WeaponCharges.POWERED_STAFF_ANIMATION, 0, true, -1, false);
		assertEquals("before the first kill", 0.0, s.supplies().costTotal(), 0.0);
		s.onTaskUpdate(task("Abyssal demons", 99, 100));
		s.onWeaponTick(ItemID.TRIDENT_OF_THE_SEAS, -1, WeaponCharges.POWERED_STAFF_ANIMATION, 0, true, -1, false);
		s.onWeaponTick(ItemID.TRIDENT_OF_THE_SEAS, -1, WeaponCharges.POWERED_STAFF_ANIMATION, 0, true, -1, false);
		// Two charges at 200 + 80 + 5 * 5 + 10 each.
		assertEquals(630.0, s.supplies().costTotal(), 1e-6);
		assertEquals(2, s.weaponCharges().attacks());
		// Scales put into a weapon are not used until it fires.
		s.onSupplies(Map.of(ItemID.TRIDENT_OF_THE_SEAS, 1, ItemID.ZULRAHS_SCALES, 0));
		assertEquals(630.0, s.supplies().costTotal(), 1e-6);
	}
}

package com.slayercompanion.session;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.ItemID;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class WeaponChargesTest
{
	private static final int NO_CAPE = -1;
	private static final int CAST = WeaponCharges.POWERED_STAFF_ANIMATION;

	private WeaponCharges w;

	@Before
	public void setUp()
	{
		w = new WeaponCharges();
	}

	/** One tick where {@code weapon}'s player started {@code animation} (no graphic). */
	private Map<Integer, Double> animate(int weapon, int animation)
	{
		return w.onTick(weapon, NO_CAPE, animation, 0, true, -1, false);
	}

	private static Map<Integer, Double> use(int... idQty)
	{
		Map<Integer, Double> m = new HashMap<>();
		for (int i = 0; i < idQty.length; i += 2)
		{
			m.put(idQty[i], (double) idQty[i + 1]);
		}
		return m;
	}

	private static void assertUse(Map<Integer, Double> expected, Map<Integer, Double> actual)
	{
		assertEquals(expected.keySet(), actual.keySet());
		expected.forEach((id, qty) -> assertEquals("item " + id, qty, actual.get(id), 1e-9));
	}

	@Test
	public void nothingCountsBeforeTheFirstKill()
	{
		assertTrue(animate(ItemID.TRIDENT_OF_THE_SEAS, CAST).isEmpty());
		w.onKill(1);
		assertFalse(animate(ItemID.TRIDENT_OF_THE_SEAS, CAST).isEmpty());
	}

	@Test
	public void tridentOfTheSeasChargeIsRunesAndCoins()
	{
		w.onKill(1);
		Map<Integer, Double> seas = use(ItemID.DEATH_RUNE, 1, ItemID.CHAOS_RUNE, 1, ItemID.FIRE_RUNE, 5,
			ItemID.COINS_995, 10);
		assertUse(seas, animate(ItemID.TRIDENT_OF_THE_SEAS, CAST));
		assertUse(seas, animate(ItemID.TRIDENT_OF_THE_SEAS_FULL, CAST));
		assertUse(seas, animate(ItemID.TRIDENT_OF_THE_SEAS_E, CAST));
	}

	@Test
	public void tridentOfTheSwampChargeUsesAScaleInsteadOfCoins()
	{
		w.onKill(1);
		Map<Integer, Double> swamp = use(ItemID.DEATH_RUNE, 1, ItemID.CHAOS_RUNE, 1, ItemID.FIRE_RUNE, 5,
			ItemID.ZULRAHS_SCALES, 1);
		assertUse(swamp, animate(ItemID.TRIDENT_OF_THE_SWAMP, CAST));
		assertUse(swamp, animate(ItemID.TRIDENT_OF_THE_SWAMP_E, CAST));
	}

	@Test
	public void sanguinestiChargeIsTwoBloodRunes()
	{
		w.onKill(1);
		assertUse(use(ItemID.BLOOD_RUNE, 2), animate(ItemID.SANGUINESTI_STAFF, CAST));
		assertUse(use(ItemID.BLOOD_RUNE, 2), animate(ItemID.HOLY_SANGUINESTI_STAFF, CAST));
	}

	@Test
	public void tumekensShadowCountsByItsCastGraphic()
	{
		w.onKill(1);
		assertTrue(animate(ItemID.TUMEKENS_SHADOW, CAST).isEmpty());
		assertUse(use(ItemID.SOUL_RUNE, 2, ItemID.CHAOS_RUNE, 5),
			w.onTick(ItemID.TUMEKENS_SHADOW, NO_CAPE, -1, 0, false, WeaponCharges.SHADOW_GRAPHIC, true));
		// The graphic still showing on a later tick is the same cast.
		assertTrue(w.onTick(ItemID.TUMEKENS_SHADOW, NO_CAPE, -1, 0, false, WeaponCharges.SHADOW_GRAPHIC, false)
			.isEmpty());
	}

	@Test
	public void revenantWeaponsUseOneEtherPerAttack()
	{
		w.onKill(1);
		assertUse(use(ItemID.REVENANT_ETHER, 1), animate(ItemID.ACCURSED_SCEPTRE, 1167));
		assertUse(use(ItemID.REVENANT_ETHER, 1), animate(ItemID.THAMMARONS_SCEPTRE_A, 1167));
		assertUse(use(ItemID.REVENANT_ETHER, 1), animate(ItemID.WEBWEAVER_BOW, 426));
		assertUse(use(ItemID.REVENANT_ETHER, 1), animate(ItemID.URSINE_CHAINMACE, 245));
	}

	@Test
	public void crystalWeaponsArePricedThroughTheTeleportSeed()
	{
		w.onKill(1);
		// 100 charges per shard, 150 shards per enhanced crystal teleport seed.
		Map<Integer, Double> perShot = Map.of(ItemID.ENHANCED_CRYSTAL_TELEPORT_SEED, 1 / 15000.0);
		assertUse(perShot, animate(ItemID.BOW_OF_FAERDHINEN, 426));
		assertUse(perShot, animate(ItemID.CRYSTAL_BOW, 426));
		assertUse(perShot, animate(ItemID.BLADE_OF_SAELDOR, 390));
		// The corrupted bow never degrades.
		assertTrue(animate(ItemID.BOW_OF_FAERDHINEN_C, 426).isEmpty());
	}

	@Test
	public void scytheUsesBloodRunesAndAHundredthOfAVial()
	{
		w.onKill(1);
		Map<Integer, Double> m = Map.of(ItemID.BLOOD_RUNE, 2.0, ItemID.VIAL_OF_BLOOD, 0.01);
		assertUse(m, animate(ItemID.SCYTHE_OF_VITUR, 8056));
	}

	@Test
	public void onlyTheWeaponsOwnAttackAnimationCounts()
	{
		w.onKill(1);
		assertTrue("eating", animate(ItemID.TRIDENT_OF_THE_SEAS, 829).isEmpty());
		assertTrue("not a charged weapon", animate(ItemID.MAGIC_SHORTBOW, 426).isEmpty());
		assertTrue("nothing wielded", animate(-1, CAST).isEmpty());
		// The animation carrying on from an earlier tick is the same attack.
		assertTrue(w.onTick(ItemID.TRIDENT_OF_THE_SEAS, NO_CAPE, CAST, 5, false, -1, false).isEmpty());
	}

	@Test
	public void blowpipeCountsEachLoopOfItsAnimationAndUsesTwoThirdsOfAScale()
	{
		w.onKill(1);
		int anim = WeaponCharges.BLOWPIPE_ANIMATIONS.iterator().next();
		// The blowpipe loops one animation, so a new shot is frame 0 whether or not the animation was just set.
		assertUse(Map.of(ItemID.ZULRAHS_SCALES, 2 / 3.0), w.onTick(ItemID.TOXIC_BLOWPIPE, NO_CAPE, anim, 0, false, -1, false));
		assertTrue(w.onTick(ItemID.TOXIC_BLOWPIPE, NO_CAPE, anim, 4, false, -1, false).isEmpty());
		assertUse(Map.of(ItemID.ZULRAHS_SCALES, 2 / 3.0), w.onTick(ItemID.BLAZING_BLOWPIPE, NO_CAPE, anim, 0, true, -1, false));
		assertEquals(-1, w.dartId());
	}

	@Test
	public void blowpipeDartsAreCostedOnceTheTypeIsKnown()
	{
		w.onKill(1);
		int anim = WeaponCharges.BLOWPIPE_ANIMATIONS.iterator().next();
		w.onChatMessage("Darts: Dragon dart x 4,321. Scales: 5,000 (30.5%).");
		assertEquals(ItemID.DRAGON_DART, w.dartId());
		assertUse(Map.of(ItemID.ZULRAHS_SCALES, 2 / 3.0, ItemID.DRAGON_DART, 0.2),
			w.onTick(ItemID.TOXIC_BLOWPIPE, ItemID.MASORI_ASSEMBLER, anim, 0, true, -1, false));
		assertUse(Map.of(ItemID.ZULRAHS_SCALES, 2 / 3.0, ItemID.DRAGON_DART, 0.28),
			w.onTick(ItemID.TOXIC_BLOWPIPE, ItemID.AVAS_ACCUMULATOR, anim, 0, true, -1, false));
		assertUse(Map.of(ItemID.ZULRAHS_SCALES, 2 / 3.0, ItemID.DRAGON_DART, 1.0),
			w.onTick(ItemID.TOXIC_BLOWPIPE, NO_CAPE, anim, 0, true, -1, false));

		w.onChatMessage("Darts: None. Scales: 99 (0.6%).");
		assertEquals(-1, w.dartId());
	}

	@Test
	public void loadingDartsIntoTheBlowpipeTeachesTheDartType()
	{
		w.onCarried(Map.of(ItemID.TOXIC_BLOWPIPE, 1, ItemID.AMETHYST_DART, 500));
		w.onCarried(Map.of(ItemID.TOXIC_BLOWPIPE, 1, ItemID.AMETHYST_DART, 200));
		assertEquals(ItemID.AMETHYST_DART, w.dartId());
		// Darts going down without a blowpipe are not loaded into it.
		w.onCarried(Map.of(ItemID.RUNE_DART, 100));
		w.onCarried(Map.of(ItemID.RUNE_DART, 50));
		assertEquals(ItemID.AMETHYST_DART, w.dartId());
	}

	@Test
	public void resetWaitsForTheNextTasksFirstKill()
	{
		w.onKill(1);
		animate(ItemID.SANGUINESTI_STAFF, CAST);
		assertEquals(1, w.attacks());
		w.reset();
		assertEquals(0, w.attacks());
		assertTrue(animate(ItemID.SANGUINESTI_STAFF, CAST).isEmpty());
	}

	@Test
	public void materialsOnlyUsedForChargingAreKnown()
	{
		assertTrue(WeaponCharges.MATERIAL_IDS.contains(ItemID.ZULRAHS_SCALES));
		assertTrue(WeaponCharges.MATERIAL_IDS.contains(ItemID.REVENANT_ETHER));
		assertTrue(WeaponCharges.MATERIAL_IDS.contains(ItemID.VIAL_OF_BLOOD));
		assertFalse("runes are also cast", WeaponCharges.MATERIAL_IDS.contains(ItemID.BLOOD_RUNE));
		assertTrue(WeaponCharges.DART_IDS.contains(ItemID.DRAGON_DART));
		assertTrue(WeaponCharges.BLOWPIPE_IDS.contains(ItemID.TOXIC_BLOWPIPE));
	}
}

package com.slayercompanion.task;

