/** Sample domain objects shared by the view-model tests and the panel screenshot tool. */
final class Samples
{
	static final int SHARK = 385;
	static final int WHIP = 4151;

	private Samples()
	{
	}

	static class MutableClock extends Clock
	{
		Instant now = Instant.parse("2026-01-01T00:00:00Z");

		void advance(long seconds)
		{
			now = now.plus(Duration.ofSeconds(seconds));
		}

		@Override
		public ZoneId getZone()
		{
			return ZoneOffset.UTC;
		}

		@Override
		public Clock withZone(ZoneId zone)
		{
			return this;
		}

		@Override
		public Instant instant()
		{
			return now;
		}
	}

	static SlayerTask fireGiants()
	{
		SlayerTask t = new SlayerTask();
		t.setId("fire-giants");
		t.setName("Fire giants");
		t.setMonsterIds(Arrays.asList(2075, 7252));
		return t;
	}

	static SlayerTask needs(String taskName, String itemName, int... ids)
	{
		SlayerTask t = new SlayerTask();
		t.setId(taskName.toLowerCase().replace(' ', '-'));
		t.setName(taskName);
		ItemNeed need = new ItemNeed();
		need.setName(itemName);
		List<Integer> list = new ArrayList<>();
		for (int id : ids)
		{
			list.add(id);
		}
		need.setItemIds(list);
		t.setRequiredItems(Collections.singletonList(need));
		return t;
	}

	static CurrentTask task(SlayerTask t, int remaining, int initial)
	{
		return new CurrentTask(t, remaining, initial, Optional.empty(), Optional.of("chaeldar"), 49);
	}

	static Monster fireGiant()
	{
		Monster m = new Monster();
		m.setId(2075);
		m.setName("Fire giant (Level 86)");
		m.setHitpoints(111);
		m.setSlayerXp(111);
		m.setMaxHit(11);
		m.setElementalWeakness("water");
		m.setElementalWeaknessPercent(50);
		m.setAttackStyles(Collections.singletonList("melee"));
		Map<String, Integer> def = new HashMap<>();
		def.put("stab", 65);
		def.put("slash", 63);
		def.put("crush", 70);
		m.setDefensiveBonuses(def);
		Drop d = new Drop();
		d.setItemId(1333);
		d.setName("Rune scimitar");
		d.setRate(1.0 / 128);
		d.setQtyMin(1);
		d.setQtyMax(1);
		m.setDrops(Collections.singletonList(d));
		return m;
	}

	static Equipment item(int id, String name, String slot)
	{
		Equipment e = new Equipment();
		e.setItemId(id);
		e.setName(name);
		e.setSlot(slot);
		return e;
	}

	static Loadout meleeLoadout()
	{
		Map<String, Equipment> slots = new HashMap<>();
		slots.put("weapon", item(WHIP, "Abyssal whip", "weapon"));
		slots.put("shield", item(12954, "Dragon defender", "shield"));
		slots.put("head", item(11864, "Slayer helmet", "head"));
		slots.put("body", item(10551, "Fighter torso", "body"));
		slots.put("legs", item(21304, "Obsidian platelegs", "legs"));
		slots.put("neck", item(6585, "Amulet of fury", "neck"));
		return new Loadout(slots, Style.MELEE, "slash", null);
	}

	static Location location(String id, String name, List<String> tags)
	{
		Location l = new Location();
		l.setId(id);
		l.setName(name);
		l.setTaskId("fire-giants");
		l.setMonsterId(2075);
		l.setTags(tags);
		return l;
	}

	static RankedLocation ranked(Location l, boolean usable, String lockedReason, boolean safespot, double travel,
		double xp, double gp, boolean recommended, String why)
	{
		RankedLocation r = new RankedLocation();
		r.setLocation(l);
		r.setUsable(usable);
		r.setLockedReason(lockedReason);
		r.setHasSafespot(safespot);
		r.setTravelSeconds(travel);
		r.setXpPerHour(xp);
		r.setGpPerHour(gp);
		r.setRecommended(recommended);
		r.setWhy(why);
		return r;
	}

	/** Fire giants: Waterfall (recommended, safespot), Catacombs, Stronghold, Karuulm (locked). */
	static List<RankedLocation> fireGiantRanking()
	{
		return Arrays.asList(
			ranked(location("fire-giants--waterfall-dungeon", "Waterfall Dungeon",
				Arrays.asList("Single-combat", "Safespot", "Cannon allowed")),
				true, null, true, 80, 31_000, 180_000, true, "Safespot · Closest"),
			ranked(location("fire-giants--catacombs-of-kourend", "Catacombs of Kourend",
				Arrays.asList("Multi-combat", "Safespot", "Catacombs bonus drops")),
				true, null, false, 120, 39_000, 320_000, false, null),
			ranked(location("fire-giants--stronghold-slayer-cave", "Stronghold Slayer Cave",
				Arrays.asList("Single-combat", "Safespot", "Cannon allowed")),
				true, null, false, 110, 29_000, 165_000, false, null),
			ranked(location("fire-giants--karuulm-slayer-dungeon", "Karuulm Slayer Dungeon",
				Arrays.asList("Single-combat", "Safespot", "Cannon allowed")),
				false, "Needs boots of stone", false, 120, 30_000, 170_000, false, null));
	}
}

package com.slayercompanion.ui;

import java.awt.image.BufferedImage;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;
import javax.imageio.ImageIO;

/** Item pictures for headless renders, from src/test/resources/icons/{id}.png; null when there is no file. */
final class TestIcons implements IconSource
{
	private final Map<Integer, BufferedImage> cache = new HashMap<>();

	@Override
	public BufferedImage icon(int itemId)
	{
		return cache.computeIfAbsent(itemId, id ->
		{
			try (InputStream in = TestIcons.class.getResourceAsStream("/icons/" + id + ".png"))
			{
				return in == null ? null : ImageIO.read(in);
			}
			catch (Exception e)
			{
				return null;
			}
		});
	}
}

package com.slayercompanion.ui;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import org.junit.Test;

public class WhereToGoModelTest
{
	@Test
	public void noTask()
	{
		WhereToGoModel m = WhereToGoModel.noTask();
		assertTrue(m.isNoTask());
		assertEquals("No slayer task", m.getMessage());
	}

	@Test
	public void topPickIsRecommendedWithWhyAndSelectedByDefault()
	{
		WhereToGoModel m = WhereToGoModel.build(Samples.fireGiantRanking(), null);
		WhereToGoModel.Row top = m.getRows().get(0);
		assertTrue(top.isRecommended());
		assertEquals("Safespot · Closest", top.getWhy());
		assertTrue(top.isSelected());
		assertEquals("fire-giants--waterfall-dungeon", m.getSelectedId());
		assertEquals("~1m 20s away", top.getTravel());
		assertEquals("~2m", m.getRows().get(1).getTravel());
	}

	@Test
	public void explicitSelectionWins()
	{
		WhereToGoModel m = WhereToGoModel.build(Samples.fireGiantRanking(), "fire-giants--catacombs-of-kourend");
		assertFalse(m.getRows().get(0).isSelected());
		assertTrue(m.getRows().get(1).isSelected());
		assertEquals("fire-giants--catacombs-of-kourend", m.getSelectedId());
	}

	@Test
	public void unknownSelectionFallsBackToTopPick()
	{
		assertEquals("fire-giants--waterfall-dungeon",
			WhereToGoModel.effectiveSelection(Samples.fireGiantRanking(), "gone"));
		assertNull(WhereToGoModel.effectiveSelection(Collections.emptyList(), null));
	}

	@Test
	public void noKnownSafespotTagWhereNone()
	{
		WhereToGoModel m = WhereToGoModel.build(Samples.fireGiantRanking(), null);
		List<String> top = m.getRows().get(0).getTags().stream().map(WhereToGoModel.Tag::getText).collect(Collectors.toList());
		assertEquals("Safespot", top.get(0));
		List<String> second = m.getRows().get(1).getTags().stream().map(WhereToGoModel.Tag::getText).collect(Collectors.toList());
		assertEquals("No known safespot", second.get(0));
		// The data's own "Safespot" tag is replaced by what the safespot store knows.
		assertEquals(1, second.stream().filter(t -> t.contains("afespot")).count());
		assertTrue(second.contains("Bonus drops"));
	}

	@Test
	public void barsScaleToMaxAcrossUsableRows()
	{
		WhereToGoModel m = WhereToGoModel.build(Samples.fireGiantRanking(), null);
		WhereToGoModel.Row catacombs = m.getRows().get(1);
		assertEquals(1.0, catacombs.getXpFraction(), 1e-9);
		assertEquals(1.0, catacombs.getGpFraction(), 1e-9);
		assertEquals(31.0 / 39.0, m.getRows().get(0).getXpFraction(), 1e-9);
		assertEquals("31k", m.getRows().get(0).getXpText());
		assertEquals("180k", m.getRows().get(0).getGpText());
		assertTrue(m.getNote().contains("estimates"));
	}

	@Test
	public void lockedRowIsGreyWithReason()
	{
		WhereToGoModel m = WhereToGoModel.build(Samples.fireGiantRanking(), null);
		WhereToGoModel.Row locked = m.getRows().get(3);
		assertTrue(locked.isLocked());
		assertEquals("—", locked.getTravel());
		assertEquals(Collections.singletonList("Needs boots of stone"),
			locked.getTags().stream().map(WhereToGoModel.Tag::getText).collect(Collectors.toList()));
	}

	@Test
	public void actionMessages()
	{
		assertEquals("Shortest Path plugin not installed", WhereToGoModel.takeMeThereMessage(false));
		assertNull(WhereToGoModel.takeMeThereMessage(true));
		assertEquals("Copied 3 safespots", WhereToGoModel.copiedMessage(3));
	}

	@Test
	public void dataTagsGetShortTextAndColour()
	{
		assertEquals(new WhereToGoModel.Tag("Multi", WhereToGoModel.TagKind.BLUE), WhereToGoModel.tag("Multi-combat"));
		assertEquals(new WhereToGoModel.Tag("Bonus drops", WhereToGoModel.TagKind.GOLD),
			WhereToGoModel.tag("Catacombs bonus drops"));
		assertEquals(new WhereToGoModel.Tag("Cannon", WhereToGoModel.TagKind.NORMAL), WhereToGoModel.tag("Cannon allowed"));
		assertEquals(WhereToGoModel.TagKind.RISK, WhereToGoModel.tag("Wilderness").getKind());
		assertEquals(new WhereToGoModel.Tag("Single-combat", WhereToGoModel.TagKind.NORMAL),
			WhereToGoModel.tag("Single-combat"));
	}

	@Test
	public void headerShowsTaskAndSortOrder()
	{
		WhereToGoModel m = WhereToGoModel.build(Samples.fireGiantRanking(), null, "Fire giants",
			com.slayercompanion.gear.Style.MELEE);
		assertEquals("Fire giants", m.getTitle());
		assertEquals("Melee · sorted by travel time", m.getSubtitle());
		assertEquals("Ranged · safespots first, then travel time",
			WhereToGoModel.subtitle(com.slayercompanion.gear.Style.RANGED));
		assertNull(WhereToGoModel.build(Samples.fireGiantRanking(), null).getTitle());
	}
}
